(window.GIM_TS=window.GIM_TS||{})["Zevachim.8"]={"from":192,"a":[["\u0003איכא\u0004 \u0005[יש]\u0006 תנא \u0003דנפקא ליה\u0004 \u0005[שיוצא\u0006 נלמד \u0005לו]\u0006 דין זה של אכילת שלמי ציבור לזכרי כהונה בלבד \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003ואיכא\u0004 \u0005[ויש]\u0006 תנא \u0003דנפקא ליה\u0004 \u0005[שיוצא\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מהכא\u0004 \u0005[מכאן].\u0006","וממשיכים בדברים הנלמדים ממלות הפסוק \"זאת התורה לעולה ולמנחה ולחטאת ולאשם ולמילואים ולזבח השלמים\" (ויקרא ז, לז): \u0003\"חטאת\"\u0004 — מה למדים ממנה? \u0003מה חטאת מתקדשת,\u0004 כלומר, מקדשת דברים שנגעו בה להיות כמותה \u0003בבלוע,\u0004 במקום שנבלע ממנה, \u0003אף כל\u0004 הקרבנות שהוזכרו בפסוק \u0003מתקדשת בבלוע.\u0004","\u0003\"אשם\"\u0004 — מה מלמדנו? \u0003מה אשם אין שפיר\u0004 (שק ההריון ובו העובר) \u0003ושליא\u0004 (דרכה מקבל העובר את מזונו) \u0003קדוש בו\u0004, שהרי האשם הוא תמיד זכר ואי אפשר שיהיו בו שפיר ושליא, \u0003אף כל\u0004 קדשים \u0003אין שפיר ושליא\u0004 שנמצאו במעי הבהמה \u0003קדוש בו.\u0004 ומעירים: מכאן ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 תנא זה כי \u0003וולדות קדשים בהוייתן,\u0004 כלומר, רק בשעת לידתן \u0003הן קדושים\u0004 ולא כשהם מצויים במעי האם. \u0003ו\u0004כן סבור הוא התנא כי \u0003דנין\u0004 דינו של דבר ש\u0003אפשר מ\u0004דינו של דבר \u0003שאי אפשר,\u0004 שהרי הוא למד דינם של שאר קרבנות שהם נקבות שאפשר שיהא בהן שפיר ושליה, מאשם שאי אפשר שיהיה בו דבר זה.","ושבים אל הלימודים הנלמדים ממקרא זה, \u0003\"מלואים\"\u0004 — מה נלמד מכאן? \u0003מה מלואים,\u0004 כלומר, אילי המילואים והלחם שעימם, שהוקרבו במשכן בשבעת ימי המילואים, וניתנו לכהנים לאכילה — \u0003מותריהן בשריפה,\u0004 שנאמר: \"ואם יותר מבשר המילואים ומן הלחם עד הבקר ושרפת את הנותר באש\" (שמות כט, לד), \u0003ואין בעלי חיים ב\u0004כלל \u0003מותריהן\u0004 הטעונים שריפה, שהרי לא נצטוו לשרוף אלא בשר ולחם, \u0003אף כל\u0004 קדשים \u0003מותריהן בשריפה ואין בעלי חיים ב\u0004כלל \u0003מותריהן.\u0004 וכגון שהפריש שני קרבנות לאחריות, שאם יאבד אחד יתכפר בשני, וקרב אחד מהם — אין ממיתים את השני ושורפים את בשרו.","\u0003\"שלמים\"\u0004 — למדים מהם: \u0003מה שלמים\u0004 שנכתב בהם דין פיגול, יש בהם \u0003מפגלין ומתפגלין,\u0004 \u0003אף כל\u0004 קדשים \u0003מפגלין ומתפגלין.\u0004","וממשיכים לדון בפסוק \"זאת התורה לעולה למנחה ולחטאת ולאשם ולמילואים ולזבח השלמים\" (ויקרא ז, לז). \u0003במתניתא תנא משמיה\u0004 \u0005[בברייתא שנה משמו]\u0006 של \u0003ר' עקיבא\u0004 דרשה דומה על כתוב זה, אך באופן אחר: \u0003\"מנחה\"\u0004 — \u0003מה מנחה מתקדשת בבלוע,\u0004 שמה שנגע במנחה ובלע ממנה נעשה כמותה (שנאמר: \"כל אשר יגע בהם יקדש\", ויקרא ו, יא), \u0003אף כל\u0004 קרבנות \u0003מתקדשת בבלוע.\u0004","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 דין זה ב\u0003מנחה ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 דין זה גם ב\u0003חטאת\u0004 (כפי ששנינו בראש עמוד זה), \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003מנחה,\u0004 הייתי אומר \u0003דאיידי דרכיכא מיבלעא\u0004 \u0005[מתוך ש\u0006היא \u0005רכה\u0006 היא \u0005נבלעת],\u0006 \u0003אבל חטאת אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא. ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003חטאת,\u0004 הייתי אומר משום \u0003דקריר\u0004 \u0005[ש\u0006היא \u0005מחלחלת]\u0006 שיש עליה שומן הרבה, והוא נספג במה שנוגע בה, \u0003אבל מנחה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","ומה שהוזכרה \u0003\"חטאת\"\u0004 בא ללמד: \u0003מה חטאת אינה באה אלא מן החולין, ו\u0004מקריבים אותה דווקא \u0003ביום, ובידו הימנית, אף כל\u0004 קדשים \u0003אינה באה אלא מן החולין וביום ובידו הימנית.\u0004 ושואלים: \u0003וחטאת מנלן\u0004 \u0005[מנין לנו]\u0006 שאינה באה אלא מן החולין? \u0003אמר רב חסדא, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"והקריב אהרן את פר החטאת אשר לו\"\u0004 (ויקרא טז, יא), ללמדנו שפר זה צריך להיות רק \u0003משלו,\u0004 \u0003ולא משל ציבור, ולא משל\u0004 מעות שחיללו עליהם \u0003מעשר\u0004 שני.","ושואלים: לשם מה היה צריך ללמוד מחטאת דין זה שהיא נעשית \u0003ביום?\u0004 הלוא דבר זה \u0003מ\"ביום צותו\"\u0004 (ויקרא ז, לח) \u0003נפקא\u0004 \u0005[יוצא],\u0006 וביחס לכל הקרבנות! ומשיבים: אכן, \u0003כדי נסבה\u0004 \u0005[לחינם הביאה],\u0006 כלומר, באמת, לא נלמד מכאן, והובא אגב ההלכות האחרות.","ועוד שואלים: והרי גם מה שתנא זה למד מחטאת, שעבודת הקרבנות נעשית \u0003בידו הימנית, מ\u0004דברי \u0003רבה בר בר חנה נפקא\u0004 \u0005[יוצא].\u0006 ש\u0003אמר רבה בר בר חנה אמר\u0004 \u0003ריש לקיש: כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו \u0003אצבע וכהונה,\u0004 כלומר, או שנאמר שהכהן עושה מעשה זה \u0003אינו אלא\u0004 ביד \u0003ימין,\u0004 ולמדים דבר זה מדין המצורע שמפורש בו דבר זה \"וטבל הכהן את אצבעו הימנית\" (ויקרא יד, טז)! ומשיבים: אכן, \u0003כדי נסבה\u0004 \u0005[לחינם הביאה],\u0006 ולא מכאן למדנו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' שמעון,\u0004 ש\u0003אמר:\u0004 במקום שנאמר בו \u0003אצבע לא בעיא\u0004 \u0005[אינו צריך]\u0006 שייאמר בה \u0003כהונה,\u0004 אבל במקום שנאמרה \u0003כהונה\u0004 הריהי \u0003בעיא\u0004 \u0005[צריכה]\u0006 שייאמר גם \u0003אצבע,\u0004 כדי לומר שאין עושים זאת אלא בימין. ובקרבנות האמורים בפסוק זה הוזכר כהן ולא אצבע, והם נלמדים איפוא מחטאת.","ומה שנאמר \u0003\"אשם\"\u0004 למדים ממנו: \u0003מה אשם עצמותיו מותרין\u0004 ואין בהם קדושה, ויכולים להשתמש בהן לכל צורך — \u0003אף כל\u0004 קרבן \u0003עצמותיו מותרין.\u0004","\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004"],["\u0003דם חטאת למטה ודם עולה למעלה,\u0004 כלומר, ניתז על הבגד דם חטאת מתחילה ונספג בו, ואחר כך ניתז עליו דם עולה — בגד זה \u0003טעון כיבוס.\u0004","ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: דם עולה למטה\u0004 שניתז עליו תחילה ונספג בו, \u0003ודם חטאת למעלה, מהו\u0004 הדין? האם החובה לכבס את הבגד מדם החטאת שניתז עליו \u0003משום נוגע הוא, והא\u0004 \u0005[והרי]\u0006 דם החטאת \u0003נוגע\u0004 בבגד. \u0003או דלמא\u0004 \u0005[שמא]\u0006 חובת הכיבוס \u0003משום בלוע\u0004 של דם החטאת \u0003הוא, והא\u0004 \u0005[והרי]\u0006 \u0003לא בלע\u0004 הבגד מדם החטאת, שהרי כבר נבלע שם דם העולה, ושוב אינו סופג דם אחר? \u0003הדר פשטה\u0004 \u0005[חזר ופתרה]\u0006 רבא את השאלה שלו: \u0003אין טעונין כיבוס.\u0004","ובנושא דומה, לענין טבילה של בגד שנטמא, \u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 שכתם \u0003דם על בגדו\u0004 הריהו \u0003חוצץ\u0004 ולא עלתה לבגד הטבילה. \u0003ואם טבח\u0004 (שוחט) \u0003הוא\u0004 — \u0003אינו חוצץ,\u0004 משום שדרכו שבגדיו מלוכלכים בדם, וכל דבר שאין אדם מקפיד עליו אינו חוצץ. וכן \u0003רבב\u0004 (שומן) \u0003על בגדו\u0004 — הרי זה \u0003חוצץ\u0004 לענין טבילה, \u0003ואם מוכר רבב הוא\u0004 — \u0003אינו חוצץ.\u0004 ועל בסיס הלכות אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 מי שהיו כתמי \u0003דם ורבב על בגדו, מהו?\u0004 ותוהים: מה מקום לשאלה זו?","שהרי \u0003אם טבח הוא, תיפוק ליה\u0004 \u0005[תצא לו]\u0006 שיש כאן חציצה \u0003משום רבב,\u0004 שהרי אין הטבח רגיל בכך! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מוכר רבב הוא, תיפוק ליה\u0004 \u0005[תצא לו]\u0006 שיש כאן חציצה \u0003משום דם,\u0004 שאין מוכר רבב רגיל בו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו אלא באדם \u0003דעביד הא והא\u0004 \u0005[שעושה זה וזה],\u0006 שהוא גם טבח וגם מוכר רבב, והשאלה היא: האם דווקא \u0003אחדא לא קפיד\u0004 \u0005[על\u0006 חציצה \u0005אחת אין\u0006 אדם \u0005מקפיד],\u0006 אך \u0003אתרתי קפיד\u0004 \u0005[על שתים מקפיד],\u0006 והרי זו חציצה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כמו שאין מקפיד על חציצה אחת, \u0003אתרתי נמי לא קפיד\u0004 \u0005[על שתים גם כן אין\u0006 אדם \u0005מקפיד]?\u0006 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","","\u0003טבול יום\u0004 כהן שהיה טמא וטבל מטומאתו, ועדיין לא העריבה השמש, ולפיכך אינו טהור לגמרי ואסור לאכול מן הקדשים, \u0003ומחוסר כיפורים\u0004 מי שהיה חייב להביא קרבן כפרה (כגון מי שנתרפא מזובו או מצרעתו) שאף שכבר טבל ביום השביעי לטהרתו, והעריב שמשו, הריהו אסור לאכול מן הקדשים עד שיקרב קרבנו ביום השמיני — \u0003אינן חולקין\u0004 באותה שעה \u0003בקדשים\u0004 אינם מקבלים חלק לעצמם כשאר אנשי בית אב של אותו יום, על מנת \u0003לאכול\u0004 אותם \u0003לערב,\u0004 אף שבערב הריהם כבר טהורים לגמרי, ומותרים באכילת קדשים.","כהן שהוא \u0003אונן\u0004 שמת באותו יום אחד מן הקרובים שהוא חייב להתאבל עליהם, ואסור לאכול בקדשים — \u0003נוגע\u0004 אמנם בבשר קדשים, שהרי אינו טמא, \u0003ו\u0004אולם \u0003אינו מקריב\u0004 אותם, \u0003ו\u0004כן \u0003אינו חולק\u0004 עם שאר הכהנים על מנת \u0003לאכול לערב.\u0004","כהנים \u0003בעלי מומין, בין\u0004 שהם \u0003בעלי מומין עוברין\u0004 (שעשויים להתרפא) \u0003בין בעלי מומין קבועין\u0004 — \u0003חולקין\u0004 עם אחיהם הכהנים בקרבנות \u0003ואוכלין\u0004 מהם, \u0003אבל לא מקריבין.\u0004","וכלל הוא: \u0003כל\u0004 כהן \u0003שאינו ראוי לעבודה\u0004 באותו יום — \u0003אינו חולק בבשר, וכל שאין לו\u0004 חלק \u0003בבשר\u0004 הקרבנות — \u0003אין לו\u0004 גם חלק \u0003בעורות\u0004 הקרבנות, הניתנים גם הם לכהנים.","\u0003 אפילו\u0004 היה הכהן \u0003טמא בשעת זריקת דמים\u0004 של הקרבן, ואחרי כן נטהר, \u0003ו\u0004הוא \u0003טהור בשעת הקטר חלבים\u0004 של קרבן זה — בכל זאת \u0003אינו חולק בבשר, ש\u0004כן \u0003נאמר: \"המקריב את דם השלמים [ואת החלב מבני אהרן] לו (יהיה)\u0004 \u0003[תהיה שוק הימין למנה]\"\u0004 (ויקרא ז, לג), משמע שמי שלא מקריב (זורק) את הדם אינו חולק בבשר."],["שנינו במשנה שהכהנים שאינם ראויים לעבודה אינם חולקים בקדשים עם אחיהם. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו\u0006\u0005]?\u0006 \u0003אמר ריש לקיש:\u0004 שכן \u0003אמר קרא\u0004 \u0005[המקרא\u0006\u0005]\u0006 בדין קרבן החטאת: \u0003\"הכהן המחטא אתה יאכלנה\"\u0004 (ויקרא ו, יט), ומכאן למדים: ה\u0003כהן המחטא\u0004 (העושה את עבודת החטאת) — \u0003יאכל\u0004 מבשרה, וזה \u0003שאינו מחטא\u0004 — \u0003אינו אוכל.\u0004","ושואלים: \u0003וכללא\u0004 \u0005[וכלל\u0006\u0005]\u0006 \u0003הוא\u0004 זה? \u0003והרי משמרה כולה\u0004 של הכהנים, העובדים משך אותו שבוע במקדש, ש\u0003אין מחטאין,\u0004 שהרי כהן אחד הוא שזורק את דם החטאת המסויימת, \u0003ו\u0004בכל זאת כל כהני המשמר \u0003אוכלין\u0004 מבשרה! ומשיבים: כל כהן ה\u0003ראוי לחיטוי\u0004 לזריקת הדם \u0003קאמרינן\u0004 \u0005[אומרים אנו\u0006\u0005],\u0006 שיאכלנה.","ומקשים עוד: ו\u0003הרי\u0004 כהן \u0003קטן, אינו ראוי לחיטוי,\u0004 שאינו רשאי עדיין לעבוד עבודה, \u0003ו\u0004בכל זאת הריהו \u0003אוכל\u0004 מהקדשים! אלא כך צריך לומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יאכלנה\"\u0004 האמור בכתוב זה? כוונתו \u0003יחלקנה,\u0004 שיש לו חלק בקרבנות הללו לעצמו. והכלל הוא איפוא: כל כהן ש\u0003ראוי לחיטוי\u0004 — \u0003חולק,\u0004 וכל \u0003שאינו ראוי לחיטוי,\u0004 ואף קטן בכלל זה — \u0003אינו חולק,\u0004 אף שמותר לו לאכול מהקדשים.","ומקשים: \u0003הרי\u0004 כהן \u0003בעל מום,\u0004 ש\u0003אינו ראוי לחיטוי ו\u0004בכל זאת \u0003חולק\u0004 (כפי ששנינו במשנתנו)! ומשיבים: \u0003בעל מום רחמנא רבייה\u0004 \u0005[התורה ריבתה אותו\u0006\u0005],\u0006 שכן נאמר בפרשה זו: \u0003\"כל זכר בכהנים\u0004 יאכל אותה\" (ויקרא ו, כב) — \u0003לרבות בעל מום.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 ריבוי זה באופן אחר: \u0003\"כל זכר\"\u0004 — \u0003לרבות טבול יום\u0004 שיחלוק בקדשים, ומדוע בעל מום? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006\u0005]\u0006 ש\u0003בעל מום הוה ליה לרבויי\u0004 \u0005[היה לו לרבות\u0006\u0005],\u0006 \u0003שכן\u0004 הוא \u0003אוכל\u0004 בקדשים. מה שאין כן טבול יום, שהוא טמא ואסור לגעת ולאכול בקדשים.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך\u0006\u0005],\u0006 \u0003טבול יום הוה ליה לרבויי\u0004 \u0005[היה לו לרבות],\u0006 \u0003דלאורתא מיחזא חזי\u0004 \u0005[ש\u0006כן \u0005לערב יהיה ראוי\u0006\u0005]\u0006 לעבודה. מה שאין כן בעל מום! ומשיבים: \u0003השתא מיהא הא לא חזי\u0004 \u0005[עכשיו על כל פנים הרי\u0006 הטבול יום \u0005אינו ראוי\u0006\u0005]\u0006 לכך.","\u0003רב יוסף אמר\u0004 באופן אחר מדוע אין לרבות טבול יום מ\"כל זכר יאכלנה\": \u0003מכדי\u0004 \u0005[הואיל\u0006\u0005]\u0006 ואמרנו כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יאכלנה\"? יחלקנה,\u0004 אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה\u0006 במפורש\u0005]\u0006 \u0003\"יחלקנה\", מאי\u0004 \u0005[מה\u0006\u0005]\u0006 הטעם לשימוש במלה \u0003\"יאכלנה\"? שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כך: מי ש\u0003ראוי לאכילה\u0004 (בעל מום) — \u0003חולק\u0004 בקדשים, ומי \u0003שאינו ראוי לאכילה,\u0004 כגון טבול יום — \u0003אינו חולק\u0004 בקדשים.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003ריש לקיש: בעל מום והוא טמא,\u0004 כגון טבול יום, \u0003מהו\u0004 דינו לענין \u0003שיחלקו לו?\u0004 וצדדי השאלה, האם \u0003כיון דלא חזי\u0004 \u0005[שאינו ראוי\u0006\u0005]\u0006 להקריב כבעל מום, \u0003ו\u0004בכל זאת \u0003רחמנא רבייה\u0004 \u0005[התורה ריבתה אותו\u0006\u0005]\u0006 שחולק בקדשים, אם כן \u0003לא שנא\u0004 \u0005[אינו שונה\u0006\u0005]\u0006 דינו בכל מצביו: \u0003מה לי\u0004 אם הוא בעל מום ו\u0003טמא, מה לי\u0004 אם הוא \u0003בעל מום\u0004 בלבד, שהרי מכל מקום כבעל מום אין הוא יכול לעבוד, ובכל זאת יש לו חלק. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 יש לומר כי רק כהן ה\u0003ראוי לאכילה\u0004 בשעת העבודה — \u0003חולק,\u0004 וכל \u0003שאינו ראוי לאכילה\u0004 — \u0003אינו חולק.\u0004 ואף כהן זה, בהיותו טמא אינו ראוי לאכילה, ואינו חולק?","\u0003אמר רבה: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]\u0006 פתרון לדבר ממה ששנינו: \u0003כהן גדול\u0004 העומד בבית המקדש ומת עליו אחד מן הקרובים שמתאבלים עליהם, הריהו \u0003מקריב\u0004 קרבנות, אף שהוא \u0003אונן\u0004 (אבל, ביום מיתת קרובו), אבל \u0003אינו אוכל\u0004 מן הקדשים, \u0003ואינו חולק\u0004 בהם על מנת \u0003לאכול\u0004 מהם \u0003לערב. שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכדי לזכות בחלוקה בקדשים, כהן ה\u0003ראוי לאכילה בעינן\u0004 \u0005[צריכים אנו\u0006\u0005].\u0006 ואף כהן בעל מום שהוא טמא, כיון שבשעת החלוקה אינו ראוי לאכילה, אינו זכאי לחלק. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","ועוד בדיני חלוקה בקדשים \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב אושעיא:\u0004 כהן \u0003טמא, בקרבנות ציבור\u0004 שהותר להקריבם בטומאה, \u0003מהו\u0004 \u0003שיחלקו לו\u0004 חלק עם שאר אחיו הכהנים על מנת לאכול מבשרם בערב, לכשיטהר? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו\u0006\u0005]:\u0006 \"הכהן \u0003המחטא\u0004 אותה\" \u0003אמר רחמנא\u0004 \u0005[אמרה התורה\u0006\u0005],\u0006 שכל שראוי לחיטוי זכאי לחלוקה בקדשים (כמובא למעלה), \u0003והאי נמי\u0004 \u0005[וזה גם כן]\u0006 בכלל \u0003מחטא הוא,\u0004 שהרי בקרבנות ציבור כאשר כל הציבור טמאים, עובדים גם כהנים טמאים. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 כפי שאמרנו, כלל הוא: כהן ה\u0003ראוי לאכילה\u0004 בשעת העבודה — \u0003חולק,\u0004 זה \u0003שאין ראוי לאכילה\u0004 — \u0003אינו חולק.\u0004 וכיון שבהיותו טמא אין הוא ראוי לאכול קרבנות אלה, אף אינו זכאי בחלוקה בהם?","\u0003אמר רבינא\u0004 בפתרון בעיה זו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006\u0005]:\u0006 ראיה ממה ששנינו כי \u0003כהן גדול מקריב אונן, ואינו אוכל ואינו חולק לאכול לערב, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכדי לזכות בחלוקה בקדשים, כהן ה\u0003ראוי לאכילה\u0004 בשעת עבודה \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005].\u0006 ואילו כהן זה כיון שאינו ראוי לאכול מקרבנות הציבור באותה שעה, אינו זכאי לחלוק בהם. מסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכך הוא הדין.","שנינו במשנה כי כהן שהוא \u0003אונן\u0004 — \u0003נוגע\u0004 (בקדשים) \u0003ואינו מקריב\u0004, ואינו חולק לאכול בערב. ותוהים: האם אכן \u0003אונן נוגע? ורמינהי\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו במשנה במסכת חגיגה: \u0003אונן\u0004 שעבר זמן אנינותו, \u0003ומחוסר כיפורים\u0004 שקרב קרבן כפרתו, \u0003צריכין טבילה לקודש.\u0004 משמע שהאונן שלא טבל אסור לו לנגוע בקדשים!","\u0003אמר ר' אמי אמר ר' יוחנן, לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005]:\u0006 \u0003כאן\u0004 (במשנתנו) ששנינו שאונן מותר בנגיעה בקדשים, מדובר \u0003בשטבל\u0004 בתוך יום אנינותו. \u0003כאן\u0004 (במסכת חגיגה) מדובר \u0003בשלא טבל,\u0004 ולכן אסור בנגיעה.","ושואלים על כך: \u0003וכי\u0004 \u0005[ו\u0006אף \u0005כאשר]\u0006 \u0003טבל מאי הוי\u0004 \u0005[מה נהיה\u0006 בכך\u0005]?\u0006 \u0003הא הדרא עליה\u0004 \u0005[הרי חוזרת עליו\u0006\u0005]\u0006 \u0003אנינות.\u0004 שכן \u0003אמר רבה בר רב הונא: אונן שטבל\u0004 בתוך יום אנינותו — \u0003אנינותו חוזרת עליו!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה\u0006\u0005]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו במסכת חגיגה, שצריך טבילה — מדובר במקרה \u0003דאסח דעתיה\u0004 \u0005[שהסיח דעתו]\u0006 מלשמור עצמו בטהרה, ולכן אינו רשאי לנגוע בקדשים, שמא נטמא. \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמותר בנגיעה — מדובר במקרה ש\u0003לא אסח דעתיה\u0004 \u0005[הסיח דעתו\u0006\u0005].\u0006","ותוהים: אם מדובר במסכת חגיגה כשהיה שם \u0003היסח הדעת,\u0004 הרי דינו כטמא מת, ולא די לו בטבילה לצורך קדשים, אלא הזאות ממי חטאת הנעשות ביום ה\u0003שלישי ושביעי\u0004 משבעת ימי טומאתו \u0003בעי\u0004 \u0005[צריך\u0006\u0005]\u0006 הוא. שכן \u0003אמר ר' יוסטאי בר' מתון אמר ר' יוחנן: היסח הדעת צריך הזאה שלישי ושביעי!\u0004","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה\u0006\u0005]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהסחת דעת מחייבת הזאות שלישי ושביעי — מדובר במקרה \u0003דאסח דעתיה\u0004 \u0005[שהסיח דעתו\u0006\u0005]\u0006 \u0003מטמא\u0004 (מטומאת) \u0003מת\u0004 ולא נזהר בה, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו במשנה במסכת חגיגה שדי לו בטבילה — מדובר במקרה \u0003דאסח דעתיה\u0004 \u0005[שהסיח דעתו\u0006\u0005]\u0006 \u0003מטמא\u0004 (מטומאת) \u0003שרץ.\u0004","ותוהים: אולם גם המסיח דעתו מ\u0003טמא שרץ, טמא מעלייא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 ולא די לו בטבילה, אלא גם \u0003הערב שמש בעי\u0004 \u0005[צריך\u0006\u0005]!\u0006 \u0003ועוד,\u0004 אם מדובר במסכת חגיגה כשהסיח דעתו מטומאת שרץ, \u0003אפילו\u0004 ב\u0003תרומה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יהיה אסור, ולאו דווקא בקדשים (ואילו במשנה נאמר שרק בקדשים הוא נאסר)!","\u0003אמר ר' ירמיה:\u0004 מדובר \u0003ב\u0004מקרה בו אדם \u0003אומר: נשמרתי מדבר המטמאני\u0004 ואני בטוח שלא נטמאתי טומאה המחייבת הערב שמש, \u0003ו\u0004אולם \u0003לא נשמרתי מדבר הפוסלני\u0004 בקדשים.","ושואלים: \u0003ומי איכא נטירותא לפלגא\u0004 \u0005[והאם יש שמירה למחצה\u0006\u0005],\u0006 שיכול לומר שלדבר מסויים נשמר מטומאה, ובדבר אחר לא נשמר? ומשיבים: \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 \u0003והתניא\u0004 \u0005[\u0006וכן \u0005שנויה\u0006 בברייתא\u0005]:\u0006 מי שהיה נושא סל, \u0003עודהו\u0004 (ובעוד) \u0003הסל על ראשו\u0004"],["\u0003ומגריפה\u0004 מצויה \u0003בתוכו, ואמר:\u0004 תשומת \u0003לבי\u0004 היתה \u0003על הסל,\u0004 שלא ייטמא, \u0003ואין לבי על המגריפה\u0004 — הרי \u0003הסל טהור,\u0004 שכן השגיח עליו, \u0003והמגריפה טמאה.\u0004","ולגופה של ברייתא זו שואלים: \u0003ותטמא מגריפה לסל!\u0004 ומשיבים: \u0003אין כלי מטמא כלי.\u0004 ושואלים: \u0003ותטמא\u0004 המגריפה את \u0003מה שבתוכו\u0004 של הסל, כגון תאנים! \u0003אמר רבא, באומר: שמרתיה\u0004 את המגריפה \u0003מדבר המטמאה,\u0004 כלומר, מדבר הגורם לה לטמא אחרים, \u0003ולא שמרתיה מדבר הפוסלה\u0004 כשלעצמה. ושבים לסתירה בין מה שנאמר במשנתנו שאונן נוגע בקדשים, לבין מה ששנינו במסכת חגיגה, שהאונן צריך טבילה לקדשים.","מסופר, \u0003איגלגל מילתא ומטאי לקמיה\u0004 \u0005[התגלגל הדבר והגיע\u0006 \u0005לפני\u0006\u0005]\u0006 \u0003ר' אבא בר ממל.\u0004 \u0003אמר להו\u0004 \u0005[להם\u0006\u0005]\u0006 ליושבים לפניו: האם \u0003לא שמיע להו הא\u0004 \u0005[שמעו\u0006 הלכה \u0005זו\u0006\u0005]\u0006 ש\u0003אמר ר' יוחנן אמר רבי: האוכל שלישי של תרומה,\u0004 כלומר, תרומה שנגעה בשני לטומאה, ונפסלה — \u0003אסור לאכול\u0004 תרומה, \u0003ומותר ליגע\u0004 בתרומה.","\u0003אלמא\u0004 \u0005[מכאן\u0006\u0005]\u0006 שדווקא \u0003באכילה עבוד רבנן\u0004 \u0005[עשו חכמים\u0006\u0005]\u0006 \u0003מעלה\u0004 והקפידו בכך, ואולם \u0003בנגיעה לא עבוד רבנן\u0004 \u0005[עשו חכמים\u0006\u0005]\u0006 \u0003מעלה.\u0004 ומכאן יש ללמוד גם לענין אונן: הצריכוהו חכמים טבילה לצורך אכילת קדשים, כפי ששנינו במסכת חגיגה, ולא הקפידו על הנגיעה, כפי שעולה ממשנתנו.","שנינו במשנה לגבי האונן: \u0003ואינו חולק\u0004 בקדשים על מנת \u0003לאכול\u0004 אותם בערב. ומעירים: יש לדייק שדווקא \u0003מיפלג\u0004 \u0005[לחלוק]\u0006 בקדשים \u0003הוא דלא פליג\u0004 \u0005[שאינו חולק\u0006\u0005],\u0006 \u0003ו\u0004אולם \u0003כי מזמני ליה\u0004 \u0005[כאשר מזמינים אותו]\u0006 כהנים אחרים לאכול עמם בערב — \u0003אכיל\u0004 \u0005[\u0006הריהו \u0005אוכל\u0006\u0005]\u0006 בקדשים.","\u0003ורמינהי\u0004 \u0005[ומשליכים\u0006 מראים סתירה על כך\u0005]\u0006 ממה ששנינו במסכת פסחים: \u0003אונן (ומחוסר כיפורים)\u0004 בארבעה עשר בניסן, \u0003טובל, ואוכל את פסחו לערב, אבל לא בקדשים\u0004 אחרים!","\u0003אמר רב ירמיה מדיפתי, לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005]:\u0006 \u0003כאן\u0004 במשנתנו, שדייקנו ממנה שמותר לאכול קדשים בערב, מדובר \u0003ב\u0004ליל ה\u0003פסח.\u0004 ואילו \u0003כאן\u0004 במשנה במסכת פסחים, ששנינו בה שאין האונן אוכל בערב בקדשים, מדובר \u0003בשאר ימות השנה.\u0004 ומדוע הוא כן?","בליל ה\u0003פסח\u0004 — \u0003איידי דאכיל\u0004 \u0005[מתוך ש\u0006האונן \u0005אוכל\u0006\u0005]\u0006 את קרבן ה\u0003פסח,\u0004 הריהו \u0003אכיל נמי\u0004 \u0005[אוכל גם כן\u0006\u0005]\u0006 \u0003קדשים\u0004 אחרים. ואולם \u0003בשאר ימות השנה\u0004 — כיון \u0003דלא חזי\u0004 \u0005[שאינו ראוי\u0006\u0005]\u0006 לאכול בקדשים, \u0003לא חזי\u0004 \u0005[אינו ראוי\u0006\u0005].\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הנאמר במשנה במסכת פסחים: \"אונן אוכל את פסחו לערב \u0003אבל לא בקדשים\"?\u0004 כוונתו: \u0003אבל לא בקדשים של כל השנה.\u0004","\u0003רב אסי אמר\u0004 תירוץ אחר לסתירה זו שבין המשניות: \u0003לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005],\u0006 \u0003כאן\u0004 במשנה בפסחים, ששנינו בה שאסור לאונן לאכול מן הקדשים בערב — מדובר \u0003שמת לו מת ב\u0004יום \u0003ארבעה עשר\u0004 בניסן, \u0003וקברו ב\u0004יום \u0003ארבעה עשר\u0004 עצמו, שבמקרה שכזה הריהו נחשב אונן (מדברי חכמים) אף בלילה שאחריו, ולכן אסור באכילת קדשים. ואילו \u0003כאן,\u0004 במשנתנו, שדייקנו בה שמותר האונן לאכול בלילה מן הקדשים — מדובר \u0003שמת לו מת ב\u0004יום \u0003שלשה עשר\u0004 בניסן, \u0003וקברו\u0004 למחרת \u0003ב\u0004יום \u0003ארבעה עשר\u0004 בניסן. וטעם הדבר, כי אף שתיקנו חכמים שיום המיתה תופס את הלילה שאחריו באנינות, \u0003יום קבורה\u0004 (כשאינו יום המיתה) \u0003לא תפיס\u0004 \u0005[אינו תופס\u0006 גורר אחריו\u0005]\u0006 את \u0003לילו\u0004 שייחשב כאונן \u0003מדרבנן\u0004 \u0005[מדברי חכמים\u0006\u0005].\u0006","מן הדיון הקודם עולה, כי לשיטת המשנה בפסחים, אנינות בלילה מדרבנן היא, ולא מן התורה. ומבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003אנינות לילה\u0004 שלאחר יום המיתה היא \u0003מדרבנן\u0004 \u0005[מדברי חכמים]?\u0006 שיטת \u0003ר' שמעון היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אנינות לילה מדברי תורה, דברי ר' יהודה. ר' שמעון אומר: אונן\u0004 בלילה \u0003אינו מדברי תורה אלא מדברי סופרים. תדע\u0004 שכן הוא, \u0003שהרי אמרו\u0004 חכמים: \u0003אונן, טובל ואוכל את\u0004 קרבן \u0003פסחו לערב, אבל לא ב\u0004שאר \u0003קדשים.\u0004 ואם אנינות לילה מן התורה היא, אף קרבן פסח יהיה אסור לאכול.","ושואלים: \u0003ו\u0004האם \u0003סבר ר' שמעון,\u0004 כי \u0003אנינות לילה\u0004 רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 היא, ואונן אוכל את פסחו בערב? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: אונן אינו משלח קרבנותיו\u0004 לבית המקדש להקריבם. \u0003מאי לאו\u0004 \u0005[האם אין\u0006\u0005]\u0006 הכוונה — \u0003ואפילו ב\u0004קרבן ה\u0003פסח,\u0004 שאינו יכול להקריבו בארבעה עשר בניסן? ומכאן שאינו אוכלו בלילה! ודוחים: \u0003לא,\u0004 מדובר בכל הקרבנות \u0003לבר\u0004 \u0005[חוץ\u0006\u0005]\u0006 \u0003מ\u0004קרבן \u0003פסח.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק \"ואם זבח שלמים קרבנו\" (ויקרא ג, א), \u0003ר' שמעון אומר:\u0004 קרבן \u0003שלמים\u0004 נקרא כן, כדי ללמדנו שאדם \u0003כשהוא שלם\u0004 ושרוי בשמחה \u0003מביא\u0004 קרבן זה, \u0003ו\u0004משום כך \u0003אינו מביא\u0004 את השלמים \u0003כשהוא אונן\u0004 (אבל ושרוי בצער). \u0003מנין לרבות את\u0004 קרבן \u0003התודה,\u0004 שאף אותה אין האונן משלח? וגם אם תאמר: \u0003מרבה\u0004 (מוסיף) \u0003אני\u0004 על השלמים אף \u0003את התודה, שכן נאכלת\u0004 היא \u0003בשמחה כשלמים,\u0004 שהרי קרבן הודאה הוא,","\u0003מנין לרבות\u0004 לענין זה אף \u0003את\u0004 קרבן \u0003העולה?\u0004 וגם אם תאמר: \u0003מרבה אני את העולה, שכן באה בנדר ובנדבה כשלמים, מנין לרבות\u0004 לענין זה אף את קרבנות ה\u0003בכור ומעשר ופסח,\u0004 שאינם באים בנדבה? וגם אם תאמר \u0003מרבה אני בכור ומעשר ופסח, שכן,\u0004 בדומה לקרבנות האחרים שהוזכרו, אף הם \u0003אינן באין על חטא, מנין לרבות\u0004 לענין זה גם קרבנות \u0003חטאת ואשם,\u0004 שהרי אלו באים על חטא? \u0003תלמוד לומר\u0004 בפסוק זה: \"ואם \u0003זבח\u0004 שלמים\" (ויקרא ג, א), ללמדנו שכל שהוא זבח הריהו בכלל \"שלמים\" לענין זה, שמביאו רק כשהוא שלם.","ומבררים עוד, \u0003מנין לרבות\u0004 בהלכה זו גם את הקדשים שאינם בכלל זבח, כגון \u0003העופות והמנחות והיין והעצים והלבונה?\u0004 \u0003תלמוד לומר: \"שלמים קרבנו\",\u0004 והמלה \"קרבנו\" מדגישה: \u0003כל קרבנות שהוא מביא\u0004 — כשהוא שלם מביא אותם, \u0003ואינו מביא\u0004 אותם \u0003כשהוא אונן.\u0004","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים\u0006\u0005]\u0006 בברייתא זו גם \u0003פסח,\u0004 משמע שגם פסח אסור האונן להביא, ומכאן שאינו רשאי לאוכלו בלילה!","\u0003אמר רב חסדא: פסח כדי נסביה\u0004 \u0005[לחינם מביא אותו\u0006\u0005].\u0006 כלומר, בפסח אין דין זה קיים, והוא נזכר כאן יחד עם הבכור והמעשר רק מתוך שגרת הלשון, שבמקומות רבים הם נזכרים ביחד.","\u0003רב ששת אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פסח\"\u0004 האמור כאן? \u0003שלמי פסח,\u0004 כלומר, שלמי חגיגה, הבאים יחד עם הפסח. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005],\u0006 \u0003היינו\u0004 \u0005[הרי זה\u0006\u0005]\u0006 \u0003שלמים,\u0004 שכבר שנה ר' שמעון בברייתא זו! ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003שלמים הבאין מחמת פסח, ותנא\u0004 \u0005[ושנה\u0006\u0005]\u0006 גם \u0003שלמים הבאין מחמת עצמן.\u0004","והוצרך לכך, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תנא\u0004 \u0005[היה שונה\u0006\u0005]\u0006 \u0003שלמים הבאין מחמת פסח, סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר\u0006\u0005]:\u0006 \u0003הואיל ומחמת פסח אתי\u0004 \u0005[באים\u0006\u0005],\u0006 \u0003כגופיה דפסח דמי\u0004 \u0005[כגופו של הפסח נחשבים\u0006\u0005],\u0006 וגם אותם מביא האונן, \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006\u0005]\u0006 כי גם שלמים אלה אסור להביא כשהוא אונן.","\u0003רב מרי אמר:\u0004"],["\u0003לא קשיא\u0004 \u0005[קשה],\u0006 את הסתירה בדברי ר' שמעון יש לתרץ כך: \u0003כאן\u0004 בברייתא ששנה ר' שמעון שאין האונן משלח את פסחו, ומכאן שאנינות לילה מן התורה היא — מדובר כ\u0003שמת לו מת ב\u0004יום \u0003ארבעה עשר\u0004 בניסן \u0003וקברו בארבעה עשר\u0004 עצמו. ואילו \u0003כאן\u0004 במשנה במסכת פסחים ששנינו בה שהאונן טובל ואוכל את פסחו לערב, ומשם הוכיח ר' שמעון שאנינות לילה מדרבנן — מדובר כ\u0003שמת לו מת ב\u0004יום \u0003שלשה עשר\u0004 בניסן, \u0003וקברו\u0004 למחרת \u0003ב\u0004יום \u0003ארבעה עשר\u0004 בניסן.","והסבר הדברים: במקרה ש\u0003מת לו מת בארבעה עשר וקברו בארבעה עשר\u0004 — חובת אנינות זו של \u0003יום מיתה\u0004 הריהי מן התורה, ולכן הוא \u0003תופס לילו\u0004 (הלילה שבא אחריו) \u0003מדאורייתא\u0004 \u0005[מהתורה],\u0006 ואין מצות אכילת קרבן פסח דוחה אנינות זו. ואילו במקרה ש\u0003מת לו מת בשלשה עשר וקברו בארבעה עשר\u0004 — הואיל ואין יום ארבעה עשר בניסן אלא \u0003יום קבורה\u0004 בלבד, שאינו יום מיתה, ואין חובת האנינות שבו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 לכן \u0003אינו תופס לילו אלא מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ומצות אכילת קרבן הפסח דוחה אנינות זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב מרי: ואלא הא דקתני\u0004 \u0005[זה ששנינו]\u0006 בברייתא שהובאה למעלה, ש\u0003אמר לו ר' שמעון\u0004 לר' יהודה: \u0003תדע\u0004 שאין אנינות לילה אלא מדברי חכמים, \u0003שהרי אמרו: אונן טובל ואוכל את פסחו אבל לא בקדשים.\u0004 ולשיטתך \u0003נימא ליה\u0004 \u0005[יאמר,\u0006 יכול ר' יהודה להשיב \u0005לו]\u0006 כך: אין זו ראיה, שכן \u0003קאמינא לך אנא\u0004 \u0005[אומר אני לך]\u0006 שאנינות לילה היא מן התורה, בלילה הבא לאחר \u0003יום מיתה,\u0004 שדין אנינות בו הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ואמרת לי את\u0004 \u0005[ואתה אומר\u0006 מביא ראיה \u0005לי\u0006 כנגדי\u0005]\u0006 ממשנה המדברת ב\u0003יום קבורה\u0004 שהוא רק מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]!\u0006 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003אביי אמר,\u0004 יש לתרץ את הסתירה שבדברי ר' שמעון בדין זה, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 בשני המקרים מדובר באונן ביום המיתה, \u0003כאן\u0004 שאין משלח את פסחו ואוכלו מדובר כ\u0003שמת\u0004 עליו מתו \u0003קודם חצות\u0004 יום ארבעה עשר בניסן, ואילו \u0003כאן\u0004 ששנינו שטובל ואוכל את פסחו לערב, מדובר כ\u0003שמת\u0004 עליו מתו \u0003לאחר חצות\u0004 יום ארבעה עשר בניסן. והסבר הדברים: כאשר מת עליו מתו \u0003קודם חצות\u0004 היום, שעדיין \u0003לא איחזי\u0004 \u0005[נהיה ראוי]\u0006 \u0003לפסח,\u0004 שהרי חובת קרבן הפסח מתחילה רק לאחר חצות היום — \u0003חיילא עליה\u0004 \u0005[חלה עליו]\u0006 \u0003אנינות,\u0004 ולכן אסור בהקרבת הפסח. ואולם אם מת עליו מתו ל\u0003אחר חצות\u0004 היום, \u0003דאחזי\u0004 \u0005[ש\u0006כבר \u0005נהיה ראוי]\u0006 \u0003לפסח\u0004 — \u0003לא חיילא עליה\u0004 \u0005[חלה עליו]\u0006 \u0003אנינות,\u0004 ולכן טובל ואוכל את פסחו בערב.","ומסבירים את מקור ההבחנה הזו, \u0003ומנא תימרא דשני ליה\u0004 \u0005[ומנין אתה אומר ששונה לו\u0006 הדין\u0005]\u0006 אם מת עליו מתו \u0003בין קודם חצות\u0004 של ארבעה עשר בניסן ל\u0003בין לאחר חצות? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בדיני טומאת הכהנים: \"ולאחותו הבתולה הקרובה אליו אשר לא היתה לאיש \u0003לה יטמא\"\u0004 (ויקרא כא, ג) — הרי זו \u0003מצוה\u0004 על הכהן שחייב להיטמא לקרוביו ולטפל בקבורתם, ואם \u0003לא רצה\u0004 בכך — \u0003מטמאין אותו על כרחו.\u0004 ומסופר, \u0003מעשה ביוסף הכהן שמתה אשתו בערב הפסח, ולא רצה ליטמא\u0004 לה, כיון שרצה לקיים את מצות קרבן הפסח, \u0003ונמנו\u0004 (עמדו למנין, הצביעו) \u0003אחיו הכהנים וטימאוהו בעל כרחו.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו בדינו של הנזיר, שאף הוא, כמו כהן, מוזהר על טומאת מת, ונאמר בו: \"לאביו ולאמו לאחיו ולאחותו לא יטמא להם במותם\" (במדבר ו, ז), ודרשו את הפסוק כך: \u0003\"ולאחותו\"\u0004 —\u0003 מה תלמוד לומר\u0004, מה זה בא ללמדנו? שכן \u0003הרי שהלך\u0004 הנזיר \u0003לשחוט את פסחו,\u0004 \u0003ולמול את בנו,\u0004 שהן מצוות חמורות, שיש בביטולן כרת, \u0003ושמע שמת לו מת\u0004 כלומר, אחד מקרוביו, \u0003יכול יטמא\u0004 למת, וייבטל מן המצוה? \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003לא יטמא\u0004 שאין נזיר רשאי ליטמא לקרוביו.","\u0003יכול כשם שלא יטמא לאחותו, כך אין מטמא למת מצוה? תלמוד לומר \"ולאחותו\",\u0004 להדגיש: \u0003לאחותו הוא\u0004 ש\u0003אינו מטמא, אבל מטמא הוא למת מצוה!\u0004 הרי שמן הברייתא הראשונה עולה כי מצוה להיטמא למת בערב הפסח, ומן הברייתא השניה עולה כי יש איסור בדבר!","אלא \u0003לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שיש להבחין בין המקרים: \u0003כאן\u0004 שאמרנו בכהן שנטמא ואינו מקריב את פסחו, מדובר שמת עליו מתו \u0003קודם חצות\u0004 היום, וכבר חל עליו החיוב להיטמא למתו קודם חובת הפסח. ואילו \u0003כאן\u0004 שאמרנו בדין הנזיר שאינו נטמא למתו אלא מקריב את פסחו, מדובר שמת עליו מתו \u0003לאחר חצות\u0004 היום. וכדין המצוה להיטמא — כך מצות האנינות.","ודוחים את הראיה: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה כך? \u0003דילמא\u0004 \u0005[שמא]\u0006 אפשר לישב את הדברים בדרך אחרת, \u0003לעולם אימא\u0004 \u0005[יכול אני לומר]\u0006 \u0003לך:\u0004 \u0003אידי ואידי\u0004 \u0005[זה וזה\u0006 בשתי הברייתות\u0005]\u0006 מדובר שמת עליו מתו ל\u0003אחר חצות\u0004 היום, \u0003והא\u0004 \u0005[\u0006וברייתא \u0005זו]\u0006 בנזיר, ששנינו בה שאינו נטמא אלא אוכל את פסחו, הריהי כשיטת \u0003ר' ישמעאל, ו\u0004אילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 במעשה יוסף הכהן, ששנינו בה שנטמא ואינו אוכל מקרבן הפסח, הריהי כשיטת \u0003ר' עקיבא.\u0004 ומסבירים מהן שיטות אלה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בטומאת כהנים: \"ולאחותו הבתולה הקרובה אליו אשר לא היתה לאיש \u0003לה יטמא\"\u0004 (ויקרא כא, ג) — הרי זו \u0003רשות,\u0004 שמותר לכהן להיטמא לאחותו, אם רצה בכך, אך אינו חייב בכך, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: חובה\u0004 עליו להיטמא לה!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דרישא דההיא\u0004 \u0005[ש\u0006הרי את \u0005תחילתה של אותה\u0006 ברייתא\u0005]\u0006 בטומאת הנזיר, ולפיה אין אדם נטמא לקרוביו בערב הפסח, \u0003ר' עקיבא\u0004 \u0003קתני לה\u0004 \u0005[שונה אותה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 ברייתא זו\u0005]\u0006 בשלמותה: נאמר בטומאת הנזיר: \"על נפש מת לא יבא. לאביו ולאמו לאחיו ולאחותו לא יטמא להם במותם\" (במדבר ו, ו—ז), \u0003ר' עקיבא אומר: \"נפש\"\u0004 האמורה כאן — \u0003אלו הקרובים,\u0004 שאינו נטמא להם, ופירוש המלה \u0003\"מת\"\u0004 האמורה כאן — \u0003אלו הרחוקים.\u0004","ומה שנאמר עוד בכתוב זה \u0003\"לאביו\",\u0004 למרות שהוא בכלל הקרובים — הרי זה להדגיש: דווקא לאביו \u0003אינו מטמא, אבל מטמא הוא למת מצוה.\u0004 עוד נאמר שם: \u0003\"לאמו\"\u0004 — ללמדנו שאפילו אם \u0003היה כהן והוא נזיר,\u0004 והרי הוא איפוא מוזהר ליטמא למת גם משום שהוא כהן וגם משום שהוא נזיר — דווקא \u0003לאמו הוא\u0004 ש\u0003אינו מטמא, אבל מטמא הוא למת מצוה.\u0004 ולמה נאמר עוד: \u0003\"לאחיו\"\u0004 — ללמדנו \u0003ש\u0004אפילו \u0003אם היה כהן גדול\u0004 שאינו מיטמא אפילו לקרוביו \u0003והוא נזיר\u0004 — דווקא \u0003לאחיו הוא\u0004 ש\u0003אינו מטמא, אבל מטמא הוא למת מצוה.\u0004","ומה שנאמר עוד: \u0003\"ולאחותו\"\u0004 — \u0003מה תלמוד לומר?\u0004 מה עוד בא הכתוב לחדש בענין זה? \u0003הרי שהלך לשחוט את פסחו ולמול את בנו,\u0004 \u0003ושמע שמת לו מת, יכול יטמא? אמרת: לא יטמא. יכול כשם שאין מטמא לאחותו\u0004 במקרה זה, \u0003כך אינו מטמא למת מצוה? תלמוד לומר \"ולאחותו\",\u0004 לומר: \u0003לאחותו לא יטמא, אבל יטמא הוא למת מצוה.\u0004"],["\u0003רבא אמר\u0004 תירוץ אחר לסתירה שבין דברי ר' שמעון בברייתא, שאונן אינו מקריב פסחו ואוכלו, לבין המשנה במסכת פסחים, שאונן טובל ואוכל את פסחו לערב: \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 עוסקות במקרה שמת עליו מת \u0003אחר חצות\u0004 יום ארבעה עשר בניסן, לאחר שכבר נתחייב בהקרבת הפסח, \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 משום ש\u0003כאן\u0004 בברייתא, מדובר שמת עליו מתו \u0003קודם ששחטו וזרקו עליו\u0004 את דם הפסח, ומעתה אינו רשאי להקריבו. ואילו \u0003כאן\u0004 במשנה במסכת פסחים, מדובר שמת עליו מתו \u0003לאחר\u0004 שכבר \u0003שחטו וזרקו עליו,\u0004 ולכן אוכל את פסחו בערב, שהרי אנינות לילה אינה מן התורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לרבא:\u0004 ל\u0003אחר ש\u0004כבר \u0003שחטו וזרקו את דמו,\u0004 מדוע אוכל הוא מן הפסח? והרי \u0003מה דהוה הוה\u0004 \u0005[שהיה היה]\u0006 ובאנינותו הוא, מדברי חכמים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא,\u0004 שישב גם הוא לפני רבא: \u0003אכילת פסחים מעכבא\u0004 \u0005[מעכבת]\u0006 את מצוות קרבן הפסח, שאם לא יאכל הריהו מבטל את עיקר מצות הפסח, ולכן לא אסרו חכמים על האונן לאוכלו בלילה, כמו שאסרו בשאר קדשים, ודבר זה למדים \u0003מ\u0004דברי \u0003רבה בר רב הונא,\u0004 כאשר יבואר להלן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב אדא בר מתנה: \u0003ציית מאי דקאמר\u0004 \u0005[הקשב,\u0006 קבל, \u0005מה שאומר]\u0006 \u0003לך רבך\u0004 רבינא. כלומר, הסברו זה של רבינא נכון הוא.","כיון שהוזכרו דברי רבה בר רב הונא, שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 אותה הלכה של \u0003רבה בר רב הונא\u0004 שממנה הסקנו שאכילת הפסח מעכבת? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יום שמועה\u0004 היום בו שומע אדם שמת לו מת, ולא ידע על כך בשעה שמת וקברוהו, הרי דינו \u0003כיום קבורה ל\u0004ענין \u0003מצות\u0004 אבילות \u0003שבעה,\u0004 שאסור ברחיצה ובנעילת הסנדל, שבעה ימים החל מיום זה, \u0003ושלשים\u0004 יום, שאסור לכבס בהם בגדיו. \u0003ו\u0004אילו \u0003ל\u0004ענין \u0003אכילת פסחים\u0004 הרי דינו של יום שמועה \u0003כיום ליקוט עצמות\u0004 אביו ואמו, כדי לקוברם (לאחר שנתעכל בשרם באדמה), שאמרו חכמים במשנה (פסחים צב,א), שטובל ואוכל קדשים בערב. ומוסיפה הברייתא: \u0003אחד זה ואחד זה,\u0004 הריהו \u0003טובל ואוכל בקדשים לערב.\u0004","ותוהים: והרי \u0003הא גופא קשיא\u0004 \u0005[\u0006ברייתא \u0005זו עצמה קשה\u0006 מתוכה\u0005],\u0006 שכן בתחילה \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003יום שמועה כיום קבורה למצות שבעה ושלשים, ולאכילת פסחים\u0004 דינו \u0003כיום ליקוט עצמות,\u0004 שטובל ואוכל בערב. \u0003מכלל\u0004 הדברים אתה למד שב\u0003יום קבורה\u0004 (למרות שאינו יום מיתה) — \u0003אפילו לערב\u0004 שלאחריו \u0003נמי לא אכיל\u0004 \u0005[גם כן אינו אוכל]\u0006 את פסחו, וכל שכן שאר קדשים. \u0003והדר תני\u0004 \u0005[ואחר כך שנה]:\u0006 \u0003אחד זה ואחד זה,\u0004 ומשמע — אחד יום קבורה ואחד יום ליקוט עצמות — \u0003טובל ואוכל בקדשים לערב!\u0004","בתירוץ סתירה זו \u0003אמר רב חסדא: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בברייתא, האם ליל קבורה מותר באכילת קדשים (כאשר יבואר להלן).","\u0003רבה בר רב הונא אמר, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 ששנינו: \"אחד זה ואחד זה טובל ואוכל קדשים בערב\", מדובר \u0003ששמע שמועה על מתו סמוך לשקיעת החמה,\u0004 כלומר, בעוד יום, \u0003וכן שליקטו לו עצמות סמוך לשקיעת החמה, וכן שמת לו מת וקברו סמוך לשקיעת החמה.\u0004 \u0003וכאן,\u0004 שדייקנו כי רק אם שמע שמועה על מתו או ליקט עצמות אוכל מפסחו בערב, אבל הקובר את מתו אינו אוכל — מדובר שהיה הדבר \u0003לאחר שקיעת החמה,\u0004 כלומר, בליל חמישה עשר בניסן. שאין זה מוצאי יום הקבורה, אלא יום הקבורה עצמו.","ותוהים על הסבר זה: אם מדובר \u0003לאחר שקיעת החמה,\u0004 הרי כששמע שמועה על מתו וכבר נשחט הקרבן ונזרק דמו — \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה],\u0006 ומדוע התירו לו לאכול את פסחו (בניגוד לשאר קדשים)? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003אכילת פסחים מעכבא\u0004 \u0005[מעכבת],\u0006 ומחמת שיש בה חומרה יתירה לא העמידו בה חכמים דבריהם, לגזור אנינות.","ועוד בתירוץ סתירה זו שבברייתא \u0003רב אשי אמר: מאי\u0004 \u0005[מה\u0006 פירוש] \u0003\"אחד זה ואחד זה\"\u0004 ששנינו בסוף הברייתא? לא אחד יום קבורה ואחד יום ליקוט עצמות. אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אחד יום שמועה ואחד יום ליקוט\u0004 עצמות — \u0003טובל ואוכל בקדשים לערב.\u0004 אבל ביום קבורה אינו אוכל מפסחו בערב, וכל שכן שאר קדשים, וכפי שדייקנו מתחילת הברייתא.","ומעירים: \u0003והא\u0004 \u0005[ו\u0006הסבר \u0005זה]\u0006 שאמר \u0003רב אשי, בדותא\u0004 \u0005[דבר שאינו נכון]\u0006 \u0003היא,\u0004 שהרי \u0003מכדי עלה קאי\u0004 \u0005[כיון\u0006 שהתנא \u0005עליה\u0006 עומד\u0005],\u0006 בדין יום שמועה ויום ליקוט עצמות, אם כן, לא היה צריך לומר \"אחד זה ואחד זה\", אלא \u0003\"זה וזה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005].\u0006 \u0003אלא שמע מינה בדותא היא\u0004 \u0005[למד מכאן\u0006 ש\u0005דבר שאינו נכון הוא].\u0006","ושבים אל דברי רב חסדא שאמר כי אכילת קדשים בליל יום קבורה במחלוקת תנאים היא שנויה. ומסבירים: \u0003ומאי תנאי\u0004 \u0005[ומה\u0006 היא מחלוקת \u0005התנאים]\u0006 בזה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עד מתי מתאונן עליו?\u0004 כלומר, עד מתי הוא נחשב לאונן על מתו, ואסור באכילת קדשים? \u0003כל היום. רבי אומר: כל זמן שלא נקבר\u0004 עדיין מתו.","ונברר ברייתא זו: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ביום מיתה,\u0004 יש לשאול על דעת התנא הראשון, שאמר שכל היום הוא אונן ולא מעבר לכך — \u0003מי איכא דלית ליה\u0004 \u0005[האם יש\u0006 תנא \u0005שאין לו,\u0006 שאינו סבור] ש\u0003יום מיתה דתפיס\u0004 \u0005[שתופס\u0006 גורר אחריו\u0005]\u0006 גם את \u0003לילו\u0004 על כל פנים \u0003מדרבנן\u0004 \u0005[מדברי סופרים]?\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 לפירוש זה, מה ש\u0003רבי אומר: כל זמן שלא נקבר,\u0004 ויש לדייק בדבריו: \u0003הא\u0004 \u0005[אבל]\u0006 אם כבר \u0003קברו אישתרי ליה\u0004 \u0005[הותר לו]\u0006 אף ביום המיתה עצמו, יש לתמוה: \u0003ומי איכא דלית ליה\u0004 \u0005[והאם יש\u0006 מי \u0005שאין לו\u0006 שאינו סבור\u0005]\u0006 כהלכה הנלמדת מהפסוק \"ושמתיה כאבל יחיד \u0003ואחריתה כיום מר\"\u0004 (עמוס ח, י), שאנינות נמשכת כל יום המיתה כולו, ואף לאחר שנקבר המת?","\u0003אמר רב ששת:\u0004 התנא שבברייתא, שאמר: עד מתי מתאונן עליו — על \u0003יום קבורה\u0004 שאינו יום המיתה \u0003קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005],\u0006 ובכך נחלקו, האם הוא אונן רק עד הקבורה, כדברי רבי, או עד סוף היום, כדברי התנא הראשון.","\u0003מתקיף\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף, אלא הא דקתני\u0004 \u0005[זו ששנינו]:\u0006 \u0003השומע על מתו\u0004 הרי הוא \u0003כמלקט עצמות,\u0004 ודינו ש\u0003טובל ואוכל בקדשים לערב,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003יום קבורה אפילו לערב נמי לא אכיל\u0004 \u0005[גם כן אינו אוכל],\u0006 \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שהרי אין היא כשיטת רבי ולא כשיטת החולקים עליו! \u0003אלא תריץ\u0004 \u0005[תרץ,\u0006 יישב את הברייתא\u0005]\u0006 ואמור כך: \u0003עד מתי מתאוננין עליו? כל אותו היום\u0004 של קבורה \u0003ו\u0004גם \u0003לילו,\u0004 שאף בו נאסר באכילת קדשים. \u0003רבי אומר:\u0004 אין אנינות בלילה אלא \u0003כל זמן שלא נקבר, אבל נקבר\u0004 — מתאוננים עליו כל אותו היום, אך \u0003בלא לילו.\u0004","\u0003אמרוה\u0004 לשמועה זו של רב יוסף \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה, אמר\u0004 בתמיהה: \u0003גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003כרב יוסף לימא הכי\u0004 \u0005[יאמר כך]?!\u0006 \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 שדברי \u0003רבי\u0004 הם \u0003לקולא\u0004 \u0005[להקל]\u0006 ביחס לדעת חכמים המחמירה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עד מתי מתאונן עליו? כל זמן שאינו נקבר, אפילו מכאן ועד עשרה ימים,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: אין מתאונן עליו אלא אותו היום בלבד.\u0004 הרי שרבי הוא המחמיר, וחכמים הם המקילים!","אלא \u0003תריץ הכי\u0004 \u0005[תרץ,\u0006 יישב \u0005כך\u0006 את הברייתא\u0005]:\u0006 \u0003עד מתי הוא מתאונן עליו? כל אותו היום\u0004 של קבורה, \u0003בלא לילו. רבי אומר:\u0004 מתאונן עליו \u0003כל זמן שלא נקבר\u0004 אפילו לאחר עשרה ימים, \u0003ואם נקבר\u0004 כלומר, כל יום שנקבר בו — \u0003תופס\u0004 את \u0003לילו.\u0004 והיא מחלוקת התנאים אליה התייחס רב חסדא.","מסופר, \u0003אמרוה\u0004 לשמועה זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא.\u0004 אמר: \u0003מדקאמר\u0004 \u0005[מכיון שאמר]\u0006 \u0003רבי: יום קבורה,\u0004 שאנינות שבו מדברי חכמים, \u0003תופס לילו מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003מכלל\u0004 הדברים יש להסיק שהוא סבור ש\u0003יום מיתה\u0004 שהוא מדברי תורה, הריהו \u0003תופס לילו מדאורייתא\u0004 \u0005[מן התורה],\u0006 שהרי בוודאי לא החמירו חכמים בדבריהם יותר מדין תורה.","ועל כך יש לתמוה: \u0003ו\u0004האם אכן \u0003סבר רבי\u0004 ש\u0003אנינות לילה דאורייתא\u0004 \u0005[מן התורה]\u0006 היא? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על חילופי הדברים שהיו בין משה ואהרון בסוף ימי המילואים, שמתו בניו באותו יום, ואמר אהרן: \u0003\"הן\u0004 היום הקריבו את חטאתם ואת עולתם לפני ה' ותקראנה אותי כאלה ואכלתי חטאת \u0003היום\u0004 הייטב בעיני ה\" (ויקרא י, יט). והמלה \"היום\" באה להדגיש: \u0003אני\u0004 — \u0003היום אסור\u0004 באכילת החטאת, \u0003ו\u0004אילו ב\u0003לילה\u0004 \u0003מותר\u0004 באכילה. \u0003ו\u0004אולם \u0003לדורות\u0004 — \u0003בין ביום ובין בלילה אסור\u0004 באכילת קדשים, אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003רבי אומר: אנינות לילה\u0004 גם לדורות \u0003אינה מדברי תורה אלא מדברי סופרים!\u0004","ומשיבים: \u0003לעולם\u0004 צריך לפרש שגם לדעת רבי, אנינות ליל יום מיתה \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא,\u0004 ומן התורה, יום מיתה אינו תופס את לילו."],["\u0003ו\u0004מכל מקום יום קבורה שהוא מדברי חכמים תופס גם את לילו, שכן \u0003חכמים עשו חיזוק לדבריהם יותר משל תורה\u0004 כלומר, יותר ממה שעשתה התורה לדבריה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שלוש לשונות ציווי בענין אכילת קדשים נאמרו על ידי משה לאהרן ובניו ביום השמיני למילואים, בו מתו נדב ואביהוא בני אהרן: \u0003\"כי כן צויתי\"\u0004 (ויקרא י, יג), \u0003\"כאשר צויתי\"\u0004 (ויקרא י, יח), \u0003כאשר צוה ה'\"\u0004 (ויקרא י, טו). ומסבירים: בתחילה אמר להם משה לגבי המנחה המיוחדת שהקריבו באותו יום: \"ואכלתם אותה... \u0003כי כן צויתי\"\u0004 מפי הקדוש ברוך הוא ש\u0003באנינות יאכלוה,\u0004 למרות שבדרך כלל אסור האונן באכילת קדשים. ומה שאמר להם: \u0003\"כאשר צויתי\"\u0004 — \u0003בשעת מעשה אמר להן\u0004 כשראה אחר כך ששרפו שעיר חטאת ראש חודש ניסן שקרב באותו יום, אמר להם: היה עליכם לאכול אותה באנינות, כאשר ציויתי אתכם על המנחה. ומה שאמר להם: \u0003\"כאשר צוה ה'\",\u0004 כוונתו היתה להדגיש: \u0003לא מאליי אני אומר\u0004 כן, אלא מפי הגבורה.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא אחרת, שנאמר בה: \u0003מפני אנינות נשרפה\u0004 החטאת, \u0003לכך נאמר\u0004 בדברי אהרן \"ותקראנה אותי \u0003כאלה\u0004 ואכלתי חטאת היום הייטב בעיני ה'\"? (ויקרא י, יט), ומשה הודה לדבריו, כפי שנאמר \"וישמע משה וייטב בעיניו\" (ויקרא י, כ), משמע שלא נצטווה שיאכלו אותה באנינות!","\u0003אמר שמואל, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא הראשונה, היא כשיטת \u0003ר' יהודה, הא\u0004 \u0005[זו],\u0006 ששנינו בה שמפני אנינות נשרפה, וכדין, היא כשיטת \u0003ר' נחמיה.\u0004","ומסבירים מהן שיטות אלה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מפני אנינות שרפוה, לכך נאמר \"כאלה\"\u0004 (כפי שהוסבר לעיל) אלו \u0003דברי ר' נחמיה. ר' יהודה ור' שמעון אומרים: מפני טומאה\u0004 שאירעה בה \u0003נשרפה. ש\u0004הרי שלוש חטאות קרבו באותו יום (כמבואר להלן), ו\u0003אם אתה אומר: מפני אנינות נשרפה, היו לשלשתן שישרפוה,\u0004 כלומר, צריך היה לשרוף את שלושתן. \u0003דבר אחר:\u0004 אם משום אנינות — \u0003היו ראוי לאוכלן\u0004 (לאוכלה) \u0003לערב,\u0004 לאחר שנגמרה האנינות, ולא היה צורך לשורפה. \u0003דבר אחר: והלא פינחס\u0004 בן אלעזר \u0003היה\u0004 כהן \u0003עמהן,\u0004 והוא לא היה אונן על נדב ואביהוא, ויכול היה לאכול.","\u0003רבא אמר: אידי ואידי\u0004 \u0005[זו וזו]\u0006 שתי הברייתות כשיטת \u0003ר' נחמיה,\u0004 הסבור שהחטאת נשרפה מפני האנינות. \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה קשה\u0005]:\u0006 \u0003כאן\u0004 שנצטווה משה לגבי המנחה שיאכלוה באנינות — מדובר היה \u0003בקדשי שעה\u0004 בקרבן שהיה מיוחד לימי המלואים בלבד. \u0003כאן\u0004 שנשרפה החטאת מפני האנינות — מדובר היה \u0003בקדשי דורות\u0004 בשעיר חטאת של ראש חודש ניסן, שנוהג לדורות, ודינו ככל שעירי ראש חודש, שאינם נאכלים באנינות. ועל כך הודה משה לאהרן.","ומעתה דנים בדעות התנאים שהובאו בברייתא, ושואלים: \u0003ר' נחמיה היכי מתריץ להני קראי\u0004 \u0005[איך מיישב את המקראות הללו]\u0006 האמורים בענין החטאת, \u0003ורבנן היכי מתרצי להו להני קראי\u0004 \u0005[וחכמים איך מיישבים אותם את המקראות הללו]?\u0006","ומסבירים: \u0003ר' נחמיה מתריץ להו הכי\u0004 \u0005[מיישב אותם כך]:\u0006 כששאל אותם משה \u0003\"מדוע לא אכלתם\u0004 את החטאת\", כך \u0003אמר לו משה לאהרן: שמא נכנס דמה\u0004 של חטאת זו \u0003לפני ולפנים,\u0004 ונפסלה בכך (ראה ויקרא ו, כג), ומשום כך ראויה הייתה להישרף? \u0003אמר לו: \"הן לא הובא את דמה\"\u0004 (ויקרא י, יח), שלא כך אירע. וחזר ושאלו משה: \u0003שמא חוץ למחיצתה יצאת\u0004 (יצאה), כלומר, חוץ לחצר המשכן, ונפסלה, ומשום כך נשרפה? \u0003אמר לו: בקדש היתה\u0004 כל העת, ולא יצאה מחוץ למחיצתה.","ושאל משה עוד את אהרן: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003באנינות אקריבתוה ופסלתוה\u0004 \u0005[הקרבתם אותה ופסלתם אותה]?\u0006 שהרי בניך אסור היה להם לעבוד עבודה באנינות, שהם כהנים הדיוטות! \u0003אמר לו: משה, וכי הם הקריבו? אני,\u0004 שאני כהן גדול המקריב גם באנינות (ראה ויקרא כא, י—יב) \u0003הקרבתי\u0004 ולא נפסלה בשל כך! \u0003ואמר לו\u0004 אז משה: \u0003הן,\u0004 כלומר, הואיל ו\u0003לא הובא את דמה\u0004 פנימה, \u0003ו\u0004גם \u0003בקדש היתה\u0004 ולא יצאה, אם כן \u0003אכול תאכלו אתה כאשר צויתי\u0004 לגבי המנחה שקרבה אותו יום, ש\u0003באנינות יאכלוה!\u0004","\u0003אמר לו\u0004 אהרן למשה: \u0003\"ותקראנה אתי כאלה ואכלתי חטאת היום הייטב בעיני ה'\"\u0004 (ויקרא י, יט)? \u0003שמא לא שמעת\u0004 מפי ה' שיש לאכול באנינות \u0003אלא בקדשי שעה,\u0004 כגון אותה מנחה.","\u0003דאי\u0004 \u0005[שאם]\u0006 תרצה לומר שאף \u0003קדשי דורות\u0004 בכלל זה, הרי יש ללמוד היפך הדברים במידת \u0003קל וחומר ממעשר\u0004 שני, \u0003הקל\u0004 בדינו מן הקדשים, ובאופן זה: \u0003ומה מעשר הקל אמרה תורה: \"לא אכלתי באני ממנו\"\u0004 (דברים כו, יד), שאסור לאונן לאכול ממנו, \u0003בקדשי דורות לא כל שכן\u0004 שאסור לאכול באנינות?","\u0003מיד\u0004 — \"\u0003וישמע משה וייטב בעיניו\u0004\" (ויקרא י, כ), והביטוי \"וישמע\" מרמז כי \u0003הודה ולא בוש משה לומר\u0004 רק: \"הלכה זו \u0003לא שמעתי\u0004 עד כה\", \u0003אלא אמר: \"שמעתי, ושכחתי\".\u0004","ושואלים: \u0003ור' יהודה ור' שמעון\u0004 הסבורים שהחטאת לא נשרפה מפני האנינות, \u0003היכי מתרצי להו\u0004 \u0005[כיצד\u0006 הם \u0005מיישבים אותם\u0006 מקראות\u0005]?\u0006 ומסבירים: \u0003הכי מתרצי להו\u0004 \u0005[כך\u0006 הם \u0005מיישבים אותם]:\u0006 כשאמר להם משה: \u0003\"מדוע לא אכלתם את החטאת במקום [הקדש]\"\u0004 (ויקרא י, יז), כך אמר: \u0003שמא נכנס דמה לפני ולפנים\u0004 ולכן נפסלה? \u0003אמר לו\u0004 אהרן למשה: \u0003\"הן לא הובא את דמה אל הקדש פנימה\"\u0004 (ויקרא י, יח).","חזר ושאל משה: \u0003שמא חוץ למחיצתה\u0004 מחוץ לחצר המשכן \u0003יצאת,\u0004 ולכן נפסלה? \u0003אמר לו\u0004 אהרן: \u0003הן בקודש היתה.\u0004 ועוד שאל משה: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003באנינות אקריבתוה\u0004 \u0005[הקרבתם אותה]\u0006 \u0003ופסלתוה\u0004 בכך? \u0003אמר לו\u0004 אהרון: \u0003משה,\u0004 וכי בני \u0003הן\u0004 \u0003הקריבוה, דפסלה בהו\u0004 \u0005[שפוסלת בהם]\u0006 \u0003אנינות? אני\u0004 שאני כהן גדול ועובד באנינות \u0003הקרבתיה!\u0004","ועוד שאל אותו משה: \u0003ודילמא אגב מררייכו פשעתו\u0004 \u0003בה ואיטמאי\u0004 \u0005[ושמא אגב מרירותכם,\u0006 אבלכם, \u0005פשעתם,\u0006 התרשלתם \u0005בה ונטמאה]?\u0006 \u0003אמר לו\u0004 אהרן: \u0003משה, כך אני בעיניך, שאני מבזה קדשי שמים\u0004 ומתרשל בטהרתם? \u0003\"ותקראנה אתי כאלה\"\u0004 — \u0003ואפילו אלה וכאלה\u0004 ועוד מיני אסונות, \u0003אין אני מבזה קדשי שמים!\u0004","\u0003אמר לו\u0004 משה: אם כן, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003הן לא הובא את דמה, ובקודש היתה\u0004 — \u0003אכול תאכלו אתה בקודש כאשר צויתי\u0004 (לגבי המנחה) \u0003באנינות יאכלוה!\u0004","\u0003אמר לו\u0004 אהרן: \u0003שמא\u0004 \u0003לא שמעת\u0004 מפי ה' שכך הוא הדין \u0003אלא בלילה\u0004 שלאחר יום האנינות, ולא ביום עצמו? \u0003דאי\u0004 \u0005[שאם]\u0006 תסיק מכאן כי הוא הדין אף \u0003ביום\u0004 עצמו, הרי יש ללמוד במידת \u0003קל וחומר ממעשר הקל\u0004 מן הקדשים שאין זה כך: \u0003ומה מעשר הקל, אמרה תורה: \"לא אכלתי באני\u0004 \u0003ממנו\"\u0004 (דברים כו, יד), \u0003קודש חמור לא כל שכן?\u0004","\u0003מיד\u0004 — \u0003\"וישמע משה\u0004"],["\u0003וייטב בעיניו\"\u0004 — \u0003לא בוש משה לומר\u0004 רק: \u0003\"לא שמעתי\u0004 הלכה זו עד כה\", \u0003אלא\u0004 אמר במפורש: \u0003\"שמעתי\u0004 הלכה זו, \u0003ושכחתי\".\u0004 ושואלים: אם כן, לשיטה זו, מדוע נשרפה החטאת?","\u0003איבעי להו לשהוייה ולמיכלא באורתא\u0004 \u0005[היה להם להשהותה ולאכול אותה בלילה]!\u0006 ומשיבים: \u0003טומאה באונס באתה\u0004 (באה) על חטאת זו, ולכן שרפוה.","ושואלים: \u0003בשלמא לרבנן\u0004 \u0005[נניח ל\u0006שיטת \u0005חכמים]\u0006 המפרשים כן, ר' יהודה ור' שמעון, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בדברי אהרן: \"ואכלתי חטאת \u0003היום\u0004 הייטב בעיני ה'\" (ויקרא י, יט)? כלומר, היום איני יכול, אלא רק בלילה. \u0003אלא ל\u0004שיטת \u0003ר' נחמיה,\u0004 שאהרן עשה הבחנה בין קדשי שעה וקדשי דורות, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"ואכלתי חטאת \u0003היום\"?\u0004 ומשיבים: הכוונה היא: וכי חטאת ראש חודש שהיא \u0003חובת היום\u0004 רשאי אני לאכול?","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' נחמיה, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בתחילת אותו פסוק: \u0003\"הן היום\u0004 הקריבו את חטאתם\" וכו' (ויקרא י, יט), כלומר, הרי לחובת היום הקריבו את חטאתם. \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים,\u0006 ר' יהודה ור' שמעון\u0005]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הן היום\"?\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 אהרן: וכי \u0003הן\u0004 (=הם, בני) \u0003הקריבו\u0004 היום, שאסור להם להקריב באנינות? \u0003אני הקרבתי,\u0004 וכהן גדול מקריב גם כשהוא אונן.","ועוד בבירור ברייתא זו, \u0003אמר מר\u0004 \u0005[החכם]\u0006 ר' יהודה ור' שמעון לר' נחמיה: אם מפני אנינות נשרפה החטאת \u0003היו לשלשתן שישרפו.\u0004 \u0003ומסבירים: מאי\u0004 \u0005[מה]\u0006 הכוונה בלשון \u0003\"שלשתן\"?\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 הדורשת את הכתוב בענין זה: \u0003\"ואת שעיר החטאת דרש דרש משה\"\u0004 (ויקרא י, טז), \u0003\"שעיר\"\u0004 — \u0003זו שעיר נחשון\u0004 בן עמינדב, נשיא שבט יהודה שהקריב את קרבנו באותו יום, שהיה היום הראשון לחנוכת המזבח (ראה במדבר פרק ז). \u0003\"חטאת\"\u0004 — \u0003זו חטאת שמיני,\u0004 כלומר, שעיר שנצטוה העם להביא ביום השמיני למילואים (ויקרא ט, ג). \u0003\"דרש\"\u0004 — זהו \u0003שעיר של ראש חודש,\u0004 שהרי הקמת המשכן היתה בראש חודש ניסן (ראה שמות מ, יז), ובראש חודש מביאים שעיר לחטאת (במדבר כח, טו). הרי אלו שלושה שעירים שקרבו באותו יום.","\u0003יכול שלשתן נשרפו? תלמוד לומר:\u0004 \"דרש דרש משה \u0003והנה שרף\",\u0004 ללמד: \u0003אחד\u0004 מן הקרבנות \u0003נשרף, ולא שלשתן נשרפו.\u0004 והוא מה שנאמר שם \u0003\"דרש דרש\",\u0004 ויש לשאול: \u0003שתי דרישות למה?\u0004 אלא כך \u0003אמר להו\u0004 \u0005[להם]\u0006 משה: \u0003מפני מה חטאת זו נשרפה, ו\u0004מפני מה \u0003אלו מונחות?\u0004 וממשיכה הברייתא: \u0003ו\u0004עדיין \u0003איני יודע איזהו\u0004 שעיר נשרף, ומהם שני השעירים המונחים. \u0003כשהוא אומר\u0004 לגבי השעיר שנשרף: \u0003\"ואתה נתן לכם לשאת את עון העדה\"\u0004 (ויקרא י, יז), \u0003הוי אומר: זה שעיר של ראש חודש,\u0004 עליו ידוע שהוא בא לכפרת טומאת מקדש וקדשיו.","ושואלים: \u0003שפיר קאמרי ליה\u0004 \u0005[יפה אומרים לו]\u0006 ר' יהודה ור' שמעון לר' נחמיה, שאם משום אנינות צריך היה לשרוף את שלושת השעירים. ומה הוא משיב על כך? ומשיבים: \u0003ר' נחמיה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: קדשי שעה לא פסלה בהו\u0004 \u0005[פוסלת בהם]\u0006 \u0003אנינות,\u0004 ולכן שרפו רק את חטאת ראש החודש, שהיא חטאת לדורות.","ועוד באותה ברייתא, \u0003אמר מר\u0004 \u0005[החכם],\u0006 טענו ר' יהודה ור' שמעון לר' נחמיה: אם מפני אנינות, מדוע נשרפה? \u0003היה לו לאכלה לערב!\u0004 ושואלים: \u0003שפיר קאמרי ליה\u0004 \u0005[יפה אמרו לו]!\u0006 ומה משיב על כך ר' נחמיה? ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003אנינות לילה דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכן גם לערב לא היו רשאים לאכול אותה.","ועוד טענו ר' יהודה ור' שמעון לר' נחמיה, \u0003דבר אחר:\u0004 אם מפני אנינות נשרפה החטאת — \u0003והלא פינחס\u0004 בן אלעזר בן אהרן \u0003היה עמהן,\u0004 ויכול היה לאכול את החטאת! ושואלים: הרי \u0003שפיר קאמרי ליה\u0004 \u0005[יפה אמרו לו],\u0006 ומה הוא משיב על כך? ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר אמר ר' חנינא: לא נתכהן פינחס עד שהרגו לזמרי\u0004 בן סלוא, כשזנה עם המדיינית (במדבר כה, ו-ח), \u0003דכתיב\u0004 \u0005[ש\u0006רק אז \u0005נאמר]:\u0006 \u0003\"והיתה לו ולזרעו אחריו ברית כהנת עולם\u0004 תחת אשר קנא לאלהיו ויכפר על בני ישראל\" (במדבר כה, יג). וקודם לכן, בזמן המילואים, רק בניו של אהרן עצמו (ובניהם שייוולדו לאחר מכן) נעשו כהנים.","\u0003רב אשי אמר:\u0004 לא נתכהן פינחס \u0003עד ששם שלום בין השבטים\u0004 בזמן כיבוש הארץ, כשעשו שבטי עבר הירדן מזבח לעצמם, ודבר זה היה עשוי לגרום למלחמה בין השבטים. ומניין שכך הוא? שהרי רק אז נזכר לראשונה בכינוי \"הכהן\", \u0003שנאמר: \"וישמע פינחס הכהן ונשיאי העדה וראשי אלפי ישראל\"\u0004 (יהושע כב, ל) וקודם לכן נזכר רק כבנו של אלעזר הכהן.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן],\u0006 מדוע אינו סבור שפנחס נתכהן כשהרג את זמרי? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 אז: \u0003\"והיתה לו ולזרעו אחריו\u0004 ברית כהונת עולם\"! ומשיבים: \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 הפסוק \u0003ההוא\u0004 — \u0003ב\u0004ענין \u0003ברכה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שלא תפסוק כהונה מזרעו.","וחוזרים ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 הסבור כי נתכהן כשהרגו לזמרי, \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"וישמע פינחס הכהן\"\u0004 (יהושע כב, ל) ומשמע שרק מאז נקרא כהן! ומשיבים: הכתוב \u0003ההוא\u0004 בא \u0003ליחס זרעו אחריו\u0004 לומר כי מכוחו ומזכותו הריהם כהנים גדולים.","ובענין שהוזכר בברייתא מביאים מה ש\u0003אמר רב: משה רבינו כהן גדול וחולק בקדשי שמים היה,\u0004 \u0003שנאמר: \"מאיל המלאים למשה היה למנה\"\u0004 (ויקרא ח, כט).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003\"והלא פינחס היה עמהן\", ואם איתא\u0004 \u0005[אכן]\u0006 משה רבינו היה חולק בקדשים ככהן, \u0003לימא\u0004 \u0005[שיאמר]:\u0006 \u0003\"והלא משה רבינו היה עמהן\"!\u0004 ודוחים: \u0003דילמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003משה, דטריד\u0004 \u0005[ש\u0006היה \u0005טרוד]\u0006 \u0003ב\u0004קבלת פני \u0003שכינה,\u0004 שהקדוש ברוך הוא היה מדבר עמו תדיר, וצריך היה בכל עת להיות פנוי לכך. וכדרך ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003משה\u0004 כשהיו ישראל חונים מול הר סיני, \u0003בהשכמה עלה\u0004 להר \u0003ובהשכמה ירד,\u0004 ולא היה פנוי לאכילת קדשים.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב ממה ששנינו, נאמר בדינו של כהן בעל מום: \u0003\"לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל\"\u0004 (ויקרא כא, כב). ויש לשאול, \u0003אם נאמרו\u0004 בפסוק זה \u0003קדשי קדשים,\u0004 שכהן בעל מום רשאי לאוכלם, \u0003למה נאמר\u0004 גם \u0003קדשים קלים? ואם נאמרו קדשים קלים, למה נאמר קדשי קדשים?\u0004","ומשיבים: \u0003אילו לא\u0004 היה \u0003נאמר קדשים קלים, הייתי אומר:\u0004 דווקא \u0003קדשי קדשים הוא\u0004 ש\u0003אוכל, שהרי הותרו\u0004 קדשי קדשים באכילה גם \u0003לזר ו\u0004גם \u0003להן\u0004 לכהנים, ואולם \u0003קדשים קלים לא יאכל\u0004 (כלומר, החזה והשוק שבהם הניתנים לכהנים), שדבר זה לא הותר לזר. \u0003ו\u0004להיפך, \u0003אילו לא נאמרו קדשי קדשים, הייתי אומר:\u0004 דווקא \u0003בקדשים קלים יהא\u0004 כהן בעל מום \u0003אוכל, ש\u0004הרי \u0003הן קלים,\u0004 ואולם \u0003בקדשי קדשים\u0004 שקדושתם מרובה \u0003לא יהא אוכל, לכך נאמרו\u0004 גם \u0003קדשי קדשים ולכך נאמר\u0004 גם \u0003קדשים קלים.\u0004","\u0003קתני מיהא\u0004 \u0005[\u0006הריהו \u0005שונה על כל פנים]:\u0006 \u0003\"שהרי הותרו לזר ולהן\", לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003משה,\u0004 שמשה היה אוכל בקדשי קדשים אף על פי שהוא זר? ומכאן שלא היה כהן גדול, כפי שאמר רב! \u0003אמר רב ששת: לא,\u0004 הכוונה היא לקדשי קדשים שהיו נאכלים \u0003בבמה לזר.\u0004 שמשנכנסו ישראל לארץ, והותרו הבמות, ושם הותר גם לזר לעבוד, בבמה שכל יחיד בונה לעצמו. ומעירים: \u0003ו\u0004הוא \u0003כדברי האומר: יש מנחה בבמה,\u0004 ומנחה היא קדשי קדשים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רב, שמשה היה כהן גדול, ממה ששנינו: \u0003מרים\u0004 שנעשתה מצורעת, \u0003מי הסגירה\u0004 (קבע שהיא מצורעת וטעונה הסגר מחוץ למחנה)? \u0003אם תאמר: משה הסגירה\u0004 — הלוא \u0003משה זר הוא,\u0004"],["\u0003ואין זר רואה את הנגעים! ואם תאמר: אהרן\u0004 הכהן הוא ש\u0003הסגירה\u0004 — הלוא \u0003אהרן קרוב הוא,\u0004 שהרי אחיה הוא, \u0003ו\u0004כלל הוא ש\u0003אין קרוב רואה את הנגעים! אלא כבוד גדול חלק לה הקדוש ברוך הוא למרים אותה שעה,\u0004 שאמר: \u0003אני\u0004 עצמי \u0003כהן, ואני\u0004 הוא זה ש\u0003מסגירה\u0004 שבעה ימים כדי לראות אם הנגע פושה או עומד בעינו, ו\u0003אני\u0004 הוא זה ש\u0003חולטה,\u0004 מכריז שהיא מצורעת אם טמאה היא בוודאי, \u0003ואני\u0004 הוא זה ש\u0003פוטרה\u0004 אם אין זה נגע טמא.","\u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]\u0006 בברייתא זו: \u0003\"משה זר, ואין זר רואה את הנגעים\",\u0004 משמע שמשה לא היה כהן, ושלא כשיטת רב!","\u0003אמר רב נחמן בר יצחק: שאני\u0004 \u0005[שונה]\u0006 הוא דין \u0003מראות נגעים,\u0004 שכן \u0003אהרן ובניו כתובין בפרשה\u0004 זו של נגעים (\"והובא אל אהרן הכהן או אל אחד מבניו הכהנים\", ויקרא יג, ב), ואין משה בכלל אהרן ובניו. ואולם אין ללמוד מכאן שלא היה כהן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על שיטת רב ממה ששנינו בברייתא: \u0003חמש שמחות היתה אלישבע\u0004 בת עמינדב, אשת אהרן (ראה שמות ו, כג), \u0003יתירה על\u0004 שאר \u0003בנות ישראל\u0004 באותו יום שנחנך המשכן: \u0003יבמה\u0004 (גיסה) משה רבינו, היה \u0003מלך, אישה\u0004 אהרן היה \u0003כהן גדול, בנה\u0004 אלעזר היה \u0003סגן\u0004 הכהן הגדול, \u0003בן בנה\u0004 פינחס היה כהן \u0003משוח מלחמה\u0004 היוצא בראש הצבא, \u0003ואחיה\u0004 נחשון בן עמינדב היה \u0003נשיא שבט\u0004 יהודה, שהקריב באותו יום את קרבנו כראשון הנשיאים. \u0003ו\u0004באותו יום עצמו של שמחה היתה \u0003אבילה על שני בניה,\u0004 נדב ואביהוא, שמתו בו ביום.","\u0003קתני מיהת\u0004 \u0005[\u0006הריהו \u0005שונה על כל פנים]:\u0006 \u0003\"יבמה\u0004 משה \u0003מלך\",\u0004 ונדייק מכאן: \u0003מלך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003כהן גדול\u0004 — \u0003לא,\u0004 ושלא כשיטת רב! ומשיבים: \u0003אימא\u0004 \u0005[אמור],\u0006 כך הכוונה: \u0003אף מלך\u0004 היה, מלבד שהיה כהן גדול.","ומעירים: שאלה זו אם משה היה כהן גדול, הריהי \u0003כתנאי\u0004 \u0005[\u0006כמחלוקת \u0005תנאים]\u0006 בענין זה. שכך שנינו על הנאמר בעת ההתגלות בסנה למשה, כשסירב לדבר אל פרעה בשליחות ה': \u0003\"ויחר אף ה' במשה\"\u0004 (שמות ד, יד), \u0003ר' יהושע בן קרחה אומר: כל חרון אף שבתורה נאמר בו רושם\u0004 כלומר, יש בכתוב מעשה או דיבור שבו מתבטא חרון זה, \u0003וזה לא נאמר בו רושם.\u0004","\u0003ר' שמעון בן יוחי אומר: אף זה נאמר בו רושם, ש\u0004כן \u0003נאמר\u0004 מיד לאחר מכן באותו פסוק: \u0003\"הלא אהרן אחיך הלוי\u0004 ידעתי כי דבר ידבר הוא\", ויש לשאול: \u0003הלא\u0004 אהרן \u0003כהן הוא!\u0004 אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 הקדוש ברוך הוא למשה: \u0003אני אמרתי\u0004 בתחילה ש\u0003אתה\u0004 תהיה \u0003כהן והוא לוי, עכשיו הוא\u0004 יהיה \u0003כהן ואתה לוי.\u0004","\u0003וחכמים אומרים: לא נתכהן משה אלא\u0004 לתקופת \u0003שבעת ימי המלואים בלבד,\u0004 ולאחר מכן פסקה כהונתו. \u0003ויש אומרים: לא פסקה כהונה אלא מזרעו של משה,\u0004 אבל משה עצמו היה כהן, \u0003שנאמר: \"ומשה איש האלהים בניו יקראו על שבט הלוי\"\u0004 (דברי הימים א כג, יד), ויש להבין מכאן שבניו הם לויים, אבל הוא עצמו כהן היה. \u0003ו\u0004כן \u0003אומר: \"משה ואהרן בכהניו ושמואל בקראי שמו\"\u0004 (תהלים צט, ו).","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואומר\"?\u0004 מדוע היה צריך להוסיף עוד ראיה? ומסבירים: \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003לדורות הוא דכתיב\u0004 \u0005[שנאמר]\u0006 שגם בניו יקראו על שבט הלוי, ואין זה בא להוציא את משה מכלל זה, \u0003ו\u0004על כן \u0003אומר: \"משה ואהרן בכהניו\",\u0004 הרי שנקרא כהן. ובשיטה זו הולך רב שאמר שהיה כהן גדול.","על מה שהוזכר קודם שואלים: \u0003וכל חרון אף שבתורה נאמר בו רושם? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויצא (משה) מעם פרעה בחרי אף\"\u0004 (שמות יא, ח), \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 משה לפרעה \u0003ולא מידי\u0004 \u0005[דבר]!\u0006 \u0003אמר ריש לקיש: סטרו\u0004 משה לפרעה \u0003ויצא.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ריש לקיש הכי\u0004 \u0005[כך]\u0006 שמשה סטר לפרעה? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדברי ה' למשה: \"לך אל פרעה... \u0003ונצבת לקראתו על שפת היאר\"\u0004 (שמות ז, טו), \u0003ואמר ריש לקיש: מלך הוא, והסביר לו פנים, ור' יוחנן אמר:\u0004 הכוונה \u0003רשע הוא, והעיז פניך בו.\u0004 הרי שלשיטת ריש לקיש נהג משה כבוד בפרעה, וכיצד אומר הוא שסטרו על לחיו! ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את שמות החכמים בזה, ואמור שריש לקיש הוא שאמר שהעיז בו פנים, ור' יוחנן הוא שאמר שנהג בו כבוד.","ובענין זה של נתינת כבוד למלך, \u0003אמר ר' ינאי: לעולם תהא אימת מלכות עליך,\u0004 אפילו כשהמלך עצמו איננו ראוי לכבוד, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר משה לפרעה: \u0003\"וירדו כל עבדיך אלה אלי\u0004 והשתחוו לי לאמר צא אתה וכל העם אשר ברגליך\" (שמות יא, ח), \u0003ואילו לדידיה לא קאמר ליה\u0004 \u0005[ל\u0006פרעה \u0005עצמו לא אמר לו]\u0006 שיעשה כן (אף שכך היה לבסוף), אלא דיבר אליו בלשון כבוד משום שהוא מלך.","\u0003ר' יוחנן אמר: מהכא\u0004 \u0005[מכאן]\u0006 ראיה לדבר, שנאמר: \u0003\"ויד ה' היתה אל אליהו וישנס מתניו וירץ לפני אחאב\"\u0004 (מלכים א יח, מו), הרי שאפילו אליהו הנביא רץ לפני מלך רשע כאחאב כדי לכבדו.","ועוד בעניינו של משה, \u0003אמר עולא: בקש משה\u0004 שתינתן לו \u0003מלכות, ולא נתנו לו. דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לו בהתגלות בסנה: \u0003\"אל תקרב הלם\"\u0004 (שמות ג, ה), \u0003ואין \"הלום\" אלא מלכות, שנאמר\u0004 בדברי דוד המלך: \u0003\"מי אנכי ה' אלהים [וגו'] כי הביאתני עד הלם\"\u0004 (שמואל ב ז, יח).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא\u0004 ממה ששנינו בברייתא שהובאה למעלה, \u0003ר' ישמעאל אומר: יבמה\u0004 של אלישבע, משה, היה \u0003מלך.\u0004 נמצא שזכה משה למלכות! \u0003אמר רבא: לו ולזרעו קאמר\u0004 \u0005[אמר],\u0006 שלא זכה למלכות שיורישנה לבניו אחריו.","ושואלים: \u0003וכל היכא דכתיב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"הלום\",\u0004 מלכות \u0003לדורות הוא? והא גבי\u0004 \u0005[והרי אצל]\u0006 \u0003שאול דכתיב\u0004 \u0005[שנאמר]\u0006 בענין המלכתו: \"וישאלו עוד בה' \u0003הבא עוד הלם איש\"\u0004 (שמואל א י, כב), \u0003הוא\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 היה מלך, \u0003זרעו\u0004 — \u0003לא!\u0004","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הא הוה\u0004 \u0005[הרי היה]\u0006 \u0003איש בשת\u0004 בן שאול שהיה גם הוא מלך (שמואל ב ב, י), ואם כן היתה מלוכה גם לבניו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שאול,\u0004 ש\u0003אפילו בגויה\u0004 \u0005[בו עצמו]\u0006 \u0003לא קאים\u0004 \u0005[עמדה\u0006, התקיימה\u0005]\u0006 המלוכה, ומשום כך גם לא נמשכה הלאה לזרעו.","ו\u0003כ\u0004דברי \u0003ר' אלעזר אמר ר' חנינא,\u0004 שאמר: \u0003בשעה שפוסקים\u0004 בשמים \u0003גדולה לאדם\u0004 — \u0003פוסקים לו ולזרעו עד סוף כל הדורות, שנאמר: \"לא יגרע מצדיק עיניו ואת מלכים לכסא\u0004 ויושיבם לנצח\" (איוב לו, ז). \u0003ואם הגיס דעתו\u0004 שנתגאה (כפי שנאמר מיד אחר כך: \"ויגבהו\") — \u0003הקדוש ברוך הוא משפילו,\u0004 כפי שאירע לשאול, \u0003שנאמר\u0004 בפסוק שלאחריו: \"\u0003ואם אסורים בזקים ילכדון בחבלי עוני\u0004\" (איוב לו, ח).","ושבים לביאור משנתנו, ששנינו בה: כהנים \u0003בעלי מומין, בין\u0004 שהם \u0003בעלי מומין\u0004 עוברים, ובין שהם בעלי מומין קבועים — חולקים בקדשים ואוכלים מהם, אבל לא מקריבים קדשים. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר לגבי המנחה: \u0003\"כל זכר\u0004 בבני אהרן יאכלנה\" (ויקרא ו, יא), והרי לשון זו (\"כל זכר\") באה \u0003לרבות\u0004 אף כהנים \u0003בעלי מומין.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין נאמר ריבוי זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003אכילה, הרי כבר נאמר\u0004 לגבי בעלי מומים במפורש: \"כל איש אשר בו מום מזרע אהרן הכהן... \u0003לחם אלהיו מקדשי הקדשים\u0004 ומן הקדשים \u0003יאכל\"\u0004 (ויקרא כא, כב)! \u0003אלא\u0004 הכוונה היא לרבות כהן בעל מום אף \u0003לחלוקה\u0004 שהוא חולק בקדשים עם שאר אחיו.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בענין זה לגבי החטאת: \u0003\"כל זכר\u0004 בכהנים יאכל אותה\" (ויקרא ו, כב) — \u0003לרבות\u0004 כהנים \u0003בעלי מומין.\u0004 ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 לאיזה ענין ריבוי זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לאכילה\u0004 — \u0003הרי כבר אמור, אי\u0004 \u0005[אם]\u0006 \u0003לחלוקה\u0004 — \u0003הרי כבר אמור.\u0004 אלא לכך בא ריבוי זה, \u0003שיכול\u0004 הייתי לומר: \u0003אין לי\u0004 דין זה \u0003אלא\u0004 דווקא בכהן שהיה בתחילה \u0003תם\u0004 (שלם) \u0003ונעשה\u0004 אחר כך \u0003בעל מום.\u0004 ואולם מי שהיה \u0003בעל מום מעיקרו, מנין\u0004 לנו שגם הוא חולק ואוכל בקדשים? תלמוד לומר הריבוי \u0003\"כל זכר\".\u0004","ועוד \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 לגבי האשם: \u0003\"כל זכר\u0004 בכהנים יאכלנו\" (ויקרא ז, ו) — \u0003לרבות בעל מום.\u0004 ושואלים: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין נאמר ריבוי זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לאכילה\u0004 — \u0003הרי כבר אמור, ואי\u0004 \u0005[ואם]\u0006 \u0003לחלוקה\u0004 — \u0003הרי כבר אמור, ואי\u0004 \u0005[ואם]\u0006 \u0003לבעל מום מעיקרו\u0004 — \u0003הרי כבר אמור.\u0004 אלא לכך בא ריבוי זה, \u0003שיכול\u0004 הייתי לומר: \u0003אין לי\u0004 דין זה \u0003אלא\u0004 דווקא בכהן \u0003בעל מום קבוע,\u0004 ואולם כהן שהוא \u0003בעל מום עובר מנין\u0004 לנו שכך הוא דינו? \u0003תלמוד לומר \"כל זכר\".\u0004","ותוהים: \u0003כלפי לייא\u0004 \u0005[להיכן\u0006 הוא \u0005נוטה]?\u0006 וכי בבעל מום עובר יש להחמיר מבעל מום קבוע? והרי ההיפך הוא המסתבר! \u0003אמר רב ששת: איפוך\u0004 \u0005[הפוך]\u0006 את הדברים, ושנה בברייתא כך: \"אין לי אלא בעל מום עובר, בעל מום קבוע מנין\".","\u0003רב אשי אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך]\u0006 את לשון הברייתא. \u0003ו\u0004אין זו קושיה, משום ש\u0003איצטריך\u0004 \u0005[הוצרך]\u0006 להיאמר שאף בעל מום עובר הריהו חולק ואוכל בקדשים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006"],["שיהיה דינו \u0003כי\u0004 \u0005[כמו]\u0006 של כהן \u0003טמא: מה טמא כמה\u0004 (כל זמן) שהוא \u0003לא טהור\u0004 — \u0003לא אכיל\u0004 \u0005[אוכל]\u0006 מהקדשים, \u0003אף האי נמי\u0004 \u0005[זה גם כן],\u0006 כהן בעל מום עובר, \u0003כמה\u0004 (כל זמן) ש\u0003לא מתקן\u0004 \u0005[נתקן,\u0006 נעשה שלם\u0005]\u0006 \u0003לא אכיל\u0004 \u0005[אוכל]\u0006 מהקדשים. לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ריבוי זה שבכל זאת הוא אוכל, אף על פי שמומו יעבור לאחר זמן.","עוד שנינו במשנתנו: \u0003כל\u0004 כהן \u0003שאינו ראוי\u0004 לעבודה, אינו חולק בקדשים. ושואלים על כך: \u0003ולא? והרי\u0004 כהן \u0003בעל מום,\u0004 \u0003דלא\u0004 \u0005[שאינו]\u0006 \u0003ראוי לעבודה,\u0004 \u0003ו\u0004בכל זאת הריהו \u0003חולק\u0004 בקדשים, וכפי ששנינו במשנתנו עצמה! \u0003ותו\u0004 \u0005[ועוד]:\u0006 מלשון המשנה \"כל שאינו ראוי לעבודה אינו חולק\", יש לדייק: \u0003הא\u0004 \u0005[אבל]\u0006 שכל ה\u0003ראוי לעבודה\u0004 — \u0003חולק.\u0004 ו\u0003הרי\u0004 כהן \u0003טמא בקרבנות ציבור\u0004 הקרבים בטומאה, \u0003ראוי\u0004 הוא \u0003לעבודה, ו\u0004בכל זאת \u0003אינו חולק!\u0004","ומשיבים: מה שאמרה המשנה \"שאינו ראוי לעבודה\" — \u0003ראוי לאכילה קאמר\u0004 \u0005[אמר],\u0006 שכל כהן שאינו ראוי לאכילה, אינו חולק בקדשים. ומקשים: לפי זה יש לדייק כי כל שראוי לאכילה חולק.","\u0003והרי\u0004 כהן \u0003קטן,\u0004 \u0003ראוי לאכילה, ואינו חולק!\u0004 ומשיבים: \u0003הא לא קתני\u0004 \u0005[\u0006דבר \u0005זה אינו שונה],\u0006 שכל שראוי לאכילה חולק, ולא באה המשנה להשמיענו אלא שהראוי לאכילה חולק.","ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך,\u0006 למסקנה זו\u0005],\u0006 שאין למדים ממשנה זו אלא מה שמפורש בה, אפשר לומר כך: \u0003לעולם\u0004 הסבר המשנה הוא \u0003כדקאמר מעיקרא\u0004 \u0005[כפי שאמר מתחילה],\u0006 שכל שאינו ראוי לעבודה אינו חולק. ולפי זה אין מקום לקושיות שהוקשו בתחילה, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום טמא\u0004 בקרבנות ציבור, שאינו חולק למרות שהוא ראוי לעבודה — \u0003טמא\u0004 כזה \u0003לא קתני\u0004 \u0005[שנה]\u0006 התנא במשנתנו שהוא חולק. שהרי כפי שאמרנו, אין המשנה באה ללמד שכל שראוי לעבודה חולק. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום בעל מום,\u0004 שאינו ראוי לעבודה, ובכל זאת הריהו חולק בקדשים — \u0003רחמנא רבייה\u0004 \u0005[התורה ריבתה אותו]\u0006 במיוחד שיהא חולק אף שאינו ראוי לעבודה, כפי שלמדנו לעיל מ\"כל זכר\".","עוד שנינו במשנה ש\u0003אפילו\u0004 היה הכהן \u0003טמא בשעת זריקת דמים\u0004 של הקרבן, \u0003וטהור בשעת הקטר חלבים\u0004 — \u0003אינו חולק\u0004 בו. ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 מי שהיה \u0003טהור בשעת זריקת דמים,\u0004 אף שהיה \u0003טמא בשעת הקטר חלבים\u0004 — \u0003חולק\u0004 בקדשים.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004דעת \u0003אבא שאול. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר: לעולם\u0004 הכהן \u0003אינו אוכל,\u0004 כלומר, אינו חולק בקדשים, \u0003עד שיהא טהור משעת זריקה עד שעת הקטר חלבים,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"המקריב את דם השלמים ואת החלב\u0004 מבני אהרן לו תהיה שוק הימין למנה\" (ויקרא ז, לג), לומר ש\u0003אפילו הקטר חלבים נמי בעי\u0004 \u0005[גם כן צריך]\u0006 שיהיה ראוי בו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי:\u0004 ולשיטת אבא שאול, אם \u0003נטמא\u0004 הכהן \u0003בינתיים\u0004 (בין זריקת הדם והקטרת החלבים), אך בשעת הזריקה וההקטרה היה טהור, \u0003מהו\u0004 דינו לענין אכילת קדשים? וצדדי השאלה, האם \u0003בשעת זריקה ובשעת הקטרה בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה הכהן טהור, \u0003והאיכא\u0004 \u0005[והרי\u0006 תנאי זה \u0005ישנו].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונת הדברים היא, שאין הכהן חולק בקדשים \u0003עד שיהא טהור משעת זריקה ועד שעת הקטר חלבים,\u0004 וכאן הרי נטמא בינתיים? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ובענין ששנינו במשנתנו, שטבול יום (שכבר טבל ונטהר מטומאתו, וממתין להערב שמש כדי להיטהר לגמרי) אינו חולק בקדשים, וכיוצא בזה אונן ומחוסר כיפורים, \u0003אמר רבא: האי דינא\u0004 \u0005[דין זה]\u0006 \u0003מר' אלעזר בר' שמעון גמירנא\u0004 \u0005[למדתי אותו],\u0006 ש\u0003אמר בבית הכסא: דנתה\u0004 יכול אתה לדון, ולומר כך בדרך סיפור מעשה שאירע: \u0003בא\u0004 כהן \u0003טבול יום\u0004 \u0003ואמר\u0004 לחבירו מאותו בית אב של כהנים, שהיה עובד בבית המקדש באותו יום וחולק בקדשים: \u0003תן לי\u0004 חלק \u0003ממנחה\u0004 של ישראל שבידך, \u0003ואוכל\u0004 ממנה בערב!","\u0003אמר לו\u0004 הכהן הטהור כך: \u0003ומה אם\u0004 קרבן חטאת, \u0003במקום ש\u0004שם \u0003יפה כחך בחטאתך,\u0004 שכשאתה מביא חטאת שלך יכול אתה להקריבה אף שלא בזמן משמרת הכהנים שלך, ואתה זכאי בבשרה — בכל זאת \u0003דחיתיך מחטאת ישראל,\u0004 שאין אתה יכול לחלוק עמי בבשרה, שהרי אתה טבול יום. מנחה, שהיא \u0003מקום שהורע כחך במנחתך,\u0004 שאינך אוכל ממנה, שהרי אין מנחת כהן נאכלת כלל, אלא עולה כליל — \u0003אינו דין שאדיחך\u0004 מלחלוק אתי \u0003ממנחת ישראל?\u0004","השיב לו טבול היום: אינו כן, \u0003ומה אם דחיתני מחטאת ישראל,\u0004 שבה אכן איני חולק, \u0003ש\u0004כן \u0003כשם שיפה כחי\u0004 בחטאת \u0003כך יפה כחך\u0004 בה, שהרי גם אתה ראוי להקריב חטאתך אף שלא בזמן בית אב שלי ושלך, האם \u0003תדחיני ממנחה\u0004 של ישראל? \u0003ש\u0004הרי \u0003כשם שהורע כחי\u0004 במנחה, שאיני אוכל ממנחתי, \u0003כך הורע כחך\u0004 בה, שאינך אוכל ממנחתך!","השיב לו הכהן הטהור, \u0003הרי הוא אומר\u0004 במנחה: \u0003\"לכהן המקריב אתה לו תהיה\"\u0004 (ויקרא ז, ט), אם רצונך ליטול בה חלק \u0003בא הקרב\u0004 מנחה \u0003ואכול\u0004 ממנה. והואיל ואינך יכול להקריבה, שהרי טבול יום אתה — אינך חולק בה.","חזר ואמר לו הכהן טבול היום לכהן הטהור: \u0003תן לי מחטאת ישראל ואוכל\u0004 אתך בערב, לכשאהיה ראוי לאכול בחטאת.","\u0003אומר לו\u0004 הכהן הטהור כך: \u0003ומה במקום שהורע כחי,\u0004 והוא \u0003במנחתי,\u0004 שאין אני רשאי לאכול בה, שהרי מנחת כהן אינה נאכלת — \u0003דחיתיך ממנחת ישראל,\u0004 וכמו שלמדנו מהפסוק \"לכהן המקריב אותה לו תהיה\", \u0003מקום שיפה כחי, בחטאתי,\u0004 שהרי אני זכאי להקריבה אף שלא בזמן בית אב שלי, וזוכה אני בה כולה, \u0003אינו דין שאדיחך מחטאת ישראל?\u0004","\u0003אמר לו\u0004 טבול היום כך: \u0003ומה אם שדחיתני ממנחת ישראל,\u0004 הרי זה משום \u0003שכשם שהורע כחך\u0004 במנחה, שהרי אינך אוכל ממנחתך, \u0003כך הורע כחי\u0004 בה, \u0003תדחיני מחטאת ישראל? ש\u0004הרי \u0003כשם שיפה כחך\u0004 בחטאתך \u0003כך יפה כחי\u0004 בחטאתי!","השיב לו הכהן הטהור: לכך \u0003הרי הוא אומר\u0004 לגבי חטאת: \u0003\"הכהן המחטא אתה יאכלנה\"\u0004 (ויקרא ו, יט), לומר שרק הכהן הזורק את הדם (\"המחטא\") הוא החולק בה. ואף אתה אם ברצונך בדבר — \u0003בא, חטא\u0004 (זרוק את הדם) \u0003ו\u0004תהיה זכאי לחלוק בה ול\u0003אכול\u0004 ממנה בערב. וכיון שאינך ראוי לזרוק את הדם בהיותך טבול יום, אף אינך חולק בה.","ועוד, חזר ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 טבול היום לכהן הטהור: \u0003תן לי מחזה ושוק\u0004 חלק הכהנים שמפרישים מהשלמים, \u0003ואוכל\u0004 בערב, לכשאהיה ראוי לאכול מהקדשים.","\u0003אמר ליה\u0004 \u0005[לו],\u0006 יכול להשיבו הכהן הטהור כך: \u0003ומה במקום שיפה כחך, בחטאתך\u0004 שלך, שהרי זכאי אתה בה להקריבה בכל זמן והיא כולה שלך, \u0003דחיתיך [מחטאת ישראל] (מחזה ושוק)\u0004 שאין אתה חולק בה, וכפי שלמדנו מהפסוק האמור בה: \"הכהן המחטא אותה יאכלנה\", \u0003מקום שהורע כחך,\u0004 כלומר \u0003ב\u0004קרבן \u0003שלמים, שאין לך בהן אלא חזה ושוק\u0004 ולא כל בשר הקרבן, כמו בקרבן חטאת — \u0003אינו דין שאדיחך\u0004 מלחלוק אתי בהם?","השיב לו הכהן טבול היום: אין זו השוואה צודקת, שכן \u0003מה אם\u0004 אכן \u0003דחיתני מחטאת,\u0004 הרי זה משום \u0003שכן הורע\u0004 בה \u0003כחי אצל נשיי ועבדיי,\u0004 שאיני יכול להאכילם ממנה, שהרי אין החטאת נאכלת אלא לכהנים זכרים בלבד, האם \u0003תדחיני מחזה ושוק\u0004 של שלמים, \u0003שכן יפה כחי\u0004 בהם \u0003אצל נשיי ועבדי,\u0004 שכן אני מאכיל אותם מחזה ושוק?","השיב לו הכהן הטהור, לכך \u0003הרי הוא אומר\u0004 בשלמים: \u0003\"לכהן הזורק את דם השלמים לו יהיה\"\u0004 (ויקרא ז, יד), \u0003בא זרוק\u0004 מדם השלמים, \u0003ו\u0004תוכל לחלוק בהם ול\u0003אכול\u0004 מהם לערב. וכיון שאינך ראוי לכך, בהיותך טבול יום, אף אינך חולק בהם.","ובסופו של דבר, \u0003יצא טבול יום\u0004 בפחי נפש עם \u0003קוליו וחמוריו\u0004 דרשות הקל וחומר הללו שטען, \u0003על ראשו,\u0004 בלא שיזכה בחלק כלשהו מן הקדשים, ושני חבריו עמו, כהן \u0003אונן\u0004 \u0003מימינו מחוסר כפרה משמאלו,\u0004 שגם הם נדחים מחלוקת הקדשים בעקבות דיון זה, שהרי גם הם אינם ראויים לעבודה.","\u0003פריך\u0004 \u0005[מקשה]\u0006 \u0003רב אחאי:\u0004 יוסיף ר' אלעזר בר' שמעון עוד חלק לדיון זה, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 הכהן טבול היום לכהן הטהור: \u0003תן לי מ\u0004קרבן \u0003בכור\u0004 שבידך, \u0003ואוכל\u0004 ממנו לערב!","ויש להשיב: \u0003משום\u0004 שכך \u0003אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 הטהור לטבול היום: \u0003ומה במקום שהורע כחי, בחטאת, אצל נשיי ועבדיי\u0004 שאיני זכאי לתת להם מבשרה (שאינה נאכלת אלא לכהנים זכרים), בכל זאת \u0003דחיתיך מחטאת ישראל\u0004 שאינך חולק בה, וכמו שלמדנו מהפסוק \"הכהן המחטא אותה יאכלנה\", \u0003מקום שיפה כחי,\u0004 \u0003בבכור, דכוליה דילי\u0004 \u0005[שכולו שלי]\u0006 \u0003היא,\u0004 שהבכור ניתן לכהן מסויים והוא מקריבו, ושלו הוא — \u0003אינו דין שאדחך ממנו?\u0004","משיב לו הכהן טבול היום: \u0003ומה אם דחיתני מחטאת, שכשם שהורע כחך\u0004 בה \u0003כך הורע כחי,\u0004 אבל האם גם \u0003תדיחני מבכור? ש\u0004הרי \u0003כשם שיפה כחך כך יפה כחי\u0004!","משיב לו הכהן הטהור, לכך \u0003הרי הוא אומר\u0004 לגבי הבכור: \u0003\"את דמם תזרק על המזבח ואת חלבם תקטיר... ובשרם יהיה לך\"\u0004 (במדבר יח, יז — יח), ללמדנו שהזורק את הדם הוא האוכל מבשרם, ואף אתה אם ברצונך לחלוק בהם — \u0003בא, זרוק ואכול.\u0004 הרי שניתן היה להוסיף שלב נוסף זה לגבי בכור, וללמוד מן הכתובים שאין טבול יום חולק בבשרו!","ומסבירים: לא ניתן היה לומר כך, שכן \u0003ואידך\u0004 \u0005[והאחר]\u0006 טבול היום \u0003פריך\u0004 \u0005[מקשה]\u0006 על ראיה זו מן הכתוב, שכן \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ובשרם לכהן הזורק\"\u0004 כדרך שנאמר לגבי המנחה, החטאת, וכן החזה והשוק? הלוא \u0003\"ובשרם יהיה לך\" כתיב\u0004 \u0005[נאמר],\u0006 באופן כללי, לכל הכהנים ומכלל פסוק זה ניתן ללמוד ש\u0003אפילו לכהן אחר\u0004 שאינו מקריב, גם כן יהיה הבכור. ומשום כך לא הביא ר' אלעזר בר' שמעון דיון זה. ושבים לדברי רבא, שאמר כי ר' אלעזר בר' שמעון אמר דברים אלו בבית הכסא.","ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[ואיך עשה\u0006 כך\u0005]\u0006 ר' אלעזר בר' שמעון? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: בכל מקום מותר להרהר\u0004 בדברי תורה, \u0003חוץ מ\u0004בית ה\u0003מרחץ ומבית הכסא,\u0004 שבמקומות המטונפים כגון אלו גנאי הוא לעסוק בהם בתורה! ומשיבים: מקרה בו נעשה הדבר \u0003לאונסו שאני\u0004 \u0005[שונה],\u0006 שכיון שהיה טרוד כל כך בדברים שחשב עליהם, דרש דרשה זו באותו מקום."],["\u0003כל\u0004 קרבן עולה \u0003שלא זכה המזבח בבשרה,\u0004 כגון שאירע בה פסול לפני זריקת דמה, \u0003לא זכו כהנים בעורה. ש\u0004כן \u0003נאמר\u0004 בפרשת העולה: \"והכהן המקריב את \u0003עלת איש,\u0004 עור העולה אשר הקריב לכהן לו יהיה\" (ויקרא ז, ח), ללמדנו: הכהן זכאי דווקא בעור \u0003עולה שעלתה לאיש,\u0004 לבעליה, שיצאו בה ידי חובתה. וזו שלא עלתה לבעליה, אין עורה לכהנים.","ומכל מקום \u0003עולה שנשחטה שלא לשמה,\u0004 אלא לשם קרבן אחר, \u0003אף על פי שלא עלתה לבעלים\u0004 בכל זאת \u0003עורה לכהנים.\u0004 וכן אף על פי שנאמר \"עולת איש\", מכל מקום \u0003אחד עולת האיש\u0004 שהביא קרבנו \u0003ואחד עולת האשה\u0004 שהביאה קרבנה — \u0003עורותיהן לכהנים.\u0004","ועוד הלכה, \u0003עורות קדשים קלים\u0004 שייכים \u0003לבעלים, עורות קדשי קדשים\u0004 (חטאות ואשמות וזבחי שלמי ציבור) שייכים \u0003לכהנים.\u0004 ולמדים זכות זו של הכהנים בעורות קדשי קדשים מ\u0003קל וחומר, ומה אם עולה, שלא זכו\u0004 הכהנים \u0003בבשרה,\u0004 שהרי היא עולה כליל, \u0003זכו בעורה,\u0004 כמפורש בכתוב (ויקרא ז, ח), \u0003קדשי קדשים\u0004 אחרים, \u0003שזכו\u0004 הכהנים \u0003בבשרה, אינו דין שיזכו בעורה?\u0004 ומוסיפים: ו\u0003אין\u0004 מקום לטעון ש\u0003מזבח יוכיח\u0004 כנגד לימוד זה, שהרי הוא זוכה בבשר העולה ואינו זוכה בעורה. משום \u0003שאין לו\u0004 זכות ב\u0003עור\u0004 הקרבן \u0003בכל מקום\u0004 בשום קרבן, ואילו הכהנים הרי זוכים בעור העולה, ומתוך כך יש ללמוד בקל וחומר שזוכים הם אף בעורות קדשי הקדשים.","ועוד בדיני זכות הכהנים בעור העולה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בפרשת העולה: \"והכהן המקריב את עולת איש עור העולה אשר הקריב לכהן לו יהיה\" (ויקרא ז, ח). והביטוי \u0003\"עלת איש\"\u0004 הרי זה בא למעט: \u0003פרט לעולת הקדש,\u0004 שאין עורה לכהנים, אלו \u0003דברי ר' יהודה. ר' יוסי בר' יהודה אומר: פרט לעולת גרים,\u0004 שאין עורה לכהנים.","ומבררים את דברי ר' יהודה שבברייתא: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פרט לעולת הקדש\"\u0004, איזו עולה יש להקדש? \u0003אמר ר' חייא בר יוסף: פרט לעולה הבאה מן המותרות\u0004 כגון אשם שנותר לאחר שנתכפרו בעליו, שממתינים עד שייפול בו מום, ומוכרים אותו, ומדמיו מביאים עולות נדבה של ציבור בזמן שלא היו עליו קרבנות אחרים (\"קיץ המזבח\"). ואלו, אין עורותיהם לכהנים, משום שאין הם בגדר \"עולת איש\", אלא עולת ציבור.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003מותרות לנדבת ציבור אזלי\u0004 \u0005[הולכות],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003מותרות לנדבת יחיד אזלי\u0004 \u0005[הולכות],\u0006 שבעליו של קרבן האשם הוא המביא עולה בדמי האשם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע לא יזכו הכהנים בעור עולה זו? הרי \"עולת איש\" היא!","ומשיבים: \u0003כ\u0004מו ש\u0003אמר רבא\u0004 על הכתוב: \"...ובער עליה הכהן עצים בבקר בבקר וערך עליה העולה\" (ויקרא ו, ה): ש\u0003\"העלה\"\u0004 בה\"א הידיעה כוונתו ה\u0003עולה ראשונה,\u0004 ללמד שעולת התמיד היא הקרבן הקרב בראשונה בכל יום במקדש. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נפרש שכוונת הנאמר \"עור \u0003העלה\u0004 אשר הקריב לכהן לו יהיה\" — \u0003עולה ראשונה,\u0004 שהפריש אדם לשם עולה — היא זו שזוכה הכהן בעורה, ולא עור העולה שבאה מן המותרות של קרבן אחר.","\u0003ר' אייבו אמר ר' ינאי:\u0004 מה שאמר ר' יהודה בברייתא: \"עולת איש\" פרט לעולת הקדש, כוונתו: \u0003פרט למתפיס\u0004 (מקדיש) \u0003עולה\u0004 שלו \u0003ל\u0004הקדש \u0003בדק הבית,\u0004 ללמדנו שאין עורה ניתן לכהנים.","ומעירים: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 הלכה זו רק \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003קדשי בדק הבית תפסי מדאורייתא\u0004 \u0005[תופסים,\u0006 חלים, \u0005מן התורה]\u0006 על קדשי מזבח, שלשיטתם בוודאי עולת הקדש היא, ולא \"עולת איש\". \u0003אלא אפילו למאן דאמר לא תפסי\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר\u0006 ש\u0005אינם תופסים],\u0006 לפי שכבר הוקדשה העולה למזבח — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא לגבי \u0003בשר\u0004 העולה העומד להקרבה, ושייך למזבח, ואינו של ההקדש. \u0003אבל\u0004 לגבי ה\u0003עור,\u0004 שממילא אין המזבח עתיד לזכות בו — \u0003תפיס\u0004 \u0005[תופס]\u0006 ההקדש לבדק הבית. ולכן אין הוא \"עולת איש\", ואינו ניתן לכהנים.","ושבים לפירושו של ר' חייא בר יוסף בענין זה, ומעירים: \u0003וכן\u0004 \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 מה שאמר ר' יהודה \"פרט לעולת הקדש\" כוונתו — \u0003פרט לעולה הבאה מן המותרות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא לרב נחמן: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר את הסברך זה, \u0003כ\u0004דעת \u0003ר' יהודה\u0004 שמצאנו כי הוא סבור שאין הכהנים זוכים בעורה? \u0003הא הדר ביה\u0004 \u0005[הרי חזר בו]\u0006 ר' יהודה מדבריו אלו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 מה ששנינו שבמקדש היו \u0003ששה\u0004 שופרות (קופות שצורתן כשופר) המיועדים \u0003לנדבה,\u0004 הכוונה היא \u0003לעולה הבאה מן המותרות,\u0004 שמי שהפריש סכום כסף לקרבנו, ולאחר שקנאו נמצא בידו כסף יתר, היה נותנו בשופרות אלו. ודינה של עולה הבאה מן המותרות \u0003שלא יהו כהנים זכאין בעורה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","ועל כך \u0003אמר לו ר' נחמיה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' שמעון: אם כן, ביטלת מדרשו של יהוידע הכהן! דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005],\u0006 \u0003זה מדרש דרש יהוידע הכהן\u0004 על הכתוב \u0003\"אשם הוא אשם אשם לה'\"\u0004 (ויקרא ה, יט): \u0003כל שבא משום חטאת ומשום אשם\u0004 שהפריש כסף לקניית חטאת או אשם, ונותר לו סכום מסויים לאחר הקנייה — \u0003ילקח בו עולות, הבשר\u0004 יהיה \u0003לשם, עורה\u0004 יהיה \u0003לכהנים.\u0004 וכיון שלא השיב ר' יהודה, משמע שחזר בו מדבריו, ואף הוא מודה שעור העולה הבאה מן המותרות הריהו לכהנים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרב המנונא בתשובה: \u0003אלא מר, במאי מוקים לה\u0004 \u0005[אדוני, במה מעמיד,\u0006 מסביר \u0005אותה]\u0006 לשון ר' יהודה שבברייתא \"פרט לעולת הקדש\"? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מוקמינא ליה\u0004 \u0005[אני מעמיד אותו]\u0006 \u0003ב\u0004אדם ה\u0003מקדיש\u0004 את כל \u0003נכסיו\u0004 כולם, ובכללם יש בהמות הראויות לעולה. שאף שהן קרבות לעולה — עולות הקדש הן, ואין עורן לכהנים.","\u0003וכ\u0004שיטת \u0003ר' יהושע\u0004 בעניין זה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו\u0004 למקדש בסתם, והרי זו הקדשה לבדק הבית, \u0003והיו בהן בהמות הראויות\u0004 להקרבה \u0003לגבי מזבח,\u0004 \u0003זכרים ונקבות, ר' אליעזר אומר:\u0004 כל הראוי למזבח, צריך ליקרב עליו. ולכן \u0003זכרים\u0004 — \u0003ימכרו לצורכי עולות,\u0004 שיקריבום על המזבח כעולה. \u0003נקבות,\u0004 שאין מביאים מהן עולה — \u0003ימכרו לצורכי זבחי שלמים. ו\u0004הואיל והוקדשו לבדק הבית \u0003דמיהן יפלו עם שאר נכסים\u0004 שהקדיש \u0003לבדק הבית.\u0004","\u0003ר' יהושע אומר:\u0004 כל דבר הראוי למזבח, מתכוון האדם שיקרב כעולה על המזבח. ולכן, \u0003זכרים עצמם\u0004 שיש שם — \u0003יקרבו עולות. ונקבות,\u0004 שאין מביאים מהן קרבן עולה — \u0003ימכרו לצורכי שלמים ויביא בדמיהן עולות. ושאר נכסים יפלו לבדק הבית.\u0004","\u0003ו\u0004בזכרים הקרבים עצמם כעולות אין הכהנים נוטלים את העור. שכן \u0003אפילו ל\u0004דעת \u0003ר' יהושע\u0004 ש\u0003אמר: אדם\u0004 המקדיש נכסיו \u0003חולק הקדישו,\u0004 ומה שראוי למזבח הריהו מתכוון להקדישו לעולה לה', \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא לגבי \u0003בשר\u0004 העולה, הקרב על גבי המזבח, \u0003אבל\u0004 את ה\u0003עור\u0004 שאינו ראוי למזבח, \u0003תפיס\u0004 \u0005[תופס]\u0006 מתחילה הקדש בדק הבית, ולכן אין לכהנים חלק בו, כפי שדורש ר' יהודה מ\"עולת איש\".","עוד שנינו בברייתא ש\u0003ר' יוסי בר' יהודה אומר:\u0004 \"עולת איש\" — \u0003פרט לעולת גרים,\u0004 שאין הכהנים זוכים בעורה. על דרשה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סימאי בר חילקאי לרבינא: אטו\u0004 \u0005[וכי]\u0006 \u0003גר לאו\u0004 \u0005[אין]\u0006 \u0003איש הוא? אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא, \u0003פרט לגר שמת ואין לו יורשים.\u0004 והרי זו עולה שאין לה בעלים, ואין הכהנים זוכים בעורה.","ועוד בענין דיני עור העולה ששנינו במשנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \"והכהן המקריב את \u0003עלת איש\u0004 עור העולה אשר הקריב לכהן לו יהיה\" (ויקרא ז, ח). ויש לשאול: \u0003אין לי\u0004 שזוכים הכהנים \u0003אלא\u0004 בעור של \u0003עולת איש,\u0004 גבר שהוא מישראל, בעור \u0003עולת גרים נשים ועבדים מנין\u0004 לנו? \u0003תלמוד לומר\u0004 מיד אחר כך: \u0003\"עור העלה\u0004 אשר הקריב\", ובכך \u0003ריבה\u0004 גם את אלו.","\u0003ואם כן, מה תלמוד לומר \"עלת איש\"?\u0004 הרי זה בא ללמד: דווקא עור \u0003עולה שעלתה לאיש\u0004 לשם חובתו, \u0003פרט ל\u0004עור עולה \u0003שנשחטה חוץ לזמנה וחוץ למקומה,\u0004 שלא עלתה לבעלים, שהרי נפסלה, \u0003שלא יהו הכהנים זכאין בעורה.\u0004","\u0003יכול שאני מרבה\u0004 אף עולה \u0003שנשחטה שלא לשמה,\u0004 לומר: \u0003הואיל ולא עלתה לבעלים\u0004 לשם חובתם"],["לכן \u0003לא יהו כהנים זכאין בעורה? תלמוד לומר: \"עור העלה\"\u0004 (ויקרא ז, ח), \u0003מכל מקום,\u0004 לרבות עולה שנשחטה שלא לשמה, מאחר ומכל מקום זכה בה המזבח.","ועוד דורשים, נאמר \u0003\"עור העלה\", אין לי אלא עור העולה\u0004 בלבד שהוא לכהנים, \u0003עורות\u0004 שאר \u0003קדשי קדשים מנין? תלמוד לומר: \"עור העלה אשר הקריב\"\u0004 (ויקרא ז, ח), לרבות כל אשר הקריב. \u0003יכול שאני מרבה אף קדשים קלים\u0004 בכלל זה? \u0003תלמוד לומר: \"עלה\",\u0004 ולא הזכיר בסתם \"כל אשר הקריב\", ומכאן אני למד: \u0003מה עולה\u0004 שהיא \u0003קדשי קדשים, אף כל\u0004 שהוזכר בענין זה הוא \u0003קדשי קדשים,\u0004 ולא בעור קדשים קלים.","\u0003ר' ישמעאל אומר\u0004 מקור אחר לדברים: \u0003\"עור העלה\"\u0004 — \u0003אין לי אלא\u0004 עור \u0003העולה\u0004 שהנהנים זוכים בו, \u0003עורות\u0004 שאר \u0003קדשי קדשים, מנין\u0004 לנו? \u0003ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא: ומה עולה, שלא זכו\u0004 הכהנים \u0003בבשרה\u0004 שהרי הכל עולה למזבח — בכל זאת \u0003זכו בעורה. קדשי קדשים, שזכו בבשרן\u0004 — \u0003אינו דין שזכו בעורן?\u0004","וכנגד זה אפשר לטעון: \u0003מזבח\u0004 עצמו \u0003יוכיח\u0004 שלא כקל וחומר זה, \u0003ש\u0004כן \u0003זכה\u0004 בעולה \u0003בבשר, ולא זכה בעור!\u0004 ודוחים ראיה זו מהמזבח: \u0003מה למזבח שכן לא זכה במקצת\u0004 עורות, שהרי אין המזבח זוכה כלל בעורות הקרבנות, \u0003תאמר בכהנים שזכו במקצת\u0004 עורות הקרבנות, כמפורש בתורה לענין עור העולה. ולכן יש מקום לומר: \u0003הואיל וזכו\u0004 הכהנים \u0003במקצת\u0004 בעור העולה, \u0003זכו בכוליה\u0004 \u0005[ב\u0006עור קדשי הקדשים \u0005כולם].\u0006","\u0003רבי אומר:\u0004 אין צורך ללימוד מיוחד לגבי עורות שאר קדשי קדשים, שכן \u0003כל עצמו\u0004 של דין זה, שעורות ניתנים לכהנים, \u0003לא הוצרכנו\u0004 לו \u0003אלא ל\u0004ענין \u0003עור העולה בלבד,\u0004 לפי \u0003שבכל מקום\u0004 לא ציותה התורה להפשיט את עור הקרבן. ולכן \u0003העור\u0004 של הקרבן \u0003מהלך אחר הבשר\u0004 של הקרבן, ונידון כמוהו:","\u0003פרים הנשרפין ושעירים הנשרפין\u0004 — \u0003הן ועורותיהן נשרפין עמהן,\u0004 כמפורש בכתוב (ראה ויקרא ד, יב). \u0003חטאת ואשם וזבחי שלמי ציבור\u0004 הרי הם כולם \u0003מתנה לכהן\u0004 (ראה ויקרא ז ז; ויקרא כג, כ), אם \u0003רצו\u0004 — \u0003מפשיטין אותן\u0004 ומשתמשים בעור לעצמו, \u0003לא רצו\u0004 — \u0003אוכלין אותן על גבי\u0004 (יחד עם) \u0003עורן. קדשים קלים\u0004 כולם \u0003לבעלים,\u0004 ולכן אם \u0003רצו\u0004 — \u0003מפשיטין אותן\u0004 ומשתמשים בעור, \u0003רצו\u0004 — \u0003אוכלין אותן על גב עורן.\u0004","\u0003אבל עולה נאמר בה: \"והפשיט את העלה ונתח אתה לנתחיה\"\u0004 (ויקרא א, ו). \u0003יכול\u0004 שכיון שבשרה עולה למזבח \u0003לא יהו הכהנים זכאין בעורה?\u0004 לכן \u0003תלמוד לומר: \"עור העלה אשר הקריב\u0004 לכהן לו יהיה\" (ויקרא ז, ח). כלומר, לכהן אשר הקריב — יהיה העור.","ומה שנאמר \u0003\"לו יהיה\"\u0004 בא למעט: \u0003פרט לטבול יום ומחוסר כיפורים ואונן,\u0004 שאינם חולקים בעורות, כדרך שאינם חולקים בבשר הקדשים. \u0003שיכול\u0004 הייתי לומר: \u0003לא יזכו בבשר, ש\u0004כן \u0003הוא\u0004 מיועד \u0003לאכילה,\u0004 והם אינם רשאים לאכול, אבל \u0003יזכו בעור שאינו לאכילה! תלמוד לומר \"לו יהיה\"\u0004 — \u0003פרט למחוסר כיפורים וטבול יום ואונן.\u0004 ונפנים עתה לבירור השיטות השונות שבברייתא זו למקור הדין שהכהנים נוטלים עורות קדשי קדשים, ולא רק עור העולה.","ושואלים: \u0003ותנא קמא נמי, תיפוק לי מדינא\u0004 \u0005[והתנא הראשון גם כן, תצא לו\u0006 הלכה זו \u0005מן הדין,\u0006 מן הקל וחומר שאמר ר' ישמעאל\u0005],\u0006 ולא יצטרך ללימוד מיוחד! ומשיבים: אכן, אפשר היה ללמוד זאת מקל וחומר, ואולם כלל בידינו שגם \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר, טרח וכתב לה קרא\u0004 \u0005[טורח וכותב אותו המקרא].\u0006","ושואלים לצד השני: \u0003ור' ישמעאל, האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"אשר הקריב\"\u0004 ממנו למד התנא הראשון דין זה, \u0003מאי עביד ליה\u0004 \u0005[מה עושה,\u0006 לומד הוא \u0005בו]?\u0006 ומסבירים: ללמדנו מיעוט, \u0003פרט לטבול יום ומחוסר כיפורים ואונן,\u0004 שאינו ראוי להקרבה, ולכן אינו זכאי בעור הקרבן.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 הלכה זו \u0003מ\u0004מה שנאמר \u0003\"לו יהיה\",\u0004 שלמד רבי בסוף ברייתא זו! ומשיבים: \u0003ר' ישמעאל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שהוא דורש \"לו יהיה\" לענין אחר, ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: נאמר בעולה \"לו יהיה\", ונאמר באשם \"לו יהיה\"\u0004 (ויקרא ז, ז), לגזירה שווה: \u0003מה להלן\u0004 באשם \u0003עצמותיו מותרין\u0004 בשימוש גם לאחר זמן האכילה, ואינם חלק מבשר הקרבן, \u0003אף כאן\u0004 בעולה, למרות שהקרבן עולה כליל — \u0003עצמותיו מותרין.\u0004","וצריכים לומר בהכרח שלשיטתו ביטוי זה \u0003מופני\u0004 \u0005[מופנה]\u0006 רק לדרשה זו, ואין דין נוסף שנצרך להילמד ממנו. משום \u0003דאי לא מופני\u0004 \u0005[שאם אינו מופנה],\u0006 \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את הגזירה השווה, ולומר: \u0003מה לאשם שכן בשרו מותר\u0004 לכהנים, ולכן גם עצמותיו מותרות להם, מה שאין כן בעולה שבשרה אסור לכהנים. אלא בהכרח הכתוב \u0003\"לו יהיה\" קרא יתירא\u0004 \u0005[מקרא יתיר]\u0006 \u0003הוא\u0004 שלא היה נחוץ לעניינו, אלא בא רק לגזירה שווה. שכלל הוא שגזירה שווה המבוססת על מקראות שהופנו לשם כך, אין פורכים אותה.","ועוד בדיני זכות הכהנים בעורות הקרבנות. \u0003כל הקדשים\u0004 (קדשי קדשים) \u0003שאירע בהן פסול קודם להפשיטן\u0004 של עורותיהם מעליהם — \u0003אין עורותיהן\u0004 ניתנים \u0003לכהנים,\u0004 אלא נשרפים יחד עם הבשר בבית השריפה. אם אירע בהם פסול \u0003לאחר הפשיטן\u0004 — \u0003עורותיהן לכהנים.\u0004 ועל הדין הראשון, שכשאירע הפסול קודם הפשט, אין העור ניתן לכהנים, אלא נשרף עם הבשר, \u0003אמר ר' חנינא סגן הכהנים:\u0004 \u0003מימי לא ראיתי\u0004 בבית המקדש \u0003עור\u0004 של קדשי קדשים שהופשט, \u0003ש\u0004אינו ניתן לכהנים אלא \u0003יוצא לבית השריפה.\u0004","\u0003אמר ר' עקיבא: מדבריו\u0004 של ר' חנינא סגן הכהנים \u0003למדנו, שהמפשיט את\u0004 עור קרבן \u0003הבכור,\u0004 \u0003ונמצא\u0004 לאחר מכן שכבר היה \u0003טריפה\u0004 בזמן ההפשט — \u0003ש\u0004בכל זאת \u0003יאותו\u0004 (ייהנו) \u0003הכהנים בעורו.\u0004 \u0003וחכמים אומרים\u0004 ביחס לדברי ר' רבי חנינא סגן הכהנים: \u0003אין\u0004 טענת \u0003\"לא ראינו\"\u0004 יכולה לשמש \u0003ראיה, אלא\u0004 יש ללכת לפי ההלכה, ואם לאחר שהופשט נמצא שהיה הקרבן פסול, קודם ההפשט — \u0003יצא\u0004 העור \u0003לבית השריפה.\u0004","שנינו במשנה הקודמת כי \u0003כל\u0004 עולה \u0003שלא זכה המזבח בבשרה,\u0004 וכגון שנפסל הבשר קודם שנזרק הדם, וכך לא היתה לו שעת היתר למזבח — \u0003לא זכו הכהנים בעורה. ו\u0004ממה שלא חילקה המשנה בדבר, יש להבין כי אין הכהנים זוכים בעורה \u0003אף על גב דאפשטיה\u0004 \u0005[אף על פי שהפשיט אותו]\u0006 את ה\u0003עור קודם\u0004 ה\u0003זריקה\u0004 של הדם. ולפי זה, משנה זו כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003ר' אלעזר בר' שמעון היא,\u0004 ש\u0003אמר: אין הדם מרצה על העור בפני עצמו,\u0004 אפילו אם הופשט, אלא רק כאשר הוא מרצה על הבשר ומתירו למזבח. ובמקרה זה שנפסל הבשר, כיון שאין הזריקה מרצה על הבשר להתירו למזבח — אף אינה מרצה על העור להתירו לכהנים.","אולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה, כלומר את משנתנו שלנו: \u0003כל הקדשים שאירע בהן פסול קודם הפשיטן\u0004 — \u0003אין עורותיהן לכהנים, לאחר הפשיטן\u0004 — \u0003עורותיהן לכהנים,\u0004 ומשמע שאם כבר הופשט העור, אפילו אירע הפסול קודם זריקת הדם — הריהו לכהנים. \u0003אתאן\u0004 \u0005[באנו]\u0006 בכך \u0003ל\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר: הדם מרצה על העור בפני עצמו.\u0004 ויש לתמוה: \u0003רישא\u0004 \u0005[ראשה]\u0006 של המשנה הוא כדעת \u0003ר' אלעזר בר' שמעון,\u0004 ו\u0003סיפא\u0004 \u0005[סופה]\u0006 כדעת \u0003רבי?\u0004","\u0003אמר אביי: מדסיפא\u0004 \u0005[מכיון שסופה]\u0006 שיטת \u0003רבי היא,\u0004 יש לומר כי \u0003רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 שיטת \u0003רבי היא. ו\u0004אף על פי שלשיטתו יכולים הכהנים לזכות בעור, אם הופשט קודם שנפסל הבשר, מכל מקום \u0003מודה רבי שאין\u0004 עושים \u0003הפשט\u0004 העור מן הבשר \u0003קודם זריקה,\u0004 ונמצא שלמעשה מתקיים דין המשנה, שכל שלא זכה המזבח בבשרה (ואין המזבח זוכה בבשר עד שייזרק הדם) — לא זכו הכהנים בעורה.","\u0003רבא אמר\u0004 להיפך: \u0003מדרישא\u0004 \u0005[מכיון שראשה]\u0006 של המשנה שיטת \u0003ר' אלעזר בר' שמעון\u0004 היא, הסבור כי אין זריקת הדם מרצה על העור אם נפסל הבשר — \u0003סיפא נמי\u0004 \u0005[סופה גם כן,\u0006 משנתנו\u0005]\u0006 כשיטת \u0003ר' אלעזר בר' שמעון\u0004 היא. ואף שנאמר במשנתנו שאם אירע הפסול לאחר הפשט, זוכים הכהנים בעור, יש להבין כי הכוונה היא שאירע הפסול בבשר לאחר שנזרק הדם. ולפי זה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קודם הפשט\",\u0004"],["\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אחר הפשט\"\u0004 השנויים במשנתנו? כוונתם: \u0003קודם\u0004 זריקת הדם \u0003ש\u0004אז \u0003נראו\u0004 (נעשו ראויים) \u0003להפשט,\u0004 ו\u0003אחר\u0004 זריקת הדם \u0003ש\u0004אז \u0003נראו להפשט.\u0004","כיון שהוזכרה מחלוקת רבי ור' אלעזר בן ר' שמעון, מבררים: \u0003מאי\u0004 \u0005[מה]\u0006 היא שיטתו זו של \u0003רבי ומאי\u0004 \u0005[ומה]\u0006 היא שיטתו של \u0003ר' אלעזר בר' שמעון\u0004 שנחלקו בה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: הדם מרצה על העור\u0004 כשהוא \u0003בפני עצמו,\u0004 כלומר, לאחר שהופשט, גם אם הבשר נפסל. וכשהוא עדיין \u0003עם הבשר,\u0004 ו\u0003נולד בו פסול\u0004 בבשר, \u0003בין קודם זריקה\u0004 של הדם \u0003בין לאחר זריקה\u0004 — \u0003הרי הוא כיוצא בו,\u0004 כדין הבשר, שנשרף, כך דין העור.","\u0003ר' אלעזר בר' שמעון אומר: אין הדם מרצה על העור בפני עצמו,\u0004 אם נפסל הבשר. \u0003וכשהוא\u0004 עדיין \u0003עם הבשר,\u0004 אם \u0003נולד בו\u0004 בבשר \u0003פסול קודם זריקה\u0004 — \u0003הרי הוא\u0004 העור \u0003כיוצא בו,\u0004 ושניהם נשרפים. נולד פסול בבשר \u0003אחר זריקה\u0004 — הרי כבר \u0003הורצה בשר שעה אחת,\u0004 ולכן, אף על פי שאחר כך נפסל — \u0003יפשיטנו\u0004 קודם שיישרף, \u0003ועורו לכהנים.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם לומר],\u0006 כי \u0003ב\u0004מחלוקת \u0003ר' אליעזר ור' יהושע קמיפלגי\u0004 \u0005[חלוקים הם]?\u0006 שנאמר: \u0003\"ועשית עלתיך הבשר והדם\"\u0004 (דברים יב, כז), ויש לשאול: לשם מה הובאו כאן יחד \"הבשר והדם\" והוקשו זה לזה? \u0003ר' יהושע אומר,\u0004 ללמד: \u0003אם אין דם\u0004 על המזבח — \u0003אין בשר\u0004 עולה על המזבח, \u0003אם אין בשר\u0004 — \u0003אין\u0004 זורקים את ה\u0003דם.\u0004","\u0003ר' אליעזר אומר: דם\u0004 יזרק \u0003אף על פי שאין בשר, שנאמר: \"ודם זבחיך ישפך\"\u0004 (דברים יב, כז). \u0003אם כן, מה תלמוד לומר\u0004 לפי זה \u0003\"ועשית עלתיך הבשר והדם\"? לומר לך: מה דם\u0004 ניתן על המזבח \u0003בזריקה, אף בשר בזריקה, הא\u0004 \u0003למדת\u0004 מכאן \u0003שריוח\u0004 משהו \u0003יש בין כבש למזבח,\u0004 ומעליו זורקים את הבשר למזבח.","ומעתה, האם \u0003לימא\u0004 \u0005[נאמר]\u0006 כי \u0003מאן דאמר\u0004 \u0005[מי שאומר]:\u0006 \u0003הורצה\u0004 העור בפני עצמו, סבור \u0003כ\u0004דעת \u0003ר' אליעזר\u0004 שאמר שזורקים את הדם אף על פי שאין בשר, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]:\u0006 \u0003לא הורצה\u0004 העור בפני עצמו, \u0003כ\u0004דעת \u0003ר' יהושע\u0004 שאמר שאם אין בשר אין דם?","ודוחים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' אליעזר כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 שהואיל והוא מתיר לזרוק את הדם לכתחילה, בוודאי הורצה העור בפני עצמו, וכשיטת רבי. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהושע,\u0004","\u0003מאן דאמר\u0004 \u0005[מי שאומר]:\u0006 \u0003לא הורצה\u0004 העור בפני עצמו, הרי זה בפשטות \u0003כ\u0004דברי \u0003ר' יהושע\u0004 הסבור שאין זורקים את הדם כשנפסל הבשר, ואם זרק — לא הורצה. \u0003מאן דאמר\u0004 \u0005[מי שאומר]:\u0006 \u0003הורצה, אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 שאין זורקים את הדם, \u0003אלא ב\u0004כשהשאלה נוגעת ל\u0003בשר\u0004 בלבד, \u0003דליכא פסידא\u0004 \u0005[שאין הפסד]\u0006 \u0003לכהנים. אבל\u0004 כשהשאלה נוגעת ל\u0003עור,\u0004 כשהוא בפני עצמו, \u0003דאיכא פסידא\u0004 \u0005[שיש הפסד]\u0006 \u0003לכהנים\u0004 אם לא ינתן להם, \u0003אפילו ר' יהושע מודה\u0004 שהדם מרצה.","\u0003מידי דהוה אדיעבד\u0004 \u0005[כמו שהוא\u0006 הדין לגבי בשר שנפסל, אם זרק את הדם \u0005בדיעבד],\u0006 \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003נטמא בשר או נפסל, או שיצא חוץ לקלעים, ר' אליעזר אומר: יזרוק\u0004 את הדם, \u0003ר' יהושע אומר: לא יזרוק\u0004 את הדם, \u0003ו\u0004מכל מקום \u0003מודה ר' יהושע שאם זרק\u0004 את הדם — הרי \u0003הורצה\u0004 הקרבן.","שנינו במשנה: \u0003אמר ר' חנינא סגן הכהנים\u0004 מימי לא ראיתי עור שיצא לבית השריפה. ושואלים: \u0003ולא\u0004 ראה? \u0003הרי פרים הנשרפים ושעירים הנשרפים\u0004 נשרפים יחד עם עורם!","ומשיבים: \u0003למצותן לא קאמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שדבר שכך מצוותו בוודאי עשו, אלא במקרים אחרים לא ראה.","ושואלים: \u0003הרי\u0004 אם נפסל הקרבן \u0003קודם הפשט וקודם זריקה\u0004 שורפים אותו עם עורו! ומשיבים: כאשר \u0003חלוץ\u0004 העור מן הבשר \u0003קאמרינן\u0004 \u0005[אומרים אנו]\u0006 שלא ראה.","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 מקרה שנפסל הבשר \u0003אחר הפשט וקודם זריקה, ל\u0004דברי \u0003ר' אלעזר בר' שמעון\u0004 ש\u0003אמר: אין הדם מרצה על העור בפני עצמו,\u0004 ונמצא שהעור צריך להישרף לאחר שהופשט!","ומשיבים: \u0003ר' חנינא כרבי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שהדם מרצה על העור במקרה כזה, ואינו נשרף. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו תוקמה\u0004 \u0005[תעמיד]\u0006 את דברי ר' חנינא סגן הכהנים \u0003כ\u0004שיטת \u0003ר' אלעזר בר' שמעון\u0004 שעקרונית ייתכן מצב כזה, הלוא \u0003מודה רבי שאין\u0004 עושים \u0003הפשט קודם זריקה\u0004 ואם כן בפועל לא ראה ר' חנינא עור שהופשט קודם זריקה, שנשרף.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 מקרה לאחר זריקה, שלאחר שהופשט העור ונותחה הבהמה \u0003נמצאת טריפה בבני מעיים,\u0004 ונתברר שהיתה פסולה מתחילה בשעת זריקת הדם!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שאם \u0003נמצאת טריפה בבני מעיים\u0004 הדם \u0003מרצה,\u0004 מאחר ובשעת הזריקה לא היה הדבר ידוע. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 לומר כך, \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנה\u0005],\u0006 \u0003אמר ר' עקיבא: מדבריו\u0004 של ר' חנינא סגן הכהנים \u0003למדנו, שהמפשיט את הבכור ונמצא טריפה\u0004 — \u0003שיאותו הכהנים בעורו.\u0004 ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003ו\u0004שואלים: אם באמת זו היתה כוונתו, \u0003אלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך \u0003ר' עקיבא?\u0004 הרי אלו הם דבריו של ר' חנינא סגן הכהנים עצמו! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[זה השמיע לנו],\u0006 שדין זה קיים לא רק במקדש, אלא \u0003אפילו בגבולין,\u0004 בבכור בעל מום, שנשחט מחוץ למקדש. שאם ידוע היה מתחילה שהוא טריפה — הריהו טעון קבורה יחד עם עורו. אבל אם נשחט ורק אחר כך נתברר שהיה טריפה — התירה אותו שחיטתו, וייהנו הכהנים מעורו, וכדרך שהועילה לכך זריקת הדם במקדש.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הלכה כר' עקיבא,\u0004 ומוסיפים: \u0003ואף ר' עקיבא לא אמר אלא כש\u0004בכור זה \u0003התירו מומחה,\u0004 שפסק שהוא בעל מום, ומותר לכהן לשוחטו. \u0003אבל לא התירו מומחה\u0004 — \u0003לא\u0004 הועילה לו שחיטתו.","ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 בענין זה היא \u0003כדברי חכמים\u0004 ולא כר' עקיבא, ולכן דין ה\u0003בשר\u0004 \u0003בקבורה, והעור בשריפה.\u0004","\u0003פרים הנשרפים\u0004 (פר יום הכיפורים ופר כהן משיח ופר העלם דבר של ציבור), שמצוותם להישרף לאחר שנזרק דמם והוקטרו אימוריהם על גבי המזבח, \u0003ו\u0004כן \u0003שעירים הנשרפים\u0004 (שעיר יום הכיפורים ושעיר שגגת עבודה זרה), \u0003בזמן שהן נשרפין כמצותן,\u0004 כהלכתם — הרי הם \u0003נשרפים\u0004 חוץ לירושלים, \u0003ב\u0004מקום הנקרא \u0003בית הדשן\u0004 (ויקרא ד, יב), \u0003ומטמאין\u0004 את ה\u0003בגדים\u0004 של הכהנים העוסקים בשריפתם, כפי שנאמר בתורה (ויקרא טז, כח). \u0003ו\u0004אולם \u0003אם\u0004 הקרבנות הנשרפים \u0003אינן נשרפין כמצותן,\u0004 משום שנפסלו, ודין פסולי המוקדשים בשריפה — הרי הם \u0003נשרפין בבית הבירה,\u0004 במקדש, \u0003ואינן מטמאין\u0004 את ה\u0003בגדים\u0004 של הכהנים העוסקים בשריפתם."],["ועוד בדין פרים ושעירים הנשרפים: \u0003היו סובלין\u0004 (נושאים) \u0003אותו\u0004 (אותם) אל מחוץ לירושלים כשהם תלוים \u0003במוטות.\u0004 ובדינם של אלה הנושאים את הקרבן: כאשר \u0003יצאו הראשונים חוץ לחומת העזרה, והאחרונים\u0004 עדיין \u0003לא יצאו\u0004 — \u0003הראשונים מטמאין בגדים,\u0004 כדינם של כל המתעסקים בשריפת קרבנות אלו. \u0003והאחרונים אינן מטמאין בגדים עד שיצאו.\u0004 וכאשר \u0003יצאו אלו ואלו\u0004 — כולם \u0003מטמאין בגדים. ר' שמעון אומר:\u0004 הן אלו ואלו, \u0003אינן מטמאין,\u0004 שאין נטמאים אלא השורפים קרבנות אלו. ואף אלה, אינם נטמאים \u0003עד שיוצת האור\u0004 (תאחז האש) \u0003ברובן\u0004 של הקרבנות הללו, ולא לפני כן. ואחר ש\u0003ניתך הבשר\u0004 נשרף לגמרי, ונעשה אפר — שוב \u0003אין השורף מטמא בגדים.\u0004","שנינו במשנה שפרים ושעירים הנשרפים שנפסלו, נשרפים בבית הבירה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 היא אותה \u0003\"בירה\"? אמר רבה בר בר חנה אמר ר' יוחנן: מקום יש בהר הבית, ו\"בירה\" שמו,\u0004 ושם היו שורפים את הקרבנות הללו. \u0003וריש לקיש אמר: כל הבית\u0004 (המקדש) \u0003כולו קרוי \"בירה\", ש\u0004כן \u0003נאמר\u0004 בתפילת דוד המלך: \"ולשלמה בני תן לבב שלם לשמור מצוותיך עדותיך וחוקיך ולעשות הכל ולבנות \u0003הבירה אשר הכינותי\"\u0004 (דברי הימים א כט, יט).","ובענין בית הדשן שנזכר במשנה, \u0003אמר רב נחמן אמר רבה בר אבוה: שלשה בית הדשנין הן\u0004 שנועדו לשריפת הקרבנות: אחד, הוא \u0003בית הדשן\u0004 ה\u0003גדול\u0004 ש\u0003היה בעזרה, ששם\u0004 היו \u0003שורפין\u0004 את \u0003פסולי קדשי קדשים, ו\u0004את \u0003אימורי\u0004 (חלקי הקרבן הקרבים על המזבח) של \u0003קדשים קלים\u0004 שנפסלו, \u0003ו\u0004את \u0003פרים הנשרפין ושעירים הנשרפין שאירע בהן פסול\u0004 (כגון שנטמאו) \u0003קודם\u0004 ה\u0003זריקה\u0004 של דמם על המזבח.","\u0003ו\u0004עוד \u0003בית הדשן אחר היה בהר הבית, ששם\u0004 היו \u0003שורפין פרים הנשרפים ושעירים הנשרפים שאירע בהן פסול אחר זריקה. ו\u0004עוד בית דשן היה, שנועד לפרים ושעירים הנשרפים שנעשו \u0003כמצותן,\u0004 והוא היה \u0003חוץ לשלש מחנות\u0004 שהיו בזמן המשכן במדבר (מחנה שכינה, מחנה לויה ומחנה ישראל), ובזמן בית המקדש — מחוץ לירושלים.","ובענין זה, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 בברייתא באופן שונה, \u0003שלשה בית הדשנין הן:\u0004 אחד הוא \u0003בית הדשן גדול\u0004 ש\u0003היה בעזרה, ששם שורפין פסולי קדשי קדשים, ואימורי קדשים קלים, ופרים הנשרפים ושעירים הנשרפים שאירע בהן פסול, בין\u0004 שאירע הפסול \u0003קודם זריקה בין לאחר זריקה. ובית הדשן אחר היה בהר הבית, ששם שורפין פרים הנשרפין ושעירים הנשרפין שאירע בהן פסול ביציאתן\u0004 (לאחר שיצאו מהעזרה). \u0003ו\u0004בית הדשן השלישי הוא זה שנועד לשריפת קרבנות הנעשים \u0003כמצותן,\u0004 ומקומו מ\u0003חוץ לשלש מחנות,\u0004 מחוץ לחומת העיר.","ודנים מהם הדברים הפוסלים בפרים ובשעירים הנשרפים. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: לינה\u0004 \u0003מהו שתועיל\u0004 לפסול \u0003בפרים הנשרפים ובשעירים הנשרפים,\u0004 אם לא הוציא את בשרם לבית הדשן עד שעבר הלילה? וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כי מהניא\u0004 \u0005[כאשר מועילה,\u0006 פועלת\u0005]\u0006 \u0003לינה\u0004 לפסול, הרי זה רק \u0003ב\u0004יחס ל\u0003בשר דבר\u0004 \u0005[ש\u0006הוא \u0005בן]\u0006 \u0003אכילה,\u0004 כגון בשר עולה שיש בו אכילת מזבח, או בשר קדשי קדשים שנאכל על ידי הכהנים. \u0003אבל הני\u0004 \u0005[אלה,\u0006 פרים ושעירים הנשרפים\u0005],\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני אכילה נינהו\u0004 \u0005[הם]\u0006 שהרי הם נשרפים — \u0003לא\u0004 תפסלם הלינה. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]\u0006 והכל לינה פוסלתם?","\u0003אמר רבא: הא מילתא איבעיא ליה\u0004 \u0005[דבר זה,\u0006 שאלת ר' ירמיה, \u0005נשאלה לו]\u0006 \u0003לאביי, ופשטנא ליה מהא\u0004 \u0005[ופתרתי לו\u0006 את שאלתו \u0005מזו\u0006 ששנינו\u0005]\u0006 בענין פרים הנשרפים, האם מחשבת חוץ לזמנו עושה בהם דין פיגול: \u0003ושוין\u0004 גם האומרים שיש דין פיגול בפרים הנשרפים, מודים \u0003ש\u0004אין הדברים אמורים אלא במחשב להקטיר את אימוריהם למחר. אבל \u0003אם חישב באכילת פרים ובשריפתן\u0004 לאכול את בשרם למחר או לשורפם למחר — \u0003שלא עשה\u0004 בכך \u0003כלום,\u0004 שכן פרים אלו אינם קרבים ואינם נאכלים, ואין מחשבת פיגול אלא במחשב לאכול דבר שדרכו לאכול, או להקטיר דבר שדרכו להקטיר. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן: \u0003מ\u0004כיון ש\u0003מחשבה\u0004 לשרוף למחר, \u0003לא פסלה\u0004 \u0005[פוסלת]\u0006 בפרים הנשרפים, \u0003לינה\u0004 עד למחר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פסלה\u0004 \u0005[פוסלת]?\u0006","ודוחים את הראיה: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 דווקא \u0003מחשבה הוא\u0004 ש\u0003לא פסלה\u0004 \u0005[פוסלת],\u0006 \u0003אבל לינה\u0004 עצמה \u0003פסלה\u0004 \u0005[פוסלת]!\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון ממה ששנינו במסכת מעילה: \u0003פרים הנשרפים ושעירים הנשרפין\u0004 — \u0003מועלין בהן מ\u0004שעה \u0003שהוקדשו,\u0004 ומשעה ש\u0003נשחטו\u0004 — \u0003הוכשרו ליפסל ב\u0004נגיעה של \u0003טבול יום וב\u0004נגיעה של \u0003מחוסר כיפורים ובלינה.\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שנפסלים ב\u0003לינת בשר,\u0004 שלא הוציאהו לישרף עד למחרת?","ודוחים: \u0003לא,\u0004 הכוונה היא לפסול של \u0003לינת אימורין\u0004 החלקים הקרבים על המזבח.","ומקשים על כך: \u0003והא מדקתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה בסוף\u0006 אותה משנה\u0005]:\u0006 \u0003כולן מועלין בהן\u0004 בהיותם \u0003בבית הדשן\u0004 שהוא מקום שריפתם \u0003עד שיותך הבשר\u0004 כלומר, עד שיישרפו לגמרי, יש ללמוד כי \u0003מדסיפא\u0004 \u0005[מ\u0006כיון \u0005שבסוף]\u0006 מדובר ב\u0003בשר, רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 מדובר ב\u0003בשר,\u0004 ולא באימורים! ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים הדברים]?\u0006 \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר ב\u0003בשר, רישא\u0004 \u0005[בראש]\u0006 מדובר ב\u0003אימורין.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לבעיה זו ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי:\u0004 בית הדשן שבהר הבית, שם היו שורפים פרים הנשרפים ושעירים הנשרפים \u0003שאירע בהן פסול ביציאתן.\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר בפסול \u0003לינה?\u0004 ודוחים: \u0003לא,\u0004 מדובר כאן ב\u0003פסול טומאה\u0004 שנטמא הבשר, או \u0003פסול יציאה\u0004 שיצאו מחוץ לעזרה קודם זמנם, לפני שנזרק הדם. ונשארה איפוא הבעיה ללא פתרון.","ועוד בענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: יציאה\u0004 אל מחוץ לעזרה קודם הזמן, \u0003מהו שתועיל\u0004 (שתפסול) \u0003בפרים הנשרפים ושעירים הנשרפים?\u0004","ושואלים: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה נשאלה לו]?\u0006 מהי הבעיה, והרי מצוותם להישרף חוץ לעזרה! \u0003אמר ר' ירמיה בר אבא:\u0004 שאלתו זו של ר' אלעזר היא \u0003אליבא דמאן דאמר\u0004 \u0005[לפי\u0006 שיטת \u0005מי שאומר]\u0006 שבשר קדשים קלים שיצא אל מחוץ לעזרה קודם זריקת הדם נפסל בכך. שאף שסופו לצאת ולהיאכל בכל ירושלים, מכל מקום \u0003עדיין לא הגיע זמנו לצאת.\u0004","ואלו צדדי הבעיה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא לגבי \u0003בשר\u0004 קדשים קלים, משום ש\u0003אין סופו לצאת חובה,\u0004 שהרי יכול הוא לאכול קדשים קלים גם בעזרה, ואין חובה להוציאם משם. \u0003אבל הני\u0004 \u0005[אלה,\u0006 פרים ושעירים הנשרפים\u0005],\u0006 ש\u0003סופן לצאת חובה\u0004 — \u0003לא,\u0004 ואין היציאה קודם זמנה פוסלתם. \u0003או דלמא הכא נמי\u0004 \u0005[שמא אלה גם כן]\u0006 נפסלים, משום שיצאו כש\u0003לא הגיע זמנו לצאת?\u0004","ומציעים פתרון, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי:\u0004 בבית הדשן שבהר הבית היו שורפים פר או שעיר \u0003שאירע בו פסול ביציאתו.\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאירע בו \u0003פסול יציאה,\u0004 שיצא קודם זריקת הדם? ומכאן שיציאה פוסלתם! ודוחים: \u0003לא,\u0004 אפשר לומר שמדובר כאן ב\u0003פסול טומאה ו\u0004ב\u0003פסול לינה.\u0004 ונשארה אף בעיה זו בלא פתרון.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: פרים הנשרפים ושעירים הנשרפים שיצא רובו\u0004 של בעל החיים אל מחוץ לעזרה \u0003במיעוט אבר\u0004 כלומר, שאיבר אחד של הקרבן יצא רק מיעוטו, ואם נצרף חלק זה לשאר האיברים שיצאו, יימצא לפנינו רוב הבהמה שיצא, \u0003מהו\u0004 הדין? האם נחשב בעל החיים כאילו יצא רובו? וצדדי השאלה, האם \u0003הך מיעוטא\u0004 \u0005[מיעוט זה]\u0006 של ה\u0003אבר, בתר רובא שדינן ליה\u0004 \u0005[אחר הרוב\u0006 של האיבר \u0005אנו משליכים\u0006 משיבים \u0005אותו],\u0006 \u0003והא\u0004 \u0005[ו\u0006אם כן \u0005הרי]\u0006 \u0003לא נפקא ליה\u0004 \u0005[יצא לו]\u0006 האיבר. \u0003או דלמא בתר רובא\u0004 \u0005[שמא אחר רוב]\u0006 ה\u0003בהמה שדינן\u0004 \u0005[אנו משליכים]\u0006 את חלק האיבר שכבר יצא, ונמצא שרוב הקרבן יצא?","ואומרים על כך: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא, \u0003דלא שבקינן רובא דבהמה\u0004 \u0005[שאין אנו מניחים\u0006 את \u0005רוב הבהמה]\u0006 \u0003ואזלינן בתר רובא\u0004 \u0005[והולכים אנו אחר רוב]\u0006 ה\u0003אברים! אלא\u0004 כך היתה שאלתו של ר' אלעזר: אם \u0003יצא חציו\u0004 של הקרבן \u0003ב\u0004אופן כזה ש\u0003רוב אבר\u0004 מסויים יצא, ומיעוטו נותר בפנים. וצדדי השאלה, האם \u0003האי מיעוטא\u0004 \u0005[אותו מיעוט]\u0006 של ה\u0003אבר\u0004 שעדיין לא יצא,"],["\u0003בתר\u0004 \u0005[אחר]\u0006 \u0003רוב אבר\u0004 שכבר יצא אל מחוץ לעזרה \u0003שדינן ליה\u0004 \u0005[מטילים אנו אותו], ו\u0006אם כן \u0003הא נפק ליה\u0004 \u0005[הרי יצא לו]\u0006 האיבר, ונמצא רוב הבהמה בחוץ, ונטמאו הנושאים אותה. \u0003או דלמא בתר\u0004 \u0005[שמא אחר]\u0006 חצי ה\u0003בהמה\u0004 שעדיין נמצא בעזרה ולא יצאה \u0003שדינן ליה\u0004 \u0005[מטילים אנו אותו\u0006 מקצת איבר\u0005],\u0006 שהרי שם הוא נמצא, ואם כן לא יצא רוב הקרבן עדיין? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003רבה בר רב הונא מתני לה\u0004 \u0005[היה שונה אותה\u0006 בעיה\u0005]\u0006 \u0003ב\u0004יחס ל\u0003גברי\u0004 \u0005[אנשים],\u0006 \u0003במתעסקין בו\u0004 בהוצאתו של פר או שעיר הנשרפים \u0003חמשה בני אדם,\u0004 \u0003ונפקו תלתא ופשו להו תרי\u0004 \u0005[ויצאו שלושה\u0006 מהעזרה \u0005ונשארו להם שנים],\u0006 והבהמה חציה בפנים וחציה בחוץ, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי הבעיה, האם \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003רוב\u0004 ה\u0003מתעסקין אזלינן\u0004 \u0005[הולכים אנו],\u0006 ולכן במקרה זה הרוב יצא כבר, \u0003או\u0004 שמא \u0003בתר\u0004 \u0005[אחר]\u0006 רוב ה\u0003בהמה אזלינן\u0004 \u0005[הולכים אנו]\u0006 והרי לא יצא רובה? גם שאלה זו נשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה ללא פתרון.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: פרים ושעירים הנשרפים שיצאו\u0004 מחוץ לעזרה \u0003וחזרו, מהו\u0004 הדין? האם הם מטמאים את נושאיהם, בפנים? וצדדי השאלה, \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דנפקי להו איטמו להו\u0004 \u0005[כאן שיצאו להם\u0006 הרי כבר \u0005נטמאו להם],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דהדור הדור\u0004 \u0005[שחזרו\u0006 \u0005חזרו]\u0006 ושוב אינם מטמאים?","\u0003אמר ר' אבא בר ממל: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו: \u0003היו סובלין אותן במוטות. הראשונים יצאו חוץ לחומת העזרה, והאחרונים לא יצאו\u0004 — \u0003הראשונים שיצאו חוץ לחומת העזרה מטמאין בגדים, והאחרונים אין מטמאין בגדים עד שיצאו,\u0004 למרות שהפרים כבר בחוץ. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003כיון דנפקי להו איטמו\u0004 \u0005[שיצאו להם נטמאו],\u0006 ומעתה הם מטמאים את הנוגעים בהם בפנים, אם כן, גם במשנה, \u0003הנך דאיכא גואי ליטמא\u0004 \u0005[\u0006את \u0005אלה שנמצאים בפנים\u0006 ועדיין לא יצאו, גם כן \u0005שייטמאו]!\u0006 אלא מכאן שהנושא אותם כשהם בפנים אינו נטמא.","\u0003אמר רבינא: ותסברא\u0004 \u0005[וסבור אתה],\u0006 שיש מכאן ראיה? \u0003הא\u0004 \u0005[הרי]\u0006 טעם הדבר שהאחרונים אינם מטמאים בגדים הוא משום \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיתקיים הכתוב \"יכבס בגדיו וכו' \u0003ואחר יבא אל המחנה\"\u0004 (ויקרא טז, כח), וליכא \u0005[ואין כאן],\u0006 שהרי לא יצאו מן המחנה!","ושואלים: \u0003אלא\u0004 אם רק מי שכבר יצא נטמא, \u0003ר' אלעזר היכי בעי לה\u0004 \u0005[כיצד\u0006 באיזה אופן \u0005שאל אותה]?\u0006 ומשיבים: \u0003כגון דנקיטי לה בבקולסי\u0004 \u0005[שאוחזים במקלות]\u0006 כלומר, שאנשים שלא הוציאום מתחילה עומדים בחוץ ובמקלות שבידיהם מוציאים אותם שוב החוצה, ומעתה יש לשאול: האם הפרים והשעירים שיצאו וחזרו מטמאים את אלו שבחוץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פרים\u0004 הנשרפים \u0003ופרה\u0004 אדומה \u0003ושעיר המשתלח\u0004 — \u0003המשלח\u0004 אותם, וכן \u0003השורפן והמוציאן, מטמא בגדים. והן עצמן\u0004 משיצאו \u0003אין מטמאין בגדים\u0004 שנגעו בהם, \u0003אבל מטמאין\u0004 רק \u0003אוכלין ומשקין\u0004 שנגעו בהם, אלו \u0003דברי ר' מאיר. וחכמים אומרים: פרה\u0004 אדומה \u0003ופרים\u0004 הנשרפים \u0003מטמאין אוכלין ומשקין,\u0004 אבל \u0003שעיר המשתלח אינו מטמא\u0004 כלל, מפני \u0003שהוא חי\u0004 עדיין, \u0003והחי אינו מטמא אוכלין ומשקין.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 יש לפרש את דבריו \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר בדיני טומאה: \u0003\"על כל זרע זרוע\"\u0004 (ויקרא יא, לז), ומשם למדנו כי זרעים אינם מקבלים טומאה עד שיותן עליהם מים ויפול עליהם שרץ.","ומשם יש ללמוד: \u0003מה זרעים\u0004 הם דבר \u0003שאין סופן ליטמא טומאה חמורה\u0004 שאין מאכלים נטמאים לעולם בדרגת אב הטומאה, לטמא אדם או כלים, \u0003וצריכין הכשר\u0004 שיבואו עליהם מים ויגע בהם שרץ כדי להיטמא ולטמא אוכלים אחרים, \u0003אף כל\u0004 דברים \u0003שאין סופן ליטמא טומאה חמורה צריכין הכשר\u0004 כדי לטמא אוכלים. \u0003יצתה\u0004 (יצאה) \u0003נבלת עוף טהור,\u0004 \u0003שסופה ליטמא טומאה חמורה,\u0004 שהיא מטמאת אדם כשהיא בבית הבליעה שלו, \u0003ו\u0004לכן \u0003אין\u0004 היא \u0003צריכה הכשר\u0004 כדי לטמא אוכלים במגעה. וכיוצא בזה דינם של פרים ופרה ושעיר, הואיל והם מטמאים את העוסקים בהם, הריהם מטמאים אוכלים ומשקים בלי הכשר.","\u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 החולקים על ר' מאיר, ומחלקים בין פרה ופרים לבין שעיר, \u0003אי אית להו\u0004 \u0005[אם יש להם,\u0006 מקבלים הם\u0005]\u0006 את הדברים \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, אפילו שעיר המשתלח\u0004 יהיה טמא! \u0003אי לית ליה\u0004 \u0005[אם אין להם]\u0006 שיטה זו, \u0003אפילו פרה ופרים מנלן\u0004 \u0005[מנין לנו]\u0006 שמטמאים כלל?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר, אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]:\u0006 לדעת חכמים, שעיר ופרים הנשרפים \u0003צריכין הכשר טומאה ממקום אחר\u0004 כדי לטמא אוכלים, ולא כשיטת תנא דבי ר' ישמעאל. אבל שעיר, משום שהוא חי אינו מקבל טומאה מדבר אחר, ואינו בכלל טומאת אוכלים.","בעקבות הברייתא שהובאה לעיל, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: פרים ושעירים הנשרפים מהו שיטמאו אוכלין ומשקין בפנים,\u0004 לפני שיצאו מן העזרה, \u0003כ\u0004פי שהם מטמאים \u0003בחוץ\u0004 לאחר שיצאו? והשאלה היא: האם \u0003מחוסר יציאה כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 וכיון שעדיין אין הם מטמאים טומאה חמורה — אין הם מטמאים טומאת אוכלים בלא הכשר. \u0003או לא\u0004 כלומר, אין זה כחסרון מעשה, והם מטמאים אוכלים, מאחר וסופם לטמא טומאה חמורה כשיצאו?","\u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר ופתרה]:\u0006 \u0003מחוסר יציאה כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 ואינם מטמאים טומאת אוכלים בלא הכשר.","ועוד בעקבות אותה ברייתא \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבא בר שמואל מר' חייא בר אבא:\u0004 אין אוכל מטמא בטומאת אוכלים אלא אם יש בו שיעור כביצה. אבל \u0003נבלת עוף טהור, לר' מאיר,\u0004 שאמר כי היא מטמאה בטומאת אוכלים בלא הכשר, מאחר והיא ראויה לטמא טומאה חמורה באותה שעה בבית הבליעה \u0003מהו שיטמא\u0004 טומאת אוכלים כשיש בו \u0003כזית\u0004 בלבד, כשיעור בו הוא מטמא טומאה חמורה בבית הבליעה?","ואומרים: \u0003דמחתא לארעא לא תיבעי לך\u0004 \u0005[שמונחת\u0006 נבלת העוף \u0005בקרקע לא תישאל לך השאלה],\u0006 שוודאי אינה מטמאה אוכלים בכזית אלא בכביצה, שהרי לא הגיעה למצב בו היא מטמאת טומאה חמורה. וכן מצד אחר, \u0003דנקיט בפומיה לא תיבעי לך\u0004 \u0005[שמחזיק\u0006 אותה \u0005בפיו לא תישאל לך],\u0006 שוודאי היא מטמאה אוכלים שבפיו כשיש בה כזית, שהרי באותה שעה יכול לבולעה, ואז היא מטמאת טומאה חמורה בשיעור זה, כדין נבלת עוף טהור. \u0003כי תיבעי לך דנקיט ליה בידיה\u0004 \u0005[כאשר תישאל לך\u0006 השאלה הרי זה \u0005כשמחזיק אותה בידו],\u0006 וצדדי השאלה: האם \u0003מחוסר קריבה\u0004 הקרבה לפיו \u0003כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 ועדיין לא הגיע לכלל טומאת בית הבליעה, שהיא בכזית, \u0003או לא?\u0004","ומעירים: \u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל אותה חזר ופתרה]:\u0006"],["\u0003מחוסר קריבה לאו\u0004 \u0005[אינו]\u0006 \u0003כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 והרי זה כאילו כבר היה בפיו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' אבא, ממה ששנינו: \u0003שלשה עשר דברים נאמרו בנבלת עוף טהור, וזה אחד מהן: צריכה מחשבה\u0004 לאוכלה, כדי שתקבל טומאת אוכלים, \u0003ואין צריכה הכשר\u0004 מים ולא מגע שרץ כדי לטמא, \u0003ומטמא טומאת אוכלין בכביצה. מאי לאו\u0004 \u0005[האם\u0006 משנה זו \u0005לא]\u0006 שיטת \u0003ר' מאיר היא?\u0004 ונמצא שלדעתו רק בכביצה היא מטמאת טומאת אוכלים, ולא בכזית!","ודוחים: \u0003לא,\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004","ושואלים: \u0003והא קתני רישא\u0004 \u0005[והרי שנה בתחילה]:\u0006 \u0003צריכה מחשבה ואין צריכה הכשר. ומאן שמעת ליה האי סברא\u0004 \u0005[ומי שמעת אותו\u0006 אומר \u0005סברה זו],\u0006 שנבלת העוף אינה צריכה הכשר? \u0003ר' מאיר,\u0004 כמבואר בברייתא שבעמוד הקודם. \u0003ומדרישא\u0004 \u0005[ומכיון שראשה]\u0006 שיטת \u0003ר' מאיר, סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 כשיטת \u0003ר' מאיר!\u0004","ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים הדברים]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כמו שהיא וזו כמו שהיא].\u0006","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה בסוף,\u0006 בהמשך אותה משנה\u0005]:\u0006 \u0003שחיטתה ומליקתה\u0004 של עוף לקרבן \u0003מטהרת טריפתה מטומאתה. מאן שמעת ליה האי סברא\u0004 \u0005[\u0006ו\u0005מי שמעת אותו\u0006 אומר \u0005סברה זו\u0006 שמליקה מטהרת את הטריפה\u0005]?\u0006 \u0003ר' מאיר,\u0004 בפרק השביעי של מסכת זו (לעיל זבחים סז,א). וכי משנה זו, \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 שיטת \u0003ר' מאיר\u0004 היא, \u0003ומציעתא רבנן\u0004 \u0005[ואמצעיתה\u0006 כדעת \u0005חכמים]?\u0006","ומשיבים: \u0003אין\u0004 \u0005[\u0006אכן \u0005כן],\u0006 \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כ\u0003ר' מאיר ומציעתא רבנן\u0004 \u0005[ואמצעה\u0006 כ\u0005חכמים].\u0006","ועוד בענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא לר' זירא: לא תיתיב אכרעך\u0004 \u0005[תשב על רגליך]\u0006 \u0003עד דאמרת\u0004 \u0005[שתאמר]\u0006 \u0003לי\u0004 \u0003הא מילתא\u0004 \u0005[דבר זה]:\u0006 \u0003נבלת עוף טהור,\u0004 \u0003ל\u0004דעת \u0003ר' מאיר,\u0004 הסבור שהיא מטמאה אוכלים במגעה בלא הכשר, משום שהיא ראויה לטמא בטומאת בית הבליעה שהיא אב הטומאה, האם כשנגעה באוכלים \u0003מונין לה ראשון ושני\u0004 כדין אב טומאה, שהנוגע בו נעשה ראשון לטומאה, וחוזר ומטמא אוכלים אחרים, \u0003או אין מונין\u0004 לה \u0003ראשון ושני,\u0004 אלא דינה ככל אוכל טמא, שהוא ראשון לטומאה, ועושה שני לטומאה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003כל היכא\u0004 \u0005[מקום]\u0006 שדבר \u0003מטמא אדם במגע\u0004 — \u0003מונין בו ראשון ושני, כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אין מטמא אדם\u0004 במגע — \u0003אין מונין בו ראשון ושני,\u0004 ונבלת העוף אינה מטמאה אדם במגע, אלא בבליעה בלבד.","ובדומה לכך \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מר' אמי בר חייא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ששאל \u0003מר' אבין בר כהנא: הא דתנן\u0004 \u0005[זה ששנינו]:\u0006 \u0003חיבורי אוכלין על ידי משקין\u0004 שאם נטמא אחד מן האוכלים גם השני נטמא — הרי זה נחשב \u0003חיבור\u0004 לצרף את האוכלים לשיעור טומאה רק \u0003ל\u0004ענין \u0003טומאה קלה\u0004 כלומר, לענין טומאת אוכלים, \u0003ואין\u0004 זה נחשב ל\u0003חיבור ל\u0004ענין \u0003טומאה חמורה,\u0004 שאם היתה זו נבילה, אין המשקה מצרף אותם לשיעור טומאה.","האם כשנתחברו שני חלקי נבילה במשקים \u0003מונין בו ראשון ושני,\u0004 שאוכל הנוגע בו חוזר ומטמא אוכלים, \u0003או אין מונין בו ראשון ושני?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכלל הוא, \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003מטמא אדם\u0004 — \u0003מונין בו ראשון ושני,\u0004 דבר ש\u0003אין מטמא אדם\u0004 — \u0003אין מונין בו ראשון ושני,\u0004 ואדם אינו נטמא בטומאת אוכלים, וממילא אין מונים בחיבור זה ראשון ושני.","שנינו במשנה בענין המוציאים את הפרים והשעירים הנשרפים: \u0003יצאו אלו ואלו\u0004 מחוץ לחומת העזרה — כולם מטמאים בגדים שעליהם. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שכבר כשיצאו חוץ לעזרה הריהם מטמאים בגדים, עוד קודם שהחלו בשריפה מחוץ לירושלים? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הנאמר בענין פר ושעיר הנשרפים של יום הכיפורים: \"יוציא אל מחוץ למחנה ושרפו באש\" וכו' (ויקרא טז, כז): \u0003להלן הוא אומר\u0004 שצריך להוציאם ולשורפם \u0003חוץ לשלש מחנות, כאן\u0004 — חוץ \u0003למחנה אחת, לומר לך: כיון שיצא\u0004 הנושא \u0003חוץ למחנה אחת,\u0004 כלומר, מחנה שכינה, ובירושלים — חוץ לעזרה, מיד \u0003מטמא בגדים,\u0004 וכפי שנאמר בהמשך: \"יכבס בגדיו ... במים\" (ויקרא טז, כח).","ושואלים: \u0003והיא גופה\u0004 \u0005[עצמה]\u0006 שצריך לשורפם חוץ לשלש מחנות \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 מה שנאמר בפר כהן משיח \u0003\"והוציא את כל הפר אל מחוץ למחנה\u0004 וכו' ושרף אותו\" (ויקרא ד, יב), כוונתו \u0003חוץ לשלש מחנות:\u0004 מחנה שכינה, מחנה לויה ומחנה ישראל. \u0003אתה אומר: חוץ לשלש מחנות, או אינו אלא\u0004 חוץ ל\u0003מחנה אחת,\u0004 מחנה שכינה?","\u0003כשהוא אומר\u0004 לאחר מכן \u0003בפר העדה: \"מחוץ למחנה\"\u0004 (ויקרא ד, כא) \u0003שאין צריך לומר\u0004 דבר זה, \u0003שהרי כבר נאמר\u0004 באותו פסוק: \"ושרף אותו \u0003כאשר שרף את הפר הראשון\"\u0004 — הרי זה בא \u0003ליתן לו מחנה שניה,\u0004 כלומר, שיש להוציאו חוץ למחנה נוסף, מחנה לויה.","\u0003כשהוא אומר\u0004 לאחר מכן \u0003\"מחוץ למחנה\" ב\u0004ענין ה\u0003דשן\u0004 שמרים הכהן מן המזבח בכל בוקר (ויקרא ו, ד) — \u0003שאין צריך לומר\u0004 דבר זה, \u0003שהרי כבר נאמר\u0004 בפר כהן משיח: \u0003\"על שפך הדשן ישרף\"\u0004 (ויקרא ד, יב), ומכאן אנו כבר יודעים שמקום הדשן הוא מחוץ למחנה. אלא הרי זה בא \u0003ליתן לו מחנה שלישית,\u0004 ללמד שבית הדשן הוא חוץ לשלושה מחנות.","ושואלים: \u0003ור' שמעון,\u0004 הסבור במשנתנו שאין המתעסקים בפרים ובשעירים הנשרפים מטמאים את הבגדים עד שיוצת האור ברובם, חוץ לשלש מחנות, \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"מחוץ למחנה\"\u0004 האמור בענין פר ושעיר של יום הכיפורים, \u0003מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005לו לכמו ששנויה\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נאמר כאן\u0004 בפר ושעיר של יום הכיפורים: \u0003\"חוץ למחנה\"\u0004 (ויקרא טז, כז) \u0003ונאמר להלן\u0004 בפרה אדומה: \"והוציא אותה אל \u0003חוץ למחנה\"\u0004 (במדבר יט, ג), \u0003מה להלן\u0004 בפר ושעיר, \"חוץ למחנה\" כוונתו \u0003חוץ לשלש מחנות,\u0004 כלומר, חוץ לירושלים — \u0003אף כאן\u0004 בפרה אדומה, כוונתו \u0003חוץ לשלש מחנות. ומה להלן\u0004 בפרה, מוציא אותה \u0003למזרחה של ירושלים,\u0004 שהרי צריך להזות מדם הפרה כנגד פתח ההיכל, שהוא במזרח —"],["\u0003אף כאן\u0004 בפר ושעיר הנשרפים \u0003למזרחה של ירושלים.\u0004 ושואלים: \u0003אלא ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאינם למדים גזירה שווה זו לפרה אדומה, \u0003היכא שריף להו\u0004 \u0005[היכן,\u0006 באיזה מקום חוץ לירושלים \u0005שורפים אותם]?\u0006 ומשיבים: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003היכן נשרפין\u0004 פרים ושעירים הנשרפים? \u0003לצפון ירושלים חוץ לשלש מחנות. ר' יוסי הגלילי אומר: אבית\u0004 (על בית) \u0003הדשן נשרפין\u0004 במקום בו שופכים את דשן המזבח חוץ לירושלים.","","\u0003אמר רבא: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 על \u0003ר' יוסי הגלילי? ר' אליעזר בן יעקב היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין פרים הנשרפים: \u0003\"על שפך הדשן ישרף\"\u0004 (ויקרא ד, יב) — \u0003שיהא שם דשן,\u0004 לומר \u0003שיקדים לשם דשן\u0004 לפני ששורף שם את הפר, שיהא זה בית הדשן. \u0003ר' אליעזר בן יעקב אומר: שיהא מקומו משופך\u0004 (משופע) שיהא שם מדרון שהדשן נשפך בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דילמא\u0004 \u0005[שמא]\u0006 רק \u0003ב\u0004דין אם צריך שיהא \u0003מקומו משופך פליגי\u0004 \u0005[חלוקים]\u0006 ר' יוסי הגלילי ור' אליעזר בן יעקב, אבל גם ר' אליעזר בן יעקב מודה שצריך שיהיה שם דשן קודם!","וכענין ששנינו במשנתנו, שלדעת ר' שמעון אין העוסקים בנשרפים מטמאים בגדים עד שיוצת האור ברובו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השורף מטמא בגדים, ולא המצית את האור מטמא בגדים, ולא המסדר את המערכה\u0004 של העצים, כדי לשרוף עליה את הבהמות הללו, \u0003מטמא בגדים. ואיזהו השורף? המסייע בשעת שריפה\u0004 עצמה.","\u0003יכול אף משנעשו אפר מטמא בגדים? תלמוד לומר\u0004 לגבי פר ושעיר של יום הכיפורים: \"והשורף \u0003אתם\u0004 יכבס בגדיו\" (ויקרא טז, כח), להדגיש: \u0003אותם\u0004 כשהם בשלימותם \u0003מטמאין בגדים, ומשנעשין אפר אין\u0004 הם \u0003מטמאין בגדים. ר' שמעון אומר\u0004 שכך יש לדייק: \u0003אותם מטמאין בגדים,\u0004 אבל אם \u0003ניתך הבשר\u0004 שוב \u0003אין מטמאין בגדים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם]?\u0006 הרי לכאורה אומרים הם אותו דבר! \u0003אמר רבא: איכא בינייהו דשוייה חרוכא\u0004 \u0005[יש ביניהם\u0006 הבדל במקרה \u0005שעשה אותו\u0006 את הבשר \u0005חרוך],\u0006 ועדיין לא נעשה אפר, שלדעת התנא הראשון עדיין מטמאים, ולדעת ר' שמעון שוב אינם מטמאים.","","\u0003השוחט\u0004 קדשים חוץ לעזרה, \u0003והמעלה\u0004 קדשים לקרבן \u0003בחוץ\u0004 (לעזרה) — \u0003חייב על השחיטה\u0004 כרת אם עשה זאת במזיד, וקרבן חטאת אם עשה זאת בשוגג, \u0003ו\u0004כן \u0003חייב על\u0004 ה\u0003העלאה,\u0004 שכן כל אחת היא עבירה לעצמה. \u0003ר' יוסי הגלילי אומר:\u0004 אם \u0003שחט\u0004 את הקרבן \u0003בפנים\u0004 המקדש, כהלכתו, וחזר \u0003והעלה\u0004 אותו \u0003בחוץ\u0004 — הריהו חייב על ההעלאה. ואולם אם \u0003שחט בחוץ והעלה בחוץ\u0004 — הריהו \u0003פטור\u0004 על ההעלאה, \u0003ש\u0004הרי \u0003לא העלה\u0004 בחוץ \u0003אלא דבר פסול,\u0004 שכן כבר נפסל הקרבן בשחיטתו בחוץ, ואין חייבים אלא על העלאה של דבר הראוי להתקבל בפנים. \u0003אמרו לו\u0004 חכמים בתשובה לכך: לשיטתך, \u0003אף השוחט בפנים ומעלה בחוץ\u0004 יהיה פטור על ההעלאה, \u0003כיון\u0004 שבשעה \u0003שהוציאו\u0004 אל מחוץ לעזרה \u0003פסלו\u0004 בכך, והריהו איפוא מעלה קרבן פסול. אלא כשם שעל הנשחט בפנים חייב — גם על הנשחט בחוץ חייב.","","ועוד נחלקו חכמים אלו בבעיה דומה במקצת: אדם \u0003הטמא שאכל\u0004 בשר קודש, \u0003בין\u0004 שאכל \u0003קדש טמא, בין קדש טהור\u0004 — \u0003חייב\u0004 כרת אם עשה זאת במזיד, וקרבן עולה ויורד אם עשה זאת בשוגג. ואילו \u0003ר' יוסי הגלילי אומר:\u0004 אדם \u0003טמא שאכל\u0004 בשר קודש \u0003טהור —\u0004 \u0003חייב.\u0004 \u0003ו\u0004אולם אדם \u0003טמא שאכל\u0004 בשר קדש \u0003טמא\u0004 — \u0003פטור,\u0004 כיון \u0003שלא אכל אלא דבר טמא. אמרו לו\u0004 חכמים החולקים עליו: לשיטתך, \u0003אף טמא שאכל את הטהור\u0004 יהיה פטור, שהרי \u0003כיון שנגע בו\u0004 בבשר הקודש \u0003טמאוהו\u0004 בכך, ונמצא שאוכל דבר טמא. ואדם \u0003טהור שאכל\u0004 בשר קודש \u0003טמא\u0004 — הרי זה \u0003פטור\u0004 מכרת ומקרבן עולה ויורד, \u0003ש\u0004כן \u0003אינו חייב\u0004 כרת \u0003אלא על\u0004 אכילת קדשים ב\u0003טומאת הגוף,\u0004 ועל אכילה של קדשים טמאים עובר בלאו שאין בו כרת.","","שנינו במשנתנו שחייב אדם בנפרד, גם על שחיטת קדשים בחוץ וגם על העלאתם בחוץ, ומבררים מה המקור להלכות אלו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003העלה\u0004 קדשים בחוץ שחייב על כך, שכן \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003עונש\u0004 בדבר אם עשה כן, \u0003וכתיב\u0004 \u0005[וכתובה]\u0006 \u0003אזהרה\u0004 מצות לא תעשה, \u0003עונש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"איש איש מבית ישראל וכו' אשר יעלה עולה או זבח \u0003ואל פתח אהל מועד לא (הביאו)\u0004 [יביאנו] לעשות אותו לה', ונכרת האיש ההוא מעמיו\" (ויקרא יז, ח—ט). \u0003אזהרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"השמר לך פן תעלה עלתיך\u0004 בכל מקום אשר תראה\" (דברים יב, יג), \u0003וכי הא\u0004 \u0005[וכמו\u0006 כלל זה] ש\u0003אמר ר' אבין אמר ר' אלעזר: כל מקום שנאמר\u0004 בתורה הלשון \u0003\"השמר\"\u0004 או \u0003\"פן\"\u0004 או \u0003\"אל\"\u0004 — \u0003אינו אלא\u0004 לשון \u0003לא תעשה.\u0004","\u0003אלא שחיטה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003עונש\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"איש איש מבית ישראל אשר ישחט שור וכו' \u0003ואל פתח אהל מועד לא הביאו...\u0004 ונכרת האיש ההוא מקרב עמו\". \u0003אלא אזהרה מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בהמשך אותה פרשה: \u0003\"ולא יזבחו עוד\u0004 את זבחיהם לשעירים אשר הם זונים אחריהם\" (ויקרא יז, ז).","ושואלים על כך: והרי \u0003האי מיבעי ליה\u0004 \u0005[\u0006מקרא זה נחוץ לו] \u0003ל\u0004הלכה זו שאמר \u0003ר' אלעזר,\u0004 שכך \u0003אמר: מנין לזובח בהמה ל\u0004עבודה זרה הקרויה \u0003מרקוליס שהוא חייב\u0004 על כך, אף שאין דרך עבודתה של עבודה זרה זו בזביחה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא יזבחו עוד את זבחיהם\", אם\u0004 כתוב זה \u0003אינו ענין ל\u0004עבודה זרה שעושה אותה \u0003כדרכה\u0004 כלומר, שדרך פולחנה הרגיל הוא בזביחה, \u0003דכתיב\u0004 \u0005[ש\u0006הרי כבר \u0005נאמר]:\u0006 \"השמר לך... ופן תדרוש לאלהיהם לאמר \u0003איכה יעבדו\u0004 הגוים האלה את אלהיהם ואעשה כן גם אני\" (דברים יב, ל), ומכאן כבר למדנו דין זה, \u0003תנהו ענין לשלא כדרכה,\u0004 כלומר, לשוחט לעבודה זרה שאין דרך עבודתה בזביחה, אלא בצורה אחרת!","\u0003אמר רבה: קרי ביה\u0004 \u0005[קרא בו\u0006 במקרא זה\u0005]\u0006 \u0003\"ולא יזבחו\", וקרי ביה\u0004 \u0005[וקרא בו]\u0006 \u0003\"ולא עוד\",\u0004 הרי כאן שני לימודים, האחד לענין איסור שחיטת קדשים בחוץ, והאחד לענין איסור זביחה לעבודה זרה.","וחוזרים ושואלים: \u0003אכתי מיבעי ליה לכדתניא\u0004 \u0005[עדיין נצרך לו\u0006 מקרא זה \u0005לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003עד כאן\u0004 בחלק הראשון של פרשת שחוטי חוץ, שנאמר בו: \"איש איש מבית ישראל אשר ישחט שור וכו' ואל פתח אהל מועד לא הביאו להקריב קרבן לה'\" (ויקרא יז, ג—ד), \u0003הוא מדבר בקדשים שהקדישן בשעת איסור הבמות\u0004 לאחר שהוקם המשכן, \u0003והקריבן בשעת\u0004 \u0003איסור הבמות,\u0004"],["\u0003שהרי עונשן אמור\u0004 במקרא זה: \u0003\"ואל פתח אהל מועד\u0004 לא הביאו להקריב קרבן לה' לפני משכן ה'... ונכרת האיש ההוא מקרב עמו\" (ויקרא יז, ד), ו\u0003אזהרה\u0004 עליהם אמורה, ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"השמר לך פן תעלה עלתיך\u0004 בכל מקום אשר תראה\" (דברים יב, יג).","\u0003מכאן ואילך\u0004 הרי הכתוב עוסק \u0003בזבחים שהקדישן בשעת היתר הבמות,\u0004 קודם שהוקם המשכן, \u0003והקריבן בשעת איסור הבמות,\u0004","\u0003שנאמר: \"למען אשר יביאו בני ישראל את זבחיהם אשר הם זבחים\u0004 על פני השדה והביאום לה' אל פתח אהל מועד... ולא יזבחו עוד את זבחיהם לשעירים אשר הם זונים אחריהם חוקת עולם תהיה זאת להם לדורותם\" (ויקרא יז, ה — ז). וכך יש להבין כתובים אלו: מה שנאמר \"למען אשר יביאו את זבחיהם אשר הם זובחים\", בא ללמד כי מדובר ב\u0003זבחים שהתרתי לך כבר,\u0004 שהוקדשו בזמן היתר במות, ומעתה שהוקם המשכן, עליהם להביאם אל פתח אהל מועד. \u0003\"על פני השדה\", לומר לך: הזובח בשעת איסור הבמות,\u0004 אפילו הזובח לה', \u0003מעלה עליו הכתוב כאילו הקריב על פני השדה\u0004 שלא לה'.","ומה שנאמר במקרא זה: \u0003\"והביאם לה'\"\u0004— \u0003זו מצות עשה\u0004 להביאם למשכן. שעוברים אף על מצות \u0003לא תעשה\u0004 אם מקריבים בחוץ קדשים אלו \u0003מניין? תלמוד לומר: \"ולא יזבחו עוד\"\u0004 (ויקרא יז, ז).","\u0003יכול יהא\u0004 השוחט בחוץ \u0003ענוש כרת\u0004 על זה, כמי שהקריב בחוץ קדשים שהוקדשו בזמן איסור במות? \u0003תלמוד לומר: \"חקת עולם תהיה זאת להם לדרתם\",\u0004 ללמד: \u0003זאת להם,\u0004 עונש על ביטול עשה ועל לא תעשה, \u0003ולא אחרת להם,\u0004 עונש כרת. נמצא איפוא כי מן הפסוק \"ולא יזבחו\" אין ללמוד אזהרה לאיסור שחיטת חוץ של קדשים שהוקדשו בזמן איסור במות!","\u0003אלא אמר ר' אבין:\u0004 נלמדת אזהרה לכך מ\u0003קל וחומר,\u0004 ובאופן זה: \u0003ומה במקום שלא ענש\u0004 הכתוב כרת על שחיטה בחוץ (בקדשים שהקדישם בשעת היתר במות) — \u0003הזהיר\u0004 על שחיטתם (\"ולא יזבחו\", ויקרא יז, ז), \u0003מקום שענש\u0004 הכתוב כרת על שחיטה בחוץ (כפי שלמדנו לגבי קדשים שהקדישם בשעת איסור במות) — \u0003אינו דין שהזהיר\u0004 על כך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אם כן,\u0004 לפי שיטה זו, שלמדים אזהרה מקל וחומר, מעתה \u0003לא יאמר\u0004 הכתוב איסור \u0003לאו ב\u0004אכילת \u0003חלב\u0004 בהמה טהורה, \u0003ותיתי\u0004 \u0005[ויבוא,\u0006 יילמד\u0005]\u0006 האיסור מ\u0003קל וחומר מנבילה,\u0004 ובאופן דומה: \u0003מה נבילה, שלא ענש\u0004 הכתוב כרת על אכילתה — \u0003הזהיר\u0004 עליה, שנאמר: \"לא תאכלו כל נבילה\" (דברים יד, כא), \u0003חלב שענש\u0004 עליו הכתוב עונש כרת על אכילתו (ויקרא ז, כה) — \u0003אינו דין שהזהיר\u0004 עליו?","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב אשי \u0005לפני]\u0006 \u0003רבא\u0004 והביא לפניו שאלה זו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 בדחייה: אזהרת חלב \u0003מנבלה נמי לא אתיא\u0004 \u0005[גם כן אינה באה,\u0006 נלמדת\u0005]\u0006 משום \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לשבור]\u0006 את הקל וחומר ולומר: \u0003מה לנבלה, שכן מטמא\u0004 במגעה, מה שאין כן בחלב.","הקשה לו: ועדיין ניתן ללמוד בדרך זו אזהרה לחלב בקל וחומר \u0003מ\u0004דין \u0003שרצים טמאין,\u0004 שנאמרה אזהרה לאכילתם (ויקרא יא, מא)! ודחה רבא: \u0003מה לשרצים טמאין,\u0004 שיש בהם חומרה, \u0003שמטמאין\u0004 אפילו \u0003במשהו,\u0004 מה שאין כן חלב ששיעורו בכזית כדי לטמא.","עוד הקשה לו רב אשי: נלמד אזהרה לאכילת חלב קל וחומר \u0003משרצים טהורים,\u0004 אלו שאין מטמאים במותם, שאף הם אסורים באכילה, ונאמרה בהם אזהרה (ויקרא יא, מא)! ודחה רבא: אין ללמוד מהם, שכן \u0003מה לשרצים טהורים ש\u0004גם \u0003איסורן\u0004 באכילה הוא \u0003ב\u0004שיעור \u0003משהו\u0004 וחלב — בכזית.","ושוב הקשה רב אשי: נלמד אזהרה לחלב \u0003מערלה וכלאי הכרם\u0004 שיש בהם אזהרה, והרי אלו איסורי אכילה ששיעורם בכזית! ודחה רבא: אין לומר כן, שכן \u0003מה לערלה וכלאי הכרם\u0004 שאיסורם חמור יותר, \u0003שכן אסורין בהנאה,\u0004 וחלב אסור רק באכילה.","וחזר והקשה רב אשי: נלמד אזהרת חלב \u0003מ\u0004איסור אכילת פירות השנה ה\u0003שביעית\u0004 שחלה עליהם חובת ביעור! ודחה רבא: \u0003מה לשביעית שכן\u0004 יש בה חומרה, לפי ש\u0003תופסת דמיה,\u0004 שכל דבר שמקבל עבור פירות שביעית נתפס בקדושת שביעית.","וחזר רב אשי והקשה: נלמד \u0003מתרומה,\u0004 שאסורה באכילה לזרים! ושוב דחה רבא: אין ללמוד ממנה, \u0003שכן לא הותר מכללה,\u0004 שאין לה היתר בשום מקום. אבל חלב הותר במקרה מסויים, וכגון בחיה טהורה שחלבה הותר באכילה. והוסיף רבא: ובדרך זו, אפשר לומר כי \u0003מכולהו נמי\u0004 \u0005[מכולם גם כן]\u0006 שהוצע מתחילה ללמוד מהם אזהרה לאיסור חלב בקל וחומר, אין ללמוד מהם, \u0003שכן לא הותרו מכללן.\u0004 ונמצא, איפוא, שאין להקשות מדין חלב, על שלמדנו אזהרה בדרך קל וחומר.","אלא \u0003אמר רבא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 ענין זה שלמדנו אזהרה לשחיטת חוץ בדרך קל וחומר, \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006 \u0003לי: הא דתנן\u0004 \u0005[זה ששנינו\u0006 במשנה\u0005]\u0006 במסכת כריתות: \u0003פסח ומילה מצו‍ת עשה\u0004 הן, ולכן אין חייבים חטאת אם ביטל מצוות אלו בשגגה, שאין מביאים חטאת אלא על שגגת לא תעשה שיש בה כרת.","ולפי דרך זו, \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 אזהרתם של אלה \u0003בקל וחומר ממותיר\u0004 קדשים לאחר זמן אכילתם, שנאמר: \"לא תותירו ממנו עד בקר\" (ויקרא כב, ל), ובאופן זה: \u0003מה מותיר שלא ענש\u0004 עליו הכתוב כרת, \u0003הזהיר\u0004 עליו הכתוב, \u0003פסח ומילה שענש\u0004 עליהם כרת \u0003אינו דין שהזהיר\u0004 עליהם?","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003רב כהנא,\u0004 מה שהתקשה רבא, \u0003ואמר לי:\u0004 אין להקשות מכאן, לפי ש\u0003ממותיר לא אתיא\u0004 \u0005[באה,\u0006 אי אפשר ללמוד\u0005]\u0006 אזהרה לפסח, \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]:\u0006 \u0003מה למותיר שכן אין לו תקנה, תאמר פסח\u0004 ש\u0003יש לו תקנה,\u0004 שהרי יכול לעשות פסח שני.","וחוזרים ומקשים מצד אחר: \u0003וכי מזהירין מן הדין?\u0004 וכי למדים אזהרה בדרך קל וחומר? הרי אין מן התנאים מי שסבור כן, ו\u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003עונשין מן הדין,\u0004 בכל זאת \u0003אין מזהירין מן הדין!\u0004","\u0003אלא\u0004 צריכים לומר כי אזהרת שחיטת חוץ (בקדשים שהוקדשו בשעת איסור במות) אינה נלמדת מקל וחומר, אלא \u0003כ\u0004שיטת \u0003ר' יוחנן,\u0004 ש\u0003אמר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו מגזירה שווה של \u0003הבאה הבאה\u0004 האמורה בשחיטה בחוץ ובהעלאה בחוץ, בשחיטה — \"אשר ישחט מחוץ למחנה ואל פתח אהל מועד לא הביאו\" (ויקרא יז, ג-ד), ובהעלאה — \"אשר יעלה עולה או זבח ואל פתח אהל מועד לא יביאנו\" (ויקרא יז, ח-ט),","\u0003מה להלן\u0004 בהעלאה בחוץ \u0003 לא ענש\u0004 כרת (ויקרא יז, ט) \u0003אלא אם כן הזהיר,\u0004 וכפי שלמדנו לעיל מן הכתוב \"השמר לך פן תעלה עולותיך\" וכו' (דברים יב, יג) \u0003אף כאן\u0004 בשחיטה בחוץ \u0003לא ענש\u0004 כרת (ויקרא יז, ד) \u0003אלא אם כן הזהיר.\u0004"],["\u0003רבא אמר:\u0004 צריכים לומר שהמקור לאזהרה על שחיטת חוץ הריהו \u0003כ\u0004דברי \u0003ר' יונה,\u0004 שכך \u0003אמר ר' יונה: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 אזהרת שחיטת חוץ מהיקש המלים \u0003\"שם\" \"שם\",\u0004 שכן נאמר \"כי אם במקום אשר יבחר ה' באחד שבטיך שם תעלה עולותיך\" (דברים יב, יד), ושוב נאמר באותו פסוק \"ושם תעשה כל אשר אנכי מצוך\", להשוות בין העלאה בחוץ לשאר עשיות, ובכללן שחיטה: \u0003מה להלן\u0004 בהעלאה, \u0003לא ענש\u0004 עליה כרת, כמבואר בספר ויקרא (יז, ט) \u0003אלא אם כן,\u0004 כלומר, מתוך ש\u0003הזהיר\u0004 עליה בפירוש, שנאמר: \"השמר לך פן תעלה עולותיך בכל מקום אשר תראה\" (דברים יב, יג), \u0003אף כאן\u0004 (בשחיטה בחוץ) \u0003לא ענש\u0004 עליה כרת (ויקרא יז, ד) \u0003אלא אם כן הזהיר\u0004 עליה.","וממשיכים לדון בענין המקור בתורה להלכות שנשנו במשנתנו. למדנו כי המקור לחיוב על העלאה בחוץ הוא בכתוב \"ואליהם תאמר איש וכו' אשר יעלה עולה או זבח ואל פתח אהל מועד לא יביאנו וכו' ונכרת האיש ההוא מעמיו\" (ויקרא יז, ח—ט). \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא מקור לדינם של \u0003מוקטרי פנים\u0004 קדשים שנשחטו במקדש \u0003שהעלן לחוץ,\u0004 שחייב עליהם, ואולם \u0003מוקטרי חוץ\u0004 קדשים שנשחטו בחוץ, שנזכרו בתחילת אותו פרק (ויקרא יז, ד) \u0003שהעלן לחוץ מנין\u0004 שחייב על העלאתם?","\u0003אמר רב כהנא, אמר קרא\u0004 \u0005[המקרא]\u0006 בתחילת ענין ההעלאה: \u0003\"ואלהם תאמר\"\u0004 (ויקרא יז, ח). ולשון \"ואליהם\" נקראת \"ועליהם\", כלומר, \u0003על הסמוכין תאמר,\u0004 כלומר, על אלו שהוזכרו תחילה, שנשחטו בחוץ.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ועליהם\"?\u0004 והלא \u0003\"ואליהם\" כתיב\u0004 \u0005[נאמר],\u0006 אל אהרן ואל בניו ואל בני ישראל, שהוזכרו בתחילת אותו פרק! \u0003אלא\u0004 המקור לכך הוא \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 שהכתוב \u0003\"ואלהם תאמר\"\u0004 בוא\"ו יתירה — הרי זה בא \u0003לערב פרשיות\u0004 השחיטה בחוץ וההעלאה בחוץ, ללמדנו שדין המעלה בחוץ הריהו מתייחס אף על הנשחט בחוץ.","\u0003ר' יוחנן אמר\u0004 הסבר אחר: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה \u0003\"הבאה\" \"הבאה\",\u0004 שבשתי פרשיות אלו נאמרה לשון \"הבאה\", בשחיטה בחוץ נאמר: \"ואל פתח אהל מועד לא הביאו\" (ויקרא יז, ד), ובהעלאה בחוץ נאמר: \"ואל פתח אהל מועד לא יביאנו\" (ויקרא יז, ט), והרי זה בא ללמד: \u0003מה להלן\u0004 (בשחיטה) הריהו חייב על \u0003מוקטרי\u0004 (שחוטי) \u0003חוץ, אף כאן\u0004 (בהעלאה) הריהו חייב אף על \u0003מוקטרי\u0004 (שחוטי) \u0003חוץ.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ביבי, הא דתנן\u0004 \u0005[זה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשים ושש כריתות\u0004 (עבירות שעונשן כרת) \u0003בתורה,\u0004 והמשנה מונה אותן, וביניהן המעלה קדשים בחוץ, הלא אם חייב גם על שחוטי חוץ, אם כן, \u0003תלתין ושב הויין\u0004 \u0005[שלושים ושבע הן],\u0006 \u0003דאיכא\u0004 \u0005[ש\u0006הרי \u0005יש]\u0006 חיוב כרת גם על \u0003המעלה\u0004 בחוץ קרבן שנשחט בפנים \u0003ו\u0004גם על \u0003המעלה\u0004 בחוץ דבר שלא נשחט בפנים, שכל אחד מהם נלמד ממקור אחר! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","וממשיכים עוד בבירור המקור בתורה להלכות שבענין זה. ושואלים: \u0003והדתנן\u0004 \u0005[וזה ששנינו]\u0006 במשנה להלן: \u0003הזורק מקצת דמים בחוץ חייב, מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003נפקא ליה מדתניא\u0004 \u0005[יוצא\u0006 נלמד הדבר \u0005מ\u0006מה \u0005ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בענין השוחט בחוץ: \u0003\"דם יחשב\u0004 לאיש ההוא דם שפך ונכרת האיש ההוא\" (ויקרא יז, ד) — הרי זה בא \u0003לרבות הזורק\u0004 את הדם, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 יש ללמוד דבר זה ממה שנאמר בענין המעלה בחוץ \"אשר יעלה עולה \u0003או זבח\"\u0004 (ויקרא יז, ח) — \"או\" \u0003לרבות את הזורק.\u0004","ושואלים: \u0003ור' ישמעאל, האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"או זבח\" מאי עביד ליה\u0004 \u0005[מה עושה,\u0006 לומד הוא \u0005בו]?\u0006 ומשיבים: הרי זה בא \u0003לחלק\u0004 ללמד שחייבים על העלאה בחוץ של עולה לחוד ושל שלמים לחוד, ולא רק כשהעלה את שניהם.","ושואלים: \u0003ור' עקיבא,\u0004 הלכה זו של \u0003לחלק מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004מה שנאמר שם: \"ואל פתח אהל מועד \u0003לא יביאנו\",\u0004 בלשון יחיד, אפילו אחד מהם.","\u0003ור' ישמעאל\u0004 מדוע הוא אינו לומד הלכה זו מ\"יביאנו\"? \u0003ההוא\u0004 \u0005[אותו\u0006 ביטוי\u0005]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כדי ללמד שרק \u0003על\u0004 \u0003השלם הוא חייב\u0004 אם העלהו (\"יביאנו\" — יביא אותו, כפי שהוא), \u0003ואינו חייב על החסר.\u0004 ושואלים: \u0003ור' עקיבא,\u0004 מנין לו הלכה זו? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 דין זה \u0003מ\u0004מה שנאמר באותו כתוב: \"לא יביאנו \u0003לעשות אתו\"\u0004 כלומר, כפי שהוא, בשלימותו.","ושואלים: \u0003ור' ישמעאל\u0004 מה הוא לומד מהכתוב \"לעשות אותו\"? ומשיבים: הוא סבור שצריכים שני מיעוטים בענין זה, \u0003חד\u0004 \u0005[אחד]\u0006 \u0003ל\u0004גבי \u0003מוקטרי\u0004 (שחוטי) \u0003פנים שחסרו והעלו בחוץ, וחד\u0004 \u0005[ואחד]\u0006 \u0003למוקטרי חוץ שחסרו והעלו בחוץ.\u0004 ומעירים: \u0003והא תניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: יכול מוקטרי פנים שחסרו והעלו בחוץ חייב? תלמוד לומר: \"לעשות אתו\"\u0004 — \u0003על השלם חייב, ואינו חייב על החסר.\u0004","ומעירים: \u0003ו\u0004אילו \u0003ר' עקיבא,\u0004 שאין לו אלא כתוב אחד לענין זה, הוא סבור ש\u0003מוקטרי פנים שחסרו והעלו בחוץ\u0004 — \u0003חייב.\u0004","ושואלים מצד אחר: \u0003ור' עקיבא, האי\u0004 \u0005[זה\u0006 הפסוק\u0005]\u0006 \u0003\"דם יחשב\"\u0004 (ויקרא יז, ד) שר' ישמעאל דורש לרבות זורק דמים בחוץ, \u0003מאי עביד ליה\u0004 \u0005[מה עושה,\u0006 דורש הוא \u0005בו]?\u0006 ומשיבים: \u0003לרבות שחיטת העוף\u0004 של קדשים בחוץ, שחייבים עליה, למרות שעוף קדשים נמלק בפנים, ושחיטה פסולה בו. ושואלים: \u0003ור' ישמעאל\u0004 מנין לו הלכה זו? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא\u0006 נלמד \u0005לו]\u0006 \u0003מ\u0004מה שנאמר \u0003\"או אשר ישחט\"\u0004 (ויקרא יז, ג), שהוא ריבוי.","\u0003ו\u0004מן הצד האחר, \u0003ר' עקיבא\u0004 \u0003אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 בשביל דבר אחר: \u0003על השוחט\u0004 עוף \u0003הוא חייב\u0004 משום שחיטת חוץ, \u0003ולא על המולק\u0004 בגוף, למרות שמליקה היא דרך עבודתו של העוף בפנים. ושואלים: \u0003ור' ישמעאל\u0004 מנין לו הלכה זו שאין חייבים על המליקה בחוץ? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שנאמר בתחילת פרשת שחיטת חוץ: \u0003\"זה הדבר\"\u0004 (ויקרא יז, ב).","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \"איש איש מבית ישראל \u0003אשר ישחט\u0004 שור או כשב או עז\" (ויקרא יז, ג) — \u0003אין לי\u0004 שנוהגת הלכה זו \u0003אלא\u0004 ב\u0003שוחט בהמה, שחט עוף\u0004 בחוץ \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שגם כן חייב? \u0003תלמוד לומר: \"או אשר ישחט\"\u0004 — \"או\" לרבות אף את שחיטת העוף.","\u0003יכול אף המולק\u0004 עוף בחוץ יהא חייב? \u0003ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא: מה שחיטה\u0004 ש\u0003אין דרך הכשירה בפנים,\u0004 שהרי אין שוחטים עופות במקדש, אלא מולקים, בכל זאת \u0003חייב\u0004 עליה בחוץ, \u0003מליקה ש\u0004היא \u0003דרך הכשירה בפנים,\u0004 \u0003אינו דין שהוא חייב\u0004 עליה בחוץ? \u0003תלמוד לומר\u0004 בתחילת הפרשה: \u0003\"זה הדבר\"\u0004 (ויקרא יז, ב), לומר שרק על שחיטה האמורה בכתוב מתחייב, ולא באופן אחר.","וחוזרים ושואלים: \u0003ור' עקיבא,\u0004 מדוע אין הוא לומד הלכה זו של מליקה מכאן? ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך],\u0006 \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 ביטוי, \"זה הדבר\", \u0005נצרך לו]\u0006 \u0003לגזירה שוה\u0004 לפרשת נדרים, שאף בה נאמר \"זה הדבר אשר צוה ה'\" (במדבר ל, ב).","וממשיכים עוד בבירור המקור בתורה להלכות שבענין זה. \u0003והא דתנן\u0004 \u0005[וזו ששנינו]\u0006 במשנה בפרק הבא: \u0003הקומץ\u0004 את המנחה בחוץ ולא הקטירה, \u0003ו\u0004כן \u0003המקבל דמים\u0004 מן הקרבנות \u0003בחוץ\u0004 ולא זרקם על המזבח — \u0003פטור, מנלן\u0004 \u0005[מנין לנו]?\u0006 ותמהים על עצם השאלה: \u0003ומהיכא תיתי\u0004 \u0005[ומהיכן תבוא,\u0006 תילמד\u0005]\u0006 שיהיה \u0003חייב?\u0004","אם תאמר \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005],\u0006 \u0003מ\u0004תוך השוואה ל\u0003שחיטה\u0004 בחוץ, שחייב אף שלא העלה — יש לפרוך השוואה זו ולומר: \u0003מה לשחיטה\u0004 שיש בה חומרה מיוחדת, \u0003שכן נפסלת\u0004 כששוחט \u0003שלא ל\u0004שם ה\u0003אוכלין\u0004 בקרבן ה\u0003פסח!\u0004","ואם תאמר: \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 שבקומץ והמקבל דמים בחוץ חייב \u0003מ\u0004תוך השוואה ל\u0003זריקה,\u0004 שאינה נפסלת במחשבה זו, ומכל מקום חייבים עליה, כפי שלמדנו לעיל — יש לפרוך ולומר: \u0003מה לזריקה\u0004 שיש בה חומרה מיוחדת, \u0003שכן\u0004 \u0003זר\u0004 שעשה אותה במקדש \u0003חייב עליה מיתה.\u0004 מה שאין כן בקמיצה ובקבלת הדם!"],["ואם תאמר: \u0003תיתי מבינייא\u0004 \u0005[\u0006ש\u0005תבוא,\u0006 תילמד \u0005מביניהן]\u0006 מן הצד השווה שבהן, בשחיטה וזריקה, שהן עבודות וחייב אם עשאן בחוץ — אין לומר כך,","ש\u0003אם כן,\u0004 שניתן ללמוד בדרך זו לגבי עבודות שאינן מפורשות בכתוב, \u0003לא יאמר\u0004 הכתוב \u0003בזריקה\u0004 שחייב עליה, \u0003ותיתי מבינייא\u0004 \u0005[ותבוא מביניהן],\u0006 משחיטה והעלאה.","שכך היית אומר: \u0003ותיתי\u0004 \u0005[ותבוא]\u0006 \u0003משחיטה\u0004 — \u0003מה לשחיטה שכן נפסלת\u0004 כשעשאה \u0003שלא לשם אוכלין בפסח. תיתי\u0004 \u0005[תבוא]\u0006 \u0003מהעלאה\u0004 — \u0003מה להעלאה שכן ישנה\u0004 גם \u0003במנחה,\u0004 וזריקת דמים אינה קיימת במנחה. ומכל מקום יש לומר: \u0003ותיתי מבינייא\u0004 \u0005[ותבוא מביניהן],\u0006 שהן עבודות וחייבין עליהן אם נעשו בחוץ, והוא הדין לזריקה —","\u0003להכי כתיב קרא\u0004 \u0005[ל\u0006שם \u0005כך בא הכתוב]\u0006 בזריקה, \u0003למימר דלא אתא מבינייא\u0004 \u0005[לומר שאינה באה מביניהן].\u0006 ומתוך שלמדנו מזריקה שאין למדים בדרך זו, נמצא שבקמיצה ובקבלת הדם, שאין להן מקור בכתוב — אין לחייב משום עבודה בחוץ.","בעקבות מחלוקת ר' ישמעאל ור' עקיבא בעמוד הקודם, מהו המקור לחיוב על זריקה בחוץ, \u0003אמר ר' אבהו:\u0004 מי ש\u0003שחט\u0004 קדשים \u0003ו\u0004גם \u0003זרק\u0004 דמם בחוץ, \u0003לדברי ר' ישמעאל חייב\u0004 חטאת \u0003אחת,\u0004 שהרי הוא לומד חיוב על זריקה ממה שנאמר \"דם יחשב\" בענין שחיטה (ויקרא יז, ד), ואם כן הרי זה חיוב אחד. \u0003לדברי ר' עקיבא\u0004 שלומד חיוב על זריקה ממה שנאמר בענין העלאה \"או זבח\" (ויקרא יז, ח) — \u0003חייב שתים.\u0004","\u0003אביי אמר: אפילו [לדברי] ר' עקיבא אינו חייב אלא אחת,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באזהרה על עבודות חוץ: \"כי אם במקום אשר יבחר ה' באחד שבטיך שם תעלה עולותיך ושם תעשה כל אשר אנכי מצוך\" (דברים יב, יד), ובלשון הכללית \u0003\"שם תעשה\" הכתוב עשאן לכולן\u0004 לכל העבודות (חוץ מהעלאה) \u0003עבודה אחת,\u0004 שאינו חייב עליהן אלא חטאת אחת.","ועוד אמר ר' אבהו (לשיטתו): אם \u0003זרק והעלה\u0004 בחוץ בהעלם אחד, \u0003לדברי ר' ישמעאל\u0004 שלמד דין זריקה משחיטה \u0003חייב שתים,\u0004 אחת משום זריקה ואחת משום העלאה. \u0003לדברי ר' עקיבא\u0004 שלמד דין זריקה מהעלאה, \u0003אינו חייב אלא אחת.\u0004","\u0003אביי אמר: אפילו [לדברי] ר' עקיבא חייב שתים,\u0004 משום ש\u0003להכי פלגינהו קרא\u0004 \u0005[לכך חילק אותם הכתוב]\u0006 את ההעלאה לחוד ואת שאר העבודות לחוד, ואמר: \u0003\"שם תעלה... ושם תעשה\"\u0004 (דברים יב, יד), כדי לחייב על העלאה לחוד ועל זריקה לחוד.","הוסיף ר' אבהו ואמר: אם \u0003שחט וזרק והעלה\u0004 בחוץ בהעלם אחד — \u0003לדברי הכל,\u0004 בין לר' ישמעאל ובין לר' עקיבא, \u0003חייב שתים.\u0004","עוד בדין השוחט קדשים בחוץ, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 נאמר בענין זה: \"איש איש מבית ישראל אשר ישחט שור או כשב או עז במחנה או אשר ישחט מחוץ למחנה\" (ויקרא יז, ג). הואיל ונאמר \"אשר ישחט ... \u0003במחנה\",\u0004 ומשמע — אף בתוך המחנה, \u0003יכול השוחט עולה,\u0004 שהיא קדשי קדשים \u0003בדרום\u0004 העזרה, ולא בצפונה, אף הוא \u0003יהא חייב\u0004 כדין השוחט בחוץ? \u0003תלמוד לומר\u0004 מיד בהמשך: \"או אשר ישחט \u0003(אל) מחוץ למחנה\",\u0004 ללמד שדווקא חוץ למחנה חייב.","\"מחוץ למחנה\" — \u0003יכול\u0004 לא יהא חייב אלא כששחט \u0003חוץ לשלש מחנות\u0004 מחנה שכינה, מחנה לויה ומחנה ישראל \u0003(תלמוד לומר: או עז במחנה\"),\u0004 \u0003מנין\u0004 שחייב \u0003אף\u0004 על שחיטה \u0003במחנה לוייה? תלמוד לומר:\u0004 \"אשר ישחט \u0003במחנה\".\u0004","ושבים ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 למדים אנו מהכתוב \u0003\"במחנה\",\u0004 שחייב גם על שחיטה בתוך המחנה, \u0003יכול\u0004 אף \u0003השוחט עולה בדרום\u0004 העזרה \u0003יהא חייב? תלמוד לומר: \"או\u0004 אשר ישחט \u0003(אל) מחוץ למחנה\",\u0004 להשמיענו:","\u0003מה חוץ למחנה מיוחד\u0004 בכך שהוא מקום \u0003שאין ראוי\u0004 לא \u0003לשחיטת\u0004 קדשי \u0003קדשים ו\u0004לא \u0003לשחיטת כל זבח,\u0004 אף מה שנאמר \"במחנה\" — מקום שאינו ראוי לשחיטת כל זבח. \u0003יצא דרום שאף על פי שאין ראוי לשחיטת קדשי קדשים\u0004 הריהו \u0003ראוי לשחיטת קדשים קלים,\u0004 ולכן, אין זה בכלל שחיטה בחוץ.","ועל פי כלל זה, \u0003אמר עולא: השוחט\u0004 קדשים \u0003על גגו של היכל\u0004 — \u0003חייב\u0004 משום שחיטה בחוץ, \u0003הואיל ואין ראוי לשחיטת כל זבח,\u0004 שאינו בכלל העזרה הכשירה לשחיטת קדשים. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אם כן, ניכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 רק: \"או אשר ישחט \u0003(אל) מחוץ למחנה\" ולא בעי\u0004 \u0005[צריך]\u0006 מה שנאמר מיד אחר כך: \u0003\"ו\u0004אל פתח אהל מועד לא הביאו\" (ויקרא יז, ד), \u0003\"ו\u0004אל פתח אהל מועד\" למה לי? לאו למעוטי \u0005[האם לא למעט]\u0006 את \u0003גגו,\u0004 שאין חייבים על השחיטה בו, למרות שאינו ראוי לשחיטת כל זבח, שהרי הביאו אל פתח אוהל מועד?","ושואלים: \u0003ול\u0004שיטת \u0003רבא,\u0004 שכל העזרה והגג בכללה נחשבת כפתח אוהל מועד, \u0003אם כן נכתוב\u0004 \u0005[שיכתוב]\u0006 רק \u0003\"אל פתח אהל מועד\u0004 לא הביאו\", ומכאן נלמד שכל השוחט חוץ לעזרה חייב, ואם כן \u0003\"במחנה\" \"ואל מחוץ למחנה\" למה לי? לאו לאתויי\u0004 \u0005[האם לא\u0006 נלמד מ\"במחנה\" \u0005להביא\u0006 לרבות\u0005]\u0006 את השחיטה על \u0003גגו\u0004 של היכל לחייב עליה למרות שהיא בכלל העזרה, ומשום כך הוצרך ל\"מחוץ למחנה\" למעט עולה ששחטה בדרום?","\u0003אמר רב מרי:\u0004 לא, יש לומר כי \"במחנה\" הובא \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 מקרה אחר, כשהיתה בהמת קדשים \u0003כולה בפנים\u0004 (בעזרה) \u0003ו\u0004אילו \u0003צוארה\u0004 היה \u0003בחוץ,\u0004 ושחטה כך, ללמדנו שחייב על כך, ומשום כך הוצרך ל\"מחוץ למחנה\" למעט עולה ששחטה בדרום.","ותוהים: כש\u0003[צוארה] בחוץ, פשיטא\u0004 \u0005[פשוט]\u0006 שחייב על כך, ואין צורך למקרא שילמדנו זאת, שהרי \u0003אמאי קפיד רחמנא\u0004 \u0005[על מה הקפידה התורה]?\u0006 על ה\u0003שחיטה, ו\u0004במקרה זה ה\u0003שחיטה בחוץ היא,\u0004 שהרי צווארה בחוץ! ומשיבים: \u0003אלא\u0004 \"במחנה\" בא \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 מקרה אחר, ש\u0003כולה\u0004 עומדת \u0003בחוץ וצוארה בפנים,\u0004 ושחטה כך, שבכל זאת היא נחשבת כבחוץ, וחייב על כך.","עוד בדין העלאה בחוץ. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המעלה\u0004 קדשים בחוץ \u0003בזמן הזה\u0004 (בימינו) שאין עדיין בית המקדש קיים — \u0003ר' יוחנן אמר: חייב, ריש לקיש אמר: פטור.\u0004","ומסבירים את שיטותיהם, \u0003ר' יוחנן אמר חייב,\u0004 משום ש\u0003קדושה ראשונה\u0004 שנתקדש בית המקדש \u0003קידשה לשעתה וקידשה לעתיד לבא,\u0004 גם לאחר החורבן, ויש אפשרות לבנות שם מזבח ולהקריב עליו. ולכן העלאה שלא במקום המקדש הריהי העלאה בחוץ. \u0003ריש לקיש אמר פטור,\u0004 משום ש\u0003קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא,\u0004 ואין זו איפוא העלאה בחוץ.","ושואלים: \u0003נימא\u0004 \u0005[האם נאמר]\u0006 \u0003דבפלוגתא\u0004 \u0005[שבמחלוקת]\u0006 של \u0003ר' אליעזר ור' יהושע קמיפלגי\u0004 \u0005[חלוקים הם]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003אמר ר' אליעזר:\u0004 שמעתי במסורת, כי \u0003כשהיו בונין בהיכל\u0004 בימי עזרא, \u0003היו עושים\u0004 תחילה \u0003קלעים\u0004 (יריעות) כמחיצות \u0003בהיכל,\u0004 קודם שבנו שם את הבנין מאבנים, וגם עשו \u0003קלעים בעזרות. אלא שבהיכל\u0004 היו \u0003בונין מבחוץ\u0004 לקלעים, כדי שלא ייכנסו הבונים לתוך ההיכל, \u0003ובעזרה\u0004 היו \u0003בונין מבפנים\u0004 לקלעים.","\u0003אמר ר' יהושע: שמעתי שהיו מקריבין\u0004 קרבנות על המזבח במקום המקדש \u0003אף על פי שאין בית\u0004 בנוי, \u0003ואוכלים קדשי קדשים, אף על פי שאין קלעים\u0004 לעזרה, וכן שהיו אוכלים \u0003קדשים קלים ומעשר שני\u0004 בירושלים \u0003אף על פי שאין חומה\u0004 לירושלים, \u0003מפני שקדושה ראשונה\u0004 שנתקדש המקדש בימי שלמה \u0003קידשה לשעתה וקידשה לעתיד לבא.\u0004","לאו \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים האלה עולה ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 כי קדושה ראשונה \u0003לא קידשה\u0004 לעתיד לבוא? ולכן הוצרכו לעשות מחיצות — כדי שיוכלו לקדש את העזרה ולהקריב בה עוד קודם שיושלם בנין המקדש. ואם כן מחלוקת ר' יוחנן וריש לקיש הריהי לכאורה כמחלוקתם של תנאים אלו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח שנחלקו ר' אליעזר ור' יהושע בדבר זה? \u0003דלמא דכולי עלמא\u0004 \u0005[שמא לדעת הכל]\u0006 \u0003קדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא,\u0004 אלא \u0003מר מאי דשמיע ליה קאמר\u0004 \u0005[חכם זה מה ששמע אמר],\u0006 \u0003ומר מאי דשמיע ליה קאמר\u0004 \u0005[וחכם זה מה ששמע אמר],\u0006 ואין מחלוקת ביניהם כלל! \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 כיון שקדושה ראשונה קיימת, \u0003קלעים ל\u0004דעת \u0003ר' אליעזר למה לי?\u0004 התשובה היא: \u0003לצניעותא בעלמא\u0004 \u0005[לצניעות בלבד],\u0006 שאין זה נאה שהמקום הקדוש יהיה גלוי.","ועוד בדין העלאת קדשים בחוץ, \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003המעלה\u0004 איבר קרבן בחוץ \u0003ואין בו\u0004 בבשרו שיעור \u0003כזית, ו\u0004היתה בו \u0003עצם\u0004 ש\u0003משלימו ל\u0004שיעור \u0003כזית\u0004 — \u0003ר' יוחנן אמר: חייב, ריש לקיש אמר: פטור.\u0004","ומסבירים את שיטותיהם, \u0003ר' יוחנן אמר חייב\u0004, משום שלדעתו \u0003חיבורי\u0004 הקרבנות ה\u0003עולין\u0004 למזבח, כגון עצם המחוברת לבשר, שאין מצווה להעלותה כשלעצמה — \u0003כעולין דמי\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 כאשר הם עם הבשר, ולכן מצטרפת העצם לבשר הקרבן להתחייב על העלאתו בחוץ. \u0003ריש לקיש אמר פטור,\u0004 כי לדעתו \u0003חיבורי עולין לאו\u0004 \u0005[לא]\u0006 \u0003כעולין דמו\u0004 \u0005[נחשבים].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: \u0003המעלה\u0004 בחוץ"],["\u0003ראש בן יונה\u0004 של עולת העוף, \u0003שאין בו\u0004 בעצמו \u0003כזית, ו\u0004אולם ה\u0003מלח\u0004 שניתן עליו, כדין כל קרבן, הריהו \u0003משלימו לכזית, מהו?\u0004 האם יתחייב על העלאתו בחוץ?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזקיא לרב אשי: לאו היינו פלוגתייהו\u0004 \u0005[האם אין זו מחלוקתם]\u0006 של \u0003ר' יוחנן וריש לקיש\u0004 בדין השלמת עצם לשיעור כזית? השיב לו רב אשי: עדיין \u0003תיבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 שאלה זו \u0003ל\u0004דעת \u0003ר' יוחנן, ותיבעי\u0004 \u0005[ו\u0006כן \u0005תישאל]\u0006 \u0003ל\u0004דעת \u0003ריש לקיש.\u0004","ומסבירים: \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לר' יוחנן\u0004 הסבור שעצם מצטרפת לבשר להשלים לכזית, שכן \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' יוחנן התם\u0004 \u0005[שם]\u0006 את שיטתו זו \u0003אלא\u0004 דווקא בדינה של \u0003עצם,\u0004 משום \u0003דמינא\u0004 \u0005[שמין]\u0006 של \u0003בשר הוא,\u0004 ולכן אפשר לומר שמצטרפת היא אל הבשר, \u0003אבל מלח דלאו מינא דבר\u0004 \u0005[שאינו מין של בן]\u0006 \u0003יונה הוא\u0004 — שמא \u0003לא\u0004 מצטרף לבשר הקרבן. וכן \u0003תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לריש לקיש,\u0004 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[שאומר]\u0006 \u0003ריש לקיש התם\u0004 \u0005[שם]\u0006 שאין העצם מצטרפת לבשר, \u0003אלא\u0004 משום שהדין הוא \u0003דאי פריש מינה, לאו מצוה לאסוקי\u0004 \u0005[שאם פרשה\u0006 העצם ממנה, מבשר הקרבן \u0005אין מצוה\u0006 לשוב ו\u0005להעלותה\u0006 למזבח\u0005],\u0006 \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במלח\u0005],\u0006 \u0003דאי פריש\u0004 \u0005[שאם פרש]\u0006 מן הקרבן יש \u0003מצוה\u0004 לחזור ו\u0003לאסוקי\u0004 \u0005[להעלותו],\u0006 שהרי אין קרבן קרב בלא מלח — שמא \u0003לא\u0004 אמר ריש לקיש את שיטתו זו, והמלח מצטרף עם הבשר לשיעור כזית. ומן הצד השני, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 נאמר שאין הבדל בין דין העצם ודין המלח, וכשיטת ר' יוחנן וריש לקיש לענין עצם, כן שיטתם לענין מלח.","ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעייה בלא פתרון.","שנינו במשנה: \u0003ר' יוסי הגלילי אומר:\u0004 השוחט בחוץ והעלה בחוץ — פטור על ההעלאה, משום שלא העלה אלא דבר פסול. והקשו עליו חכמים, שלשיטתו אף השוחט בפנים ומעלה בחוץ יהיה פטור על ההעלאה, שהרי כבר נפסל הקרבן בשעה שיצא מן העזרה. ולא נשנתה במשנה תשובתו של ר' יוסי לטענה זו.","ובברייתא נאמר, \u0003השיב רבי תחת\u0004 (במקום) \u0003ר' יוסי הגלילי:\u0004 יש הבדל בין הדברים, שכן \u0003מה לשוחט בפנים ומעלה בחוץ,\u0004 שחייב על העלאתו, \u0003ש\u0004כן \u0003היתה לו שעת הכושר\u0004 להקריבו בפנים, והקריבו בחוץ, \u0003תאמר בשוחט חוץ ומעלה בחוץ, שלא היתה לו שעת הכושר\u0004 להעלאה מעולם? שהרי נפסל בשחיטתו.","ובאופן אחר \u0003השיב ר' אלעזר בר' שמעון תחת ר' יוסי הגלילי: מה לשוחט בפנים ומעלה בחוץ,\u0004 שחייב על ההעלאה, \u0003שכן קודש מקבלו\u0004 שאף שהוא פסול לכתחילה להקרבה, אם חזר והכניסו למקדש והעלהו על המזבח, אין מורידים אותו (לעיל זבחים פד,א), \u0003תאמר בשוחט בחוץ, שאין קודש מקבלו?\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם,\u0006 בין רבי ור' אלעזר בר' שמעון\u0005]?\u0006 \u0003אמר זעירי: שחיטת לילה\u0004 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 ששחט קרבן בלילה בפנים, והוציאו לחוץ והעלהו: להסברו של רבי, כיון שלא היתה לו שעת הכושר להקרבה, שהרי נפסל בשחיטה — הריהו פטור על ההעלאה בחוץ. ולהסברו של ר' אלעזר בר' שמעון, כיון שהקודש מקבלו, שהרי אם עלה לא ירד — הריהו חייב על ההעלאה בחוץ.","\u0003רבה אמר:\u0004 \u0003קבלה\u0004 שקיבל דמו של הקרבן \u0003בכלי חול איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שהואיל ודם זה פסול ואין זורקים אותו — לא היתה לקרבן שעת הכושר, ולכן להסבר רבי אינו חייב על ההעלאה בחוץ. ואולם בדיעבד הקודש מקבלו, ולכן להסבר ר' אלעזר בר' שמעון הריהו חייב על ההעלאה בחוץ.","עוד שנינו במשנה: אדם \u0003טמא שאכל בין\u0004 בשר \u0003קודש\u0004 טמא ובין קדש טהור, הריהו חייב משום אכילת קדשים בטומאה. ור' יוסי סבור שטמא שאכל קודש טמא — הריהו פטור, הואיל ולא אכל אלא דבר טמא. והקשו עליו חכמים: אף טמא שאכל קודש טהור, כיון שנגע בו כדי לאוכלו הרי טימאו בכך, ובכל זאת מודה ר' יוסי שהוא חייב על אכילתו, ומה ההבדל באיזה אופן נטמא הבשר?","ושואלים: \u0003שפיר קאמרי ליה רבנן\u0004 \u0005[יפה אומרים לו חכמים]\u0006 \u0003לר' יוסי הגלילי,\u0004 ומה הוא עונה על כך?","\u0003אמר רבא:\u0004 באמת, \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003נטמא טומאת הגוף\u0004 (שנטמא האדם) \u0003ואחר כך נטמא בשר\u0004 הקודש — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 וגם ר' יוסי הגלילי סבור שהוא \u0003חייב, שכן\u0004 איסור אכילת הקודש ב\u0003טומאת הגוף\u0004 שהוא \u0003בכרת\u0004 כבר חל, ושוב אינו פוקע גם אם נטמא הקודש.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו\u0006 ר' יוסי וחכמים\u0005]\u0006 הרי זה \u0003כשנטמא בשר\u0004 ונאסר באכילה, \u0003ואחר כך נטמא הגוף,\u0004","\u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 אף שבדרך כלל אין איסור חל על איסור, הרי כאן איסור אכילת קדשים בטומאת הגוף — איסור כולל הוא, שהוא חל על כל הקדשים, ובמקרה זה \u0003אמרינן מיגו\u0004 \u0005[אומרים אנו \"מתוך\"],\u0006 כלומר, מתוך שחל איסור טומאת הגוף על אכילת בשר טהור, הוא חל גם על אכילת הבשר הטמא. \u0003ו\u0004אילו \u0003ר' יוסי הגלילי סבר\u0004 \u0005[סבור]:\u0006 \u0003לא אמרינן מיגו\u0004 \u0005[אין אנו אומרים \"מתוך\"],\u0006 ולכן חל כאן הכלל שאין איסור חל על איסור.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יוסי, נהי דמיגו לא אמרינן\u0004 \u0005[אם אמנם ש\"מתוך\"\u0006 \u0005אין אנו אומרים],\u0006 מכל מקום \u0003תיתי\u0004 \u0005[תבוא]\u0006 \u0003טומאת הגוף דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 \u0003ו\u0004משום כך \u0003תחול על טומאת בשר!\u0004","\u0003אמר רב אשי: ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 ש\u0003טומאת הגוף חמורה? דלמא\u0004 \u0005[שמא]\u0006 \u0003טומאת בשר חמורה.\u0004 שאף על פי שאין עונשה מרובה כשל טומאת הגוף, יש צד אחר שהיא חמורה בה, \u0003שכן אין לה טהרה במקוה\u0004 כטומאת גוף האדם שנטמא!","ועוד בהלכות שחיטת קדשים והעלאתם מחוץ לעזרה: יש \u0003חומר\u0004 \u0003בשחיטה מבעלייה\u0004 (העלאה), \u0003ו\u0004יש חומרה \u0003בעלייה מבשחיטה.\u0004","ומפרטים: \u0003חומר בשחיטה\u0004 מהעלאה, \u0003שהשוחט\u0004 קדשים בחוץ אפילו \u0003להדיוט,\u0004 כלומר, לצורך אכילת אדם ולא לשם שמים — \u0003חייב, ו\u0004אילו \u0003המעלה\u0004 קרבן בחוץ \u0003ל\u0004שם \u0003הדיוט\u0004 — \u0003פטור. חומר בעלייה\u0004 משחיטה: \u0003שנים שאחזו בסכין ו\u0004ביחד \u0003שחטו\u0004 קדשים בחוץ — \u0003פטורים,\u0004 אבל אם שנים \u0003אחזו באבר\u0004 מהקרבן \u0003והעלו\u0004 אותו ביחד בחוץ — \u0003חייבין.\u0004","ועוד בהלכות העלאת קדשים בחוץ: אם \u0003העלה\u0004 קדשים בחוץ בשגגה, ו\u0003חזר והעלה\u0004 חלקים מאותה בהמה בשגגה, \u0003ו\u0004שוב \u0003חזר והעלה\u0004 — \u0003חייב\u0004 חטאת \u0003על כל עלייה, דברי ר' שמעון. ר' יוסי אומר: אינו חייב אלא אחת.\u0004","ועוד אמר ר' יוסי בהלכות אלו: \u0003ואינו חייב\u0004 על העלאה בחוץ \u0003עד שיעלה לראש המזבח\u0004 דווקא. \u0003ר' שמעון אומר: אפילו העלה\u0004 בחוץ \u0003על הסלע או על האבן\u0004 שאינם מזבח — גם כן \u0003חייב.\u0004","שנינו במשנה שהשוחט קדשים בחוץ להדיוט הריהו חייב על כך, ואילו המעלה בחוץ להדיוט פטור. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003המעלה להדיוט\u0004 ש\u0003פטור\u0004 על כך? משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדינו של השוחט קדשים בחוץ: \"ואל פתח אהל מועד לא יביאנו לעשות אותו \u0003לה'\"\u0004 (ויקרא יז, ט), שאינו חייב על העלאה בחוץ אלא אם כן היה זה לה', ואולם \u0003בשחיטה נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 בדומה לכך: \"...או אשר ישחט מחוץ למחנה. ואל פתח אהל מועד לא הביאו להקריב קרבן \u0003לה'\"\u0004 (ויקרא יז, ג — ד)!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם\u0006 בשחיטה], ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"איש איש\u0004 מבית ישראל... או אשר ישחט מחוץ למחנה\" (ויקרא יז, ג), והרי זה לשון ריבוי, שאף על שחיטה להדיוט הריהו חייב. ומקשים: והרי \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003העלאה נמי כתיב\u0004 \u0005[גם כן נאמר]:\u0006 \u0003\"איש איש\"\u0004 (ויקרא יז, ח)! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ריבוי זה \u0003ל\u0004רבות \u0003שנים שהעלו באבר\u0004 שהם \u0003חייבין.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הכא נמי מיבעי ליה\u0004 \u0005[כאן גם כן\u0006 בשחיטה \u0005צריך אותו]\u0006 \u0003לשנים שאחזו בסכין ושחטו שחייבין,\u0004 ולא כפי ששנינו במשנתנו! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם\u0006 בשחיטה בחוץ\u0005],\u0006 שכן \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"ונכרת האיש \u0003ההוא\"\u0004 (ויקרא יז, ד), לומר: בענין זה מדובר דווקא באדם \u0003אחד ולא שנים.\u0004","ומקשים על כך: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003העלאה נמי\u0004 \u0005[גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \"ונכרת האיש \u0003ההוא\"\u0004 (ויקרא יז, ט)!"],["ומשיבים: אותו מקרא האמור בהעלאה \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 המעלה קדשים בחוץ כשהוא \u0003שוגג,\u0004 או \u0003אנוס ו\u0004כן כשהוא \u0003מוטעה\u0004 בדבר. שכן הלשון \"ההוא\" מורה על אדם שלם בדעתו בדבר זה שהוא עושה. וחוזרים ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הכא נמי מיבעי למעוטי\u0004 \u0005[כאן\u0006 בשחיטה בחוץ \u0005גם כן צריך\u0006 \"ההוא\" כדי \u0005למעט]\u0006 \u0003אנוס שוגג ומוטעה!\u0004","ומשיבים: \u0003תרי\u0004 \u0005[שתי]\u0006 \u0003\"ההוא\" כתיבי\u0004 \u0005[נאמרו]\u0006 בדין השוחט בחוץ (\"דם יחשב לאיש ההוא דם שפך ונכרת האיש ההוא\", ויקרא יז, ד), ומן האחד למדים למעט אנוס שוגג ומוטעה, ומן האחר למדים למעט שנים ששחטו בחוץ. בתחילת הדיון נאמר כי אף שנאמר \"לה'\" בענין שחיטה בחוץ (ויקרא יז, ד), מכל מקום גם השוחט להדיוט חייב, מריבוי הכתובים \"איש איש\".","\u0003ו\u0004שואלים: \u0003אלא\u0004 לפי זה \u0003\"לה'\" למה לי?\u0004 ומשיבים: \u0003להוציא שעיר המשתלח\u0004 ביום הכיפורים, שאם שחטו בחוץ איננו חייב עליו כרת.","עוד שנינו במשנתנו שיש \u0003חומר\u0004 (חומרה) \u0003בהעלאה\u0004 מבשחיטה, ששנים שהעלו ביחד אבר קדשים בחוץ — חייבים, ואילו שנים ששחטו ביחד — פטורים.","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה שנאמר בדינו של המעלה קדשים בחוץ: \u0003\"איש איש...\u0004 אשר יעלה עולה או זבח\". (ויקרא יז, ח), \u0003מה תלמוד לומר\u0004 (איזה לימוד מלמדנו יתור לשון זה)? הרי זה בא \u0003לרבות שנים שאחזו באבר והעלו שחייבין.\u0004 ונצרך לכך לימוד מיוחד משום \u0003שיכול\u0004 היית לומר: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה\u0004 שחיטה בחוץ שהיא חמורה, שהרי \u0003השוחט להדיוט שחייב\u0004 על כך, בכל זאת \u0003שנים שאחזו בסכין ושחטו\u0004 יחד — \u0003פטורין.\u0004 העלאה בחוץ שהיא קלה, שהרי \u0003המעלה להדיוט שפטור\u0004 על כך — \u0003אינו דין\u0004 \u0003ששנים שאחזו\u0004 באבר והעלוהו יהיו \u0003פטורין?\u0004 לכך \u0003תלמוד לומר: \"איש איש\"\u0004 לרבות, אלו \u0003דברי ר' שמעון.\u0004","\u0003ר' יוסי אומר:\u0004 מה שנאמר בדינו של המעלה \"האיש \u0003ההוא\"\u0004 (ויקרא יז, ט) — דווקא \u0003אחד ולא שנים. אם כן, מה תלמוד לומר \"איש איש\"?\u0004 אין כפילות זו באה ללמדנו דבר, אלא \u0003דברה תורה כלשון בני אדם.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003ר' שמעון,\u0004 מה מלמדנו הלשון \"ההוא\"? ומשיבים: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003\"ההוא\" מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שוגג, אנוס, מוטעה.\u0004 חוזרים ושואלים: \u0003ור' יוסי,\u0004 שלומד מכאן לפטור שנים שהעלו, מהיכן לומד הוא פטור שוגג אנוס ומוטעה? ומשיבים: דין זה נלמד \u0003מ\u0004מה שהיה יכול לכתוב \u0003\"הוא\",\u0004 וכתב \u0003\"ההוא\".\u0004 ומעירים: \u0003ו\u0004אילו \u0003ר' שמעון,\u0004 את הייתור \u0003\"הוא\" \"ההוא\" לא דריש\u0004 \u0005[אינו דורש].\u0006","ומקשים: \u0003ו\u0004לשיטת \u0003ר' יוסי, מדהאי\u0004 \u0005[מ\u0006תוך \u0005שזה]\u0006 מה שנאמר \u0003\"איש איש\"\u0004 בהעלאה, אינו מלמד דבר, אלא \u0003דברה תורה כלשון בני אדם,\u0004 אם כן יש לומר לגבי \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003\"איש איש\"\u0004 בשחיטה (ויקרא יז, ג) \u0003נמי\u0004 \u0005[גם כן]\u0006 כי \u0003דברה תורה כלשון בני אדם. ואלא\u0004 לפי זה \u0003השוחט להדיוט מנא ליה\u0004 \u0005[מנין לו]\u0006 ש\u0003חייב?\u0004 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר \u0003מ\u0004מה שנאמר: \u0003\"דם יחשב לאיש ההוא דם שפך\"\u0004 (ויקרא יז, ד) — \u0003ואפילו השוחט לאיש,\u0004 ולא רק לה'.","עוד שנינו במשנתנו בדין העלאת קדשים בחוץ, שאם \u0003העלה\u0004 בשוגג, ונודע לו, \u0003וחזר והעלה\u0004 בשוגג, לדעת ר' שמעון חייב חטאת על כל העלאה והעלאה, ולדעת ר' יוסי אינו חייב אלא אחת בלבד.","ובהסבר מחלוקתם \u0003אמר ריש לקיש: מחלוקת\u0004 זו היא דווקא \u0003בארבעה וחמשה אברים,\u0004 שהעלם בנפרד, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 בענין המעלה בחוץ \u0003\"לעשות אתו\"\u0004 (ויקרא יז, ט), ומשם למדנו כי דווקא \u0003על השלם\u0004 \u0003הוא חייב ואינו חייב על החסר\u0004 — על \u0003כל הבהמה כתיב\u0004 \u0005[נאמר],\u0006 שרק אם העלה את כל הבהמה הוא חייב. ולכן גם אם העלה ארבעה וחמישה איברים בנפרד אינו חייב אלא אחת. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 הלשון \"אותו\" — על \u0003כל אבר ואבר כתיב\u0004 \u0005[נאמר],\u0006 ולכן המעלה ארבעה וחמישה איברים הריהו חייב על כל העלאה והעלאה. \u0003אבל\u0004 במעלה \u0003אבר אחד\u0004 שחתכו והעלהו בכמה פעמים — \u0003דברי הכל אינו חייב אלא אחת.\u0004","\u0003ור' יוחנן אמר: מחלוקת\u0004 ר' יוסי ור' שמעון היא דווקא \u0003ב\u0004מקרה שהעלה \u0003אבר אחד,\u0004 שחתכו והעלהו בכמה פעמים. ואף שבקדשים שנשחטו בחוץ אין חולק על כך שאינו חייב על העלאה בחוץ של איבר חסר, נחלקו כאן בקדשים שנשחטו בפנים והוא מעלה אותם בחוץ, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003מוקטרי פנים,\u0004 כלומר, קרבנות שנשחטו בפנים, \u0003שחסרו\u0004 איבריהם, \u0003והעלה\u0004 את האיבר החסר \u0003בחוץ\u0004 — \u0003חייב\u0004 עליו, ולכן אם העלה בנפרד חלקים של איבר כזה — הריהו חייב על כל אחד ואחד. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 מוקטרי פנים שחסרו והעלם בחוץ — \u0003פטור,\u0004 ולכן אינו חייב אלא חטאת אחת על כל האיבר. \u0003אבל בארבעה וחמשה איברין\u0004 שהעלם בנפרד — \u0003דברי הכל חייב על כל אבר ואבר,\u0004 ולא רק על בהמה שלמה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקים]\u0006 דברים אלה על דברי \u0003עולא,\u0004 ש\u0003אמר עולא: הכל מודים במוקטרי פנים שחסרו והעלו בחוץ שחייב\u0004 עליהם. \u0003לא נחלקו אלא במוקטרי בחוץ שחסרו והעלו בחוץ, דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003פטור\u0004 עליהם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון \u0005סבור]:\u0006 \u0003חייב.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 שכך \u0003אמר עולא\u0004 (כשיטת ר' יוחנן, רבו): \u0003הכל מודים במוקטרי חוץ שחסרו והעלו בחוץ שהוא פטור. לא נחלקו אלא במוקטרי פנים שחסרו והעלו בחוץ, דמר סבר\u0004 \u0005[שחכם זה\u0006 ר' יוסי \u0005סבור]\u0006 שהוא \u0003פטור, ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' שמעון \u0005סבור]\u0006 שהוא \u0003חייב.\u0004","ומעירים: \u0003ופליגי דאבוה\u0004 \u0005[וחלוקים\u0006 דבריו \u0005של אביו]\u0006 של \u0003שמואל אלישנא קמא\u0004 \u0005[על הלשון הראשונה]\u0006 בשם \u0003עולא.\u0004 שכך \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: כמאן מהדרינן\u0004 \u0005[כ\u0006דעת \u0005מי מחזירים אנו]\u0006 איברים \u0003פוקעין לגבי\u0004 \u0005[אצל]\u0006 ה\u0003מזבח? כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — ש\u0003לא כ\u0004דעת \u0003ר' יוסי,\u0004 שהרי הוא פוטר אם העלה בחוץ איבר חסר של מוקטרי פנים. ומכאן שאיבר כזה (וכגון שנשרף במקצתו ופקע מעל המזבח) אינו ראוי להקטרה בפנים. ואילו ללשון הראשונה של עולא אפילו ר' יוסי מודה שהוא חייב על כך.","\u0003ו\u0004עוד נחלקו ר' יוסי ור' שמעון במשנתנו בדין העלאת קדשים בחוץ, שלדעת ר' יוסי \u0003אינו חייב עד שיעלה\u0004 על מזבח דווקא, ולדעת ר' שמעון — אף אם העלה על הסלע או על האבן חייב. ובהסבר השיטות, \u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ויבן נח מזבח לה'\u0004 ויקח מכל הבהמה הטהורה ומכל העוף הטהור ויעל עולות במזבח\" (בראשית ח, כ), הרי שאין העלאה אלא זו הנעשית על מזבח.","\u0003אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בקרבן שהקריב מנוח אבי שמשון: \u0003\"ויקח מנוח את גדי העזים ואת המנחה ויעל על הצור לה'\"\u0004 (שופטים יג, יט), הרי שיש העלאה אף על הסלע, ובלא מזבח.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' שמעון, \u0005גם כן]\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויבן\u0004 נח \u0003מזבח לה'\"!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 מקרא בא לציין \u0003גובהה בעלמא\u0004 \u0005[גובה בלבד],\u0006 שהיה זה מקום מוגבה מן הקרקע, ולא שהיה זה מזבח בדווקא. וחוזרים ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' יוסי, \u0005גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ויקח מנוח...\u0004 ויעל על הצור\"! ומשיבים: \u0003הוראת שעה היתה\u0004 זו, ואין ללמוד ממנה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ש\u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון, כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 נאמר \"וזרק הכהן את הדם על \u0003מזבח\u0004 ה' \u0003פתח אהל מועד\"\u0004 (ויקרא יז, ו), לומר שדווקא במשכן יש מזבח, ו\u0003אין\u0004 צורך ב\u0003מזבח בבמה\u0004 של יחיד בזמן היתר הבמות, כדי להקריב. \u0003לפיכך\u0004 אם \u0003העלה על הסלע או על האבן\u0004 בבמה — \u0003חייב.\u0004","ויש לתמוה: אם מדובר בשעת היתר הבמות, אם כן \u0003\"יצא\u0004 ידי חובתו\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 אלא: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 הואיל ובשעת היתר במות אין צורך במזבח, \u0003לפיכך בשעת איסור הבמות\u0004 אם \u0003העלה על הסלע או על האבן\u0004 — \u0003חייב.\u0004","ובענין זה של מזבח בבמה בזמן היתר הבמות, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוסי בר' חנינא: קרן\u0004 בכל קצה של מזבח, \u0003וכבש ויסוד וריבוע\u0004 (שיהא המזבח מרובע), שבמקדש אין המזבח כשר בלעדיהם, \u0003מהו\u0004 דינם \u0003שיעכבו בבמה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קרן וכבש וריבוע ויסוד, מעכבין\u0004 בשעת היתר הבמות \u0003בבמה גדולה\u0004 שעושים לכל ישראל, כגון זו שבנוב ושבגבעון, \u0003ואין מעכבין\u0004 \u0003בבמה קטנה\u0004 של אדם פרטי."],["\u0003אחד קדשים כשרין, ואחד קדשים פסולין שהיה פסולן בקודש\u0004 תוך כדי עבודה במקדש, \u0003והקריבן בחוץ\u0004 לעזרה — \u0003חייב\u0004 עליהם משום הקרבה בחוץ.","\u0003המעלה\u0004 (המקריב) שיעור \u0003כזית מן\u0004 בשר \u0003העולה ומן האימורין\u0004 (החלבים) \u0003בחוץ\u0004 — \u0003חייב,\u0004 אף שלא היה בבשר עצמו כשיעור זית.","שנינו במשנתנו שחייבים על העלאתם בחוץ בין של קדשים כשרים ובין של קדשים שנפסלו בקודש. ובמקורה של הלכה זו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת העלאה בחוץ \u0003\"אשר יעלה עלה או זבח.\u0004 ואל פתח אהל מועד לא יביאנו לעשות אותו לה'\" (ויקרא יז, ח—ט). ומסבירים מה בא ללמד כל חלק מן הכתוב: \"עולה\" — \u0003אין לי\u0004 שדין זה נוהג \u0003אלא\u0004 בקרבן \u0003עולה,\u0004 שקרב כולו על המזבח, \u0003מנין לרבות אימורי אשם ואימורי חטאת ואימורי קדשי קדשים ואימורי קדשים קלים,\u0004 שמוקטרים אף הם על המזבח, שאם העלה אותם בחוץ שהוא חייב? \u0003תלמוד לומר: \"זבח\",\u0004 כל שאר הזבחים.","\u0003מנין לרבות\u0004 גם שאר דברים הקרבים על המזבח: \u0003הקומץ\u0004 המנחה, \u0003והלבונה\u0004 (הנקטרת עם הקומץ), \u0003והקטורת\u0004 המוקטרת בכל יום על המזבח הפנימי, \u0003ומנחת כהנים ומנחת\u0004 חביתין של \u0003כהן משיח\u0004 (כהן גדול) הקריבה בכל יום, ששתיהן עולות כליל על המזבח, \u0003ו\u0004כן \u0003המנסך\u0004 בחוץ \u0003שלשת לוגין יין\u0004 (שהוא המועט מכל הנסכים שמנסכים על המזבח), \u0003ושלשת לוגין מים\u0004 שמנסכים על המזבח בחג הסוכות, מנין שחייבים על כל אלה אם העלם בחוץ? \u0003תלמוד לומר: \"ואל פתח אהל מועד לא יביאנו\"\u0004 (ויקרא יז, ט), ללמדנו ש\u0003כל\u0004 \u0003הבא לפתח אהל מועד\u0004 להיות מוקרב על המזבח — \u0003חייבין עליו\u0004 על העלאתו \u0003בחוץ.\u0004","וממשיכים לברר, \u0003ואין לי\u0004 שחייבים \u0003אלא\u0004 על העלאה בחוץ \u0003קדשים כשרים\u0004 שכן הם ראויים להיות מוקרבים על המזבח, \u0003מנין לרבות\u0004 גם קדשים \u0003פסולין\u0004 שהיה פסולם בקודש,","\u0003כגון הלן\u0004 כל הלילה מחוץ למזבח, \u0003והיוצא\u0004 חוץ לעזרה, \u0003והטמא, ושנשחט\u0004 במחשבה להקריבו או לאוכלו \u0003חוץ לזמנו\u0004 \u0003ו\u0004כן במחשבת \u0003חוץ למקומו,\u0004 \u0003ושקבלו פסולין\u0004 לעבודה \u0003וזרקו את דמו,\u0004 וכן \u0003ה\u0004קרבנות שדמיהם \u0003ניתנין למטה\u0004 (מחוט הסיקרא שבמזבח) \u0003שנתנן למעלה,\u0004 \u0003והניתנין למעלה שנתנן למטה, והניתנין בחוץ\u0004 במזבח החיצון \u0003שנתנן בפנים\u0004 בהיכל, \u0003והניתנין בפנים שנתנן בחוץ, ופסח וחטאת שנתנן\u0004 את דמם \u0003שלא לשמן,\u0004","\u0003מנין\u0004 שעל כל אלה חייבים על העלאתם בחוץ, אף שהם פסולים? \u0003תלמוד לומר: \"לא יביאנו לעשות\"\u0004 (ויקרא יז, ט), לומר: \u0003כל המתקבל\u0004 ונעשה \u0003בפתח אהל מועד,\u0004 אפילו בדיעבד — \u0003חייבין עליו בחוץ.\u0004 וכל פסולים אלה, אם עלו על המזבח לא ירדו.","שנינו במשנתנו ש\u0003המעלה כזית מן\u0004 בשר \u0003העולה\u0004 ומן האימורים בחוץ חייב. ונדייק מכאן: \u0003עולה ואימוריה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מצטרפים לשיעור כזית לחייב על העלאה בחוץ. אבל בשר \u0003שלמים ואימוריהן\u0004 — \u0003לא,\u0004 מפני שאין בשר השלמים ראוי ליקרב על המזבח, שהרי הוא נאכל.","ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנתנו \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003עולה ואימוריה מצטרפין ל\u0004שיעור \u0003כזית ל\u0004חייב משום \u0003העלותן בחוץ, ולחייב עליהן משום\u0004 אכילת \u0003פיגול, ו\u0004משום אכילת \u0003נותר וטמא.\u0004 ואם כן יש לדייק גם בברייתא, שדווקא בעולה הדין כן ולא בשלמים.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003העלאת\u0004 חוץ, מובן הדבר: \u0003עולה\u0004 שהיא קריבה \u0003כליל\u0004 על המזבח — \u0003אין\u0004 \u0005[כן]\u0006 מצטרפים הבשר והאימורים, \u0003שלמים\u0004 — \u0003לא\u0004 מצטרף הבשר לאימורים, שהרי אינו קרב על המזבח. \u0003אלא\u0004 לענין אכילת \u0003פיגול ונותר וטמא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אין מצטרפים בשר שלמים ואימוריהם?","\u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה במסכת מעילה\u0005]:\u0006 \u0003כל הפגולין\u0004 (הדברים שנאסרו משום פיגול) \u0003מצטרפין\u0004 לשיעור כזית, לחייב את האוכל מהם, \u0003ו\u0004כן \u0003כל הנותרין מצטרפין.\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003פיגול\u0004 השנוי במשנה זו על דין \u0003פיגול\u0004 השנוי בברייתא, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003נותר\u0004 על דין \u0003נותר!\u0004","ומשיבים: מ\u0003פיגול\u0004 על \u0003פיגול לא קשיא\u0004 \u0005[קשה],\u0006 שכן \u0003כאן\u0004 שבשר השלמים והאימורים מצטרפים, מדובר \u0003ב\u0004אכילת \u0003פיגול,\u0004 שכבר התפגל הקרבן במחשבת חוץ לזמנו. ואילו \u0003כאן\u0004 שאינם מצטרפים, מדובר \u0003במחשבת פיגול,\u0004 שמחשבה להקטיר פחות מכזית אימורים לאחר זמנו, ולאכול פחות מכזית בשר לאחר זמנו — אינה מצטרפת לאסור את הקרבן משום פיגול.","וכן גם הסתירה מדין \u0003נותר\u0004 על דין \u0003נותר לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003כאן\u0004 ששנינו שכל הנותרים מצטרפים, מדובר \u0003ב\u0004אכילת \u0003נותר\u0004 ממש, \u0003כאן\u0004 בברייתא שדייקנו בה שדווקא בעולה הבשר והאימורים מצטרפים לכזית, אבל לא בשלמים, מדובר \u0003ב\u0004מקרה \u0003ש\u0004אבד או נשרף הקרבן, ו\u0003ניתותרו\u0004 חצי כזית מן האימורים וחצי כזית מן הבשר \u0003עד שלא נזרק הדם,\u0004 ולגבי השאלה האם ניתן לזרוק את הדם על אותו כזית.","\u0003ומני\u0004 \u0005[ו\u0006שיטת \u0005מי היא\u0006 ברייתא זו\u0005]?\u0006 שיטת \u0003ר' יהושע היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה,\u0004 חוץ מקרבן עולה, \u0003ש\u0004אבדו או שנטמאו ו\u0003נשתייר בהן כזית בשר\u0004"],["\u0003ו\u0004כן אם נשתייר מהם רק \u0003כזית חלב\u0004 שעולה למזבח — הרי זה \u0003זורק את הדם\u0004 עליהם, ויצא ידי חובת קרבנו.","ואולם אם נשאר מהם רק \u0003חצי זית בשר וחצי זית חלב\u0004 — \u0003אינו זורק\u0004 עליהם \u0003את הדם,\u0004 משום שלא נותר מן הקרבן שיעור ראוי לא לאכילה ולא להקרבה על המזבח. \u0003ובעולה\u0004 אפילו \u0003חצי זית בשר וחצי זית חלב\u0004 — \u0003זורק\u0004 עליה \u0003את הדם, מפני שכולה כליל\u0004 וגם הבשר וגם החלב קרבים על המזבח. \u0003ומנחה אפילו כולה קיימת\u0004 — \u0003לא יזרוק.\u0004","ותוהים: \u0003מנחה מאי עבידתה\u0004 \u0005[מה מעשיה,\u0006 עניינה כאן\u0005],\u0006 והרי אין זריקת דם במנחות? \u0003אמר רב פפא:\u0004 הכוונה היא ל\u0003מנחת נסכים הבאה עם הזבח,\u0004 שאפילו שהיא עצמה כולה קיימת, אין היא נחשבת עיקר הזבח, שיזרקו דמים בשבילה.","\u0003הקומץ\u0004 של המנחה, המוקטר על המזבח, \u0003והלבונה\u0004 הנקטרת עם הקומץ, \u0003והקטרת\u0004 המוקטרת בכל יום על המזבח הפנימי, \u0003ומנחת כהנים\u0004 העולה כולה על המזבח, \u0003ומנחת\u0004 חביתין של \u0003כהן משיח\u0004 (כהן גדול) הקריבה בכל יום כליל על המזבח, \u0003ומנחת נסכים\u0004 הבאה עם הקרבן, ומוקטרת כולה על המזבח, \u0003שהקריב מאחת מהן כזית בחוץ\u0004 לעזרה — \u0003חייב\u0004 משום העלאה בחוץ. \u0003ר' אליעזר פוטר עד שיקריב את כולן\u0004 בשלמותם, כפי שהיה מוקרב כדינו במקדש. \u0003ו\u0004מכל מקום, גם לדעת ר' אליעזר, \u0003כולן\u0004 \u0003שהקריב\u0004 אותם תחילה \u0003בפנים ושייר מהן כזית, ו\u0004לאחר מכן \u0003הקריבו\u0004 את אותו כזית \u0003בחוץ\u0004 — \u0003חייב,\u0004 כיון שבכך היתה נשלמת הקטרה.","\u0003וכולן,\u0004 כל אלה שנשנו במשנתנו, \u0003שחסרו כל שהו\u0004 לפני הקטרתם, ונפסלו בכך, \u0003והקריבו\u0004 אותם כך כפי שהם \u0003בחוץ\u0004 — \u0003פטור.\u0004","\u0003המקריב\u0004 בשר \u0003קדשים\u0004 הנאכלים, \u0003ו\u0004איתם הקריב גם את ה\u0003אימורים\u0004 שלהם, \u0003בחוץ\u0004 — \u0003חייב\u0004 על הקטרת האימורים, למרות שאינו חייב על הבשר.","שנינו במשנה שהמקטיר קטורת בשיעור כזית בחוץ חייב. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המקטיר\u0004 קטורת \u0003כזית בחוץ\u0004 — \u0003חייב,\u0004 אף שאין בה שיעור הקטרה הראוי למקדש, שהוא משקל פרס (חצי מנה). ואילו המקטיר פחות מכשיעור הראוי, כגון \u0003חצי פרס בפנים\u0004 — \u0003פטור.\u0004 ומבררים את האמור בסוף ברייתא זו.","\u0003קא סלקא דעתין\u0004 \u0005[עלה על דעתנו]\u0006 לפרש כך: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פטור\"\u0004 — כוונתו: \u0003פטור זר,\u0004 שמי שאינו כהן, ואסור בעבודה, אם הקטיר במקדש פחות מכשיעור — פטור על כך, משום שלא עשה עבודה כראוי. ואולם על כך יש לתהות: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 והרי \u0003הקטרה היא,\u0004 כפי ששנינו בדין הראשון בברייתא זו, שאם הקטיר כזית בחוץ חייב!","\u0003אמר ר' זירא אמר רב חסדא אמר רב ירמיה בר אבא אמר רב: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פטור\"\u0004 האמור בברייתא? כוונתו: \u0003פטור ציבור,\u0004 שאם הקטירו בכמות זו, אף שאין בה שיעור ראוי, יצאו ידי חובת הקטרה, ושוב אין צריכים להביא קטורת חדשה.","\u0003אמר ר' זירא: אי קשיא\u0004 \u0005[אם קשה]\u0006 \u0003לי\u0004 בהסבר זה — \u0003הא קשיא\u0004 \u0005[\u0006דבר \u0005זה קשה]\u0006 \u0003לי,\u0004 \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רב עלה\u0004 \u0005[עליה]:\u0006 \u0003בהא\u0004 \u0005[ב\u0006הלכה \u0005זו]\u0006 שיוצאים ידי חובת הקטרה בפחות משיעורה המלא, \u0003אפילו ר' אליעזר,\u0004 שפוטר במשנתנו על הקטרה כזו בחוץ, \u0003מודה.\u0004 וקשה לי על שיטתו זו של רב, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' אליעזר\u0004 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003הקטרה היא\u0004 \u0003קאמר\u0004 \u0005[הוא אומר],\u0006 ומשום כך הוא פוטר במשנתנו על הקטרה כזו בחוץ!","\u0003אמר רבה\u0004 בתשובה לשאלת ר' זירא: \u0003בהקטרה\u0004 שנעשית ב\u0003היכל\u0004 על מזבח הזהב פעמיים בכל יום, \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 חכמים ור' אליעזר, \u0005אינם חלוקים]\u0006 שגם אם הקטיר כזית הריהי הקטרה, ויוצאים בה ידי חובה בפנים, וחייבים עליה בחוץ. שכן שיעור פרס אינו מדין תורה אלא מדברי חכמים. ובהקטרה זו עוסקת הברייתא.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 חכמים ור' אליעזר במשנתנו, האם מתחייבים על הקטרה בחוץ בכזית, הרי זה \u0003בהקטרה\u0004 שנעשית ב\u0003פנים\u0004 (בקודש הקודשים) ביום הכיפורים, ובכך נחלקו: \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]\u0006 כי מה שנאמר בענין זה \"ולקח... ו\u0003מלא חפניו\u0004 קטורת סמים דקה והביא מבית לפרוכת\" (ויקרא טז, יב), כוונתו שתהא ההקטרה בשיעור זה \u0003דוקא,\u0004 ולא בפחות ממנו. ולכן אינו חייב בפחות מכך על הקטרת חוץ. ואילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבורים]\u0006 כי \u0003\"מלא חפניו\"\u0004 הריהו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003דוקא\u0004, ואין שיעור זה מעכב את הקטורת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: איך אפשר לומר שלדעת חכמים \"מלא חפניו\" לאו דווקא? \u0003והא כי קא כתיבא\u0004 \u0005[והרי כאשר נאמרה]\u0006 \u0003\"חקה\"\u0004 בסדר עבודת יום הכיפורים (ויקרא טז, לד), אף \u0003בהקטרה\u0004 שב\u0003פנים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 וכל מקום שנאמר בתורה \"חוקה\" הוא מעכב!","\u0003אלא אמר אביי: בהקטרה בפנים כולי עלמא לא פליגי\u0004 \u0005[הכל\u0006 \u0005אינם חלוקים]\u0006 שאם הקטיר פחות משיעור \"מלא חפניו\" שאין זו הקטרה.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 חכמים ור' אליעזר במשנתנו, הרי זה \u0003בהקטרה\u0004 של קטורת הפנים כשעשאה ב\u0003חוץ, מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 לענין זה את דינה של קטורת \u0003פנים\u0004 (של יום הכיפורים) \u0003מ\u0004דינה של קטורת \u0003חוץ\u0004 (שבהיכל). וכשם שהמקטיר את קטורת ההיכל בחוץ חייב אף בכזית, כך המקטיר את קטורת הפנים בחוץ חייב בכזית. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה\u0006 ר' אליעזר \u0005סבור]:\u0006 \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 דין קטורת פנים מקטורת היכל, לענין שיעור העלאה בחוץ.","\u0003אמר רבא\u0004 בסתירת הסברו של אביי: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לענין העלאה בחוץ, אפילו את דינה של עבודת \u0003חוץ\u0004 \u0003מ\u0004דינה של עבודת \u0003חוץ\u0004 אחרת \u0003לא ילפי רבנן\u0004 \u0005[אין חכמים למדים],\u0006 וכי את דינה של עבודת \u0003פנים מ\u0004דינה של עבודת \u0003חוץ מיבעי\u0004 \u0005[\u0006האם \u0005נצרך]\u0006 לומר שלא ילמדו?","ומבררים: \u0003מה היא,\u0004 מהו אותו ענין לימוד עבודת חוץ מעבודת חוץ שהתייחס אליו רבא? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול\u0004 \u0003המעלה\u0004 מחוץ לעזרה \u0003פחות מכזית קומץ ו\u0004כן \u0003פחות מכזית אימורין,\u0004 או \u0003המנסך\u0004 בחוץ \u0003פחות משלשת לוגין יין\u0004 או \u0003פחות משלשה לוגין מים\u0004 בחג הסוכות \u0003יהא חייב? תלמוד לומר\u0004 בדין העלאה בחוץ: \"ואל פתח אהל מועד לא יביאנו \u0003לעשות\u0004 אותו\" (ויקרא יז, ט), דווקא \u0003על השלם\u0004 הוא \u0003חייב, ואינו חייב על החסר.\u0004","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003פחות משלשת לוגין,\u0004 שפטור אם ניסך בהם בחוץ, \u0003דאית בהו\u0004 \u0005[שיש בהם]\u0006 שיעור של \u0003כמה זיתים, ו\u0004בכל זאת \u0003לא ילפי רבנן\u0004 \u0005[אין למדים חכמים]\u0006 \u0003חוץ מחוץ,\u0004 לחייב על ניסוך היין בחוץ בכזית, כדרך שחייבים בקרבנות אחרים הנעשים במזבח החיצון. ובודאי שאין ללמוד דין עבודת פנים מדין עבודת חוץ!","\u0003אלא אמר רבא\u0004 תשובה אחרת לשאלת ר' זירא: מה שאמר רב שעל הקטרת חצי פרס בפנים פטור הציבור מלהקריב שוב, אף לשיטת ר' אליעזר, הרי זה משום שגם לדעתו שיעור הקטרה הריהו בכזית (בין לצאת ידי חובה, ובין להתחייב על הקטרה של כזית בחוץ). ומה שנחלקו ר' אליעזר וחכמים במשנתנו האם מתחייב על הקטרת הקטורת בחוץ כאשר היא חסרה, הרי זה \u0003כגון דקבעינהו\u0004 \u0005[שקבע אותם,\u0006 הניחם\u0005]\u0006 הכהן את \u0003שני חצאי פרס,\u0004 כלומר, את כל הקטורת הראויה להקטרה,"]]};
